# Pillow draws the dials, buttons and chips with smooth edges.  Tk alone draws
# circles without anti-aliasing, which looks stepped.  Without Pillow the app
# still works and falls back to plain Tk drawing.
try:
    from PIL import Image as PILImage
    from PIL import ImageDraw as PILDraw
except Exception:  # pragma: no cover - depends on the installation
    PILImage = None
    PILDraw = None

# Tk itself does not implement the Unicode bidirectional algorithm consistently
# on Windows.  These two small libraries convert Persian text to visual order
# before it is handed to Tk.  They are optional for English/German, but are
# required for correct Persian rendering.
try:
    import arabic_reshaper  # type: ignore[import-not-found]
    try:
        from bidi.algorithm import get_display as bidi_get_display  # type: ignore[import-not-found]
    except ImportError:
        from bidi import get_display as bidi_get_display  # type: ignore[import-not-found]
except ImportError:
    arabic_reshaper = None
    bidi_get_display = None

# Import pywin32 at module load time when available. Besides making tray failures
# easier to diagnose, explicit imports let PyInstaller see the Windows tray
# dependencies instead of relying on imports inside a worker thread.
try:
    import win32api  # type: ignore[import-not-found]
    import win32con  # type: ignore[import-not-found]
    import win32gui  # type: ignore[import-not-found]
except ImportError:
    win32api = None
    win32con = None
    win32gui = None

# Use the mature infi.systray implementation for notification-area mouse/menu
# handling.  The previous hand-written TrackPopupMenu callback worked on some
# Windows builds but repeatedly failed to receive/show right-click menus on
# others.  Import only on Windows because infi.systray itself is Windows-only.
try:
    if platform.system() == "Windows":
        from infi.systray import SysTrayIcon as InfiSysTrayIcon  # type: ignore[import-not-found]
    else:
        InfiSysTrayIcon = None
except (ImportError, OSError):
    InfiSysTrayIcon = None


