# Embedded notification-area icon. infi.systray expects an .ico file path, so
# Taktpause writes this tiny bundled icon to its local application-data folder.
# Keeping the bytes in the source means PyInstaller --onefile needs no extra data file.
TRAY_ICON_B64 = ""

# The same mark as a single 64px PNG. Tk 8.6 can read PNG straight from
# base64, so the window icon and the tray icon are one design.
APP_ICON_PNG_B64 = ""


def ensure_tray_icon(path: Path) -> str | None:
    """Materialize the bundled tray icon and return its path for infi.systray."""
    try:
        raw = base64.b64decode(TRAY_ICON_B64)
        if not path.exists() or path.stat().st_size != len(raw) or path.read_bytes() != raw:
            tmp = path.with_suffix(path.suffix + ".tmp")
            tmp.write_bytes(raw)
            os.replace(tmp, path)
        return str(path)
    except Exception:
        LOGGER.exception("Could not prepare Taktpause tray icon")
        return None
