def resource_path(*parts: str) -> Path:
    """Return the primary bundled-resource path."""
    base = Path(getattr(sys, "_MEIPASS", Path(__file__).resolve().parent))
    return base.joinpath(*parts)


def _translation_paths(language: str) -> list[Path]:
    """Return possible translation locations for source and packaged runs."""
    filename = f"{language}.json"
    candidates = [resource_path("translations", filename)]

    # If PyInstaller data files were not bundled, also allow a translations
    # folder beside the executable. This is useful during private testing.
    if getattr(sys, "frozen", False):
        candidates.append(Path(sys.executable).resolve().parent / "translations" / filename)

    candidates.append(Path(__file__).resolve().parent / "translations" / filename)
    candidates.append(Path.cwd() / "translations" / filename)

    unique: list[Path] = []
    seen: set[str] = set()
    for candidate in candidates:
        key = str(candidate.resolve(strict=False)).lower()
        if key not in seen:
            unique.append(candidate)
            seen.add(key)
    return unique


def load_translations() -> dict[str, dict[str, str]]:
    """Load JSON translations, rejecting stale/incomplete external catalogs."""
    catalogs: dict[str, dict[str, str]] = {}
    for language in ("en", "de", "fa"):
        loaded: dict[str, str] | None = None
        expected_keys = set(EMBEDDED_TRANSLATIONS[language])
        for path in _translation_paths(language):
            if not path.is_file():
                continue
            try:
                candidate = json.loads(path.read_text(encoding="utf-8"))
            except (OSError, ValueError, json.JSONDecodeError):
                logging.getLogger("taktpause").warning("Could not read translation file %s", path, exc_info=True)
                continue
            if not (
                isinstance(candidate, dict)
                and all(isinstance(key, str) and isinstance(value, str) for key, value in candidate.items())
            ):
                logging.getLogger("taktpause").warning("Invalid translation file %s", path)
                continue
            missing = expected_keys - set(candidate)
            extra = set(candidate) - expected_keys
            if missing or extra:
                logging.getLogger("taktpause").warning(
                    "Translation catalog %s is stale: missing=%s, extra=%s; using embedded catalog",
                    path, sorted(missing), sorted(extra),
                )
                continue
            loaded = candidate
            break

        # The embedded copy prevents one-file builds, stale sidecar files, or a
        # partially upgraded installation from exposing raw translation keys.
        catalogs[language] = loaded if loaded is not None else dict(EMBEDDED_TRANSLATIONS[language])
    return catalogs


TEXT: dict[str, dict[str, str]] = load_translations()


