VOICE_TEXT_KEY_TO_CATEGORY = {
    spec["text_key"]: category
    for category, spec in MESSAGE_CATEGORY_SPECS.items()
    if spec.get("kind") == "text" and spec.get("text_key")
}
HUMOR_CONTEXT_TO_CATEGORY = {
    spec["context"]: category
    for category, spec in MESSAGE_CATEGORY_SPECS.items()
    if spec.get("kind") == "humor" and spec.get("context")
}


def built_in_message_lines(language: str, category: str) -> list[str]:
    language = language if language in CUSTOM_MESSAGE_LANGUAGES else "en"
    spec = MESSAGE_CATEGORY_SPECS.get(category, {})
    kind = spec.get("kind")
    if kind == "text":
        key = spec.get("text_key", "")
        text = TEXT.get(language, {}).get(key, TEXT.get("en", {}).get(key, ""))
        return [str(text)] if text else []
    if kind == "activity":
        keys = (
            "activity_distance_body", "activity_hands_body", "activity_walk_body",
            "activity_chest_body", "activity_twist_body", "activity_neck_body",
            "activity_ankle_body", "activity_quiet_body",
        )
        return [str(TEXT.get(language, {}).get(key, TEXT["en"].get(key, ""))) for key in keys]
    if kind == "humor":
        context = spec.get("context", "")
        return list(HUMOR_LINES.get(language, {}).get(context, []))
    return []


