def state_palette(base: dict[str, str], tone: str) -> dict[str, str]:
    """The base light/dark palette, tinted for one timer state."""
    if tone not in {"break", "due"}:
        return base
    family = "dark" if base.get("is_dark") else "light"
    palette = dict(base)
    palette.update(STATE_TONES[family][tone])
    palette["name"] = f"{family}_{tone}"
    return palette


MINI_SIZES = {"small": 112, "medium": 140, "large": 176}
MINI_OPACITY = {"off": 1.0, "light": 0.85, "strong": 0.65}


def _rgba(colour: str, alpha: int = 255) -> tuple[int, int, int, int]:
    value = colour.lstrip("#")
    return (int(value[0:2], 16), int(value[2:4], 16), int(value[4:6], 16), max(0, min(255, int(alpha))))


def _png_data(image: Any) -> str:
    import io

    buffer = io.BytesIO()
    image.save(buffer, format="PNG")
    return base64.b64encode(buffer.getvalue()).decode("ascii")


_PILL_CACHE: dict[tuple[Any, ...], str] = {}


def pill_image_data(
    width: int, height: int, fill: str, outline: str | None = None, radius: float | None = None,
) -> str | None:
    """A smooth rounded button/chip background as base64 PNG, or None without Pillow."""
    if PILImage is None:
        return None
    width, height = max(4, int(width)), max(4, int(height))
    key = (width, height, fill, outline, radius)
    cached = _PILL_CACHE.get(key)
    if cached is not None:
        return cached
    scale = 4
    big = PILImage.new("RGBA", (width * scale, height * scale), (0, 0, 0, 0))
    draw = PILDraw.Draw(big)
    corner = (height / 2.0 if radius is None else float(radius)) * scale
    draw.rounded_rectangle(
        [0, 0, width * scale - 1, height * scale - 1],
        radius=corner,
        fill=_rgba(fill),
        outline=_rgba(outline) if outline else None,
        width=scale if outline else 0,
    )
    data = _png_data(big.resize((width, height), PILImage.LANCZOS))
    if len(_PILL_CACHE) > 400:
        _PILL_CACHE.clear()
    _PILL_CACHE[key] = data
    return data


def dial_geometry(size: int) -> dict[str, float]:
    """Radii and widths of the dial, in pixels of the final image."""
    face_r = size / 2.0 - 1.0
    ring_w = max(4.0, size * 0.03)
    ring_r = face_r - size * 0.035 - ring_w / 2.0
    tick_outer = ring_r - ring_w / 2.0 - size * 0.03
    major = size * 0.036
    wedge_r = tick_outer - major - size * 0.022
    return {
        "face_r": face_r, "ring_w": ring_w, "ring_r": ring_r, "tick_outer": tick_outer,
        "major": major, "minor": size * 0.018, "wedge_r": wedge_r,
    }


def dial_image_data(
    size: int,
    *,
    fraction: float,
    ring: str,
    wedge: str,
    face: str,
    border: str,
    track: str,
    tick: str,
    tick_major: str,
    overtime: bool = False,
    ring_alpha: int = 255,
    show_hand: bool = True,
    ticks: bool = True,
    matte: str | None = None,
) -> str | None:
    """Draw a countdown dial as a smooth base64 PNG.

    Remaining time is shown three ways at once: a coloured path on the outer
    ring, a soft wedge (like a kitchen countdown timer) and a short hand at
    the current position.  ``matte`` fills everything outside the circle with
    one colour and cuts the edge hard; the floating timer needs that for its
    round window.  Returns None when Pillow is missing.
    """
    if PILImage is None:
        return None
    size = max(16, int(size))
    scale = 3
    big = size * scale
    g = {key: value * scale for key, value in dial_geometry(size).items()}
    centre = big / 2.0
    image = PILImage.new("RGBA", (big, big), (0, 0, 0, 0))
    draw = PILDraw.Draw(image)

    def box(radius: float) -> list[float]:
        return [centre - radius, centre - radius, centre + radius, centre + radius]

    def point(radius: float, fraction_of_turn: float) -> tuple[float, float]:
        angle = math.radians(-90.0 + 360.0 * fraction_of_turn)
        return centre + radius * math.cos(angle), centre + radius * math.sin(angle)

    fraction = max(0.0, min(1.0, float(fraction)))
    draw.ellipse(box(g["face_r"]), fill=_rgba(face), outline=_rgba(border), width=scale)
    ring_outer = g["ring_r"] + g["ring_w"] / 2.0
    draw.ellipse(box(ring_outer), outline=_rgba(track), width=int(round(g["ring_w"])))
    if 0.0 < fraction < 0.9995:
        draw.pieslice(box(g["wedge_r"]), -90.0, -90.0 + 360.0 * fraction, fill=_rgba(wedge))
    elif fraction >= 0.9995:
        draw.ellipse(box(g["wedge_r"]), fill=_rgba(wedge))
    if ticks:
        for index in range(12):
            quarter = index % 3 == 0
            length = g["major"] if quarter else g["minor"]
            x1, y1 = point(g["tick_outer"] - length, index / 12.0)
            x2, y2 = point(g["tick_outer"], index / 12.0)
            width = max(scale, (size * (0.0085 if quarter else 0.005)) * scale)
            colour = _rgba(tick_major if quarter else tick)
            draw.line([x1, y1, x2, y2], fill=colour, width=int(round(width)))
            for x, y in ((x1, y1), (x2, y2)):
                draw.ellipse([x - width / 2, y - width / 2, x + width / 2, y + width / 2], fill=colour)
    ring_colour = _rgba(ring, ring_alpha)
    if overtime or fraction >= 0.9995:
        draw.ellipse(box(ring_outer), outline=ring_colour, width=int(round(g["ring_w"])))
    elif fraction > 0.0:
        draw.arc(box(ring_outer), -90.0, -90.0 + 360.0 * fraction, fill=ring_colour, width=int(round(g["ring_w"])))
        cap = g["ring_w"] / 2.0
        for end in (0.0, fraction):
            x, y = point(g["ring_r"], end)
            draw.ellipse([x - cap, y - cap, x + cap, y + cap], fill=ring_colour)
    if show_hand and 0.0 < fraction < 0.9995:
        hand_w = max(2.0 * scale, size * 0.011 * scale)
        x1, y1 = point(g["wedge_r"] * 0.9, fraction)
        x2, y2 = point(g["wedge_r"] + size * 0.012 * scale, fraction)
        draw.line([x1, y1, x2, y2], fill=_rgba(ring), width=int(round(hand_w)))
        for x, y, r in ((x1, y1, hand_w / 2), (x2, y2, size * 0.02 * scale)):
            draw.ellipse([x - r, y - r, x + r, y + r], fill=_rgba(ring))
    small = image.resize((size, size), PILImage.LANCZOS)
    if matte is not None:
        backdrop = PILImage.new("RGBA", (size, size), _rgba(face))
        backdrop.alpha_composite(small)
        mask = PILImage.new("L", (size, size), 0)
        mask_draw = PILDraw.Draw(mask)
        for y, x, width in circle_scanlines(size):
            mask_draw.line([x, y, x + width - 1, y], fill=255)
        result = PILImage.new("RGBA", (size, size), _rgba(matte))
        result.paste(backdrop, (0, 0), mask)
        small = result.convert("RGB")
    return _png_data(small)


class ChartPen:
    """Draws chart shapes smoothly with Pillow, or plainly on the Tk canvas without it.

    Shapes go into one picture behind the canvas text, so text stays crisp
    and selectable areas are handled by simple hit lists in the caller.
    """

    def __init__(self, canvas: Any, width: float, height: float) -> None:
        self.canvas = canvas
        self.width = max(1, int(width))
        self.height = max(1, int(height))
        self.scale = 3
        self.image = None
        if PILImage is not None:
            self.image = PILImage.new("RGBA", (self.width * self.scale, self.height * self.scale), (0, 0, 0, 0))
            self.draw = PILDraw.Draw(self.image)

    def rect(self, x1: float, y1: float, x2: float, y2: float, fill: str | None,
             radius: float = 0.0, outline: str | None = None, width: float = 1.0) -> None:
        if x2 - x1 <= 0.05 or y2 - y1 <= 0.05:
            return
        if self.image is None:
            self.canvas.create_rectangle(x1, y1, x2, y2, fill=fill or "", outline=outline or "", width=width if outline else 0)
            return
        k = self.scale
        r = max(0.0, min(radius, (x2 - x1) / 2.0, (y2 - y1) / 2.0)) * k
        self.draw.rounded_rectangle(
            [x1 * k, y1 * k, max(x1 * k, x2 * k - 1), max(y1 * k, y2 * k - 1)], radius=r,
            fill=_rgba(fill) if fill else None, outline=_rgba(outline) if outline else None,
            width=max(1, int(width * k)) if outline else 0,
        )

    def line(self, x1: float, y1: float, x2: float, y2: float, fill: str, width: float = 1.0, dash: float = 0.0) -> None:
        if self.image is None:
            self.canvas.create_line(x1, y1, x2, y2, fill=fill, width=width, dash=(4, 3) if dash else None)
            return
        k = self.scale
        if not dash:
            self.draw.line([x1 * k, y1 * k, x2 * k, y2 * k], fill=_rgba(fill), width=max(1, int(width * k)))
            return
        length = math.hypot(x2 - x1, y2 - y1)
        steps = max(1, int(length / (dash * 2)))
        for index in range(steps):
            a = index / steps
            b = min(1.0, a + 0.5 / steps)
            self.draw.line(
                [(x1 + (x2 - x1) * a) * k, (y1 + (y2 - y1) * a) * k, (x1 + (x2 - x1) * b) * k, (y1 + (y2 - y1) * b) * k],
                fill=_rgba(fill), width=max(1, int(width * k)),
            )

    def circle(self, cx: float, cy: float, radius: float, fill: str, outline: str | None = None, width: float = 1.0) -> None:
        if self.image is None:
            self.canvas.create_oval(cx - radius, cy - radius, cx + radius, cy + radius, fill=fill, outline=outline or "")
            return
        k = self.scale
        self.draw.ellipse(
            [(cx - radius) * k, (cy - radius) * k, (cx + radius) * k, (cy + radius) * k],
            fill=_rgba(fill), outline=_rgba(outline) if outline else None, width=max(1, int(width * k)) if outline else 0,
        )

    def finish(self) -> None:
        """Place the picture behind all text items on the canvas."""
        if self.image is None:
            return
        data = _png_data(self.image.resize((self.width, self.height), PILImage.LANCZOS))
        picture = tk.PhotoImage(master=self.canvas, data=data)
        item = self.canvas.create_image(0, 0, image=picture, anchor="nw")
        self.canvas.tag_lower(item)
        self.canvas._chart_picture = picture


def track_image_data(width: int, height: int, fraction: float, *, track: str, fill: str, handle: str, face: str) -> str | None:
    """A smooth horizontal timeline with a draggable handle (fraction 0 = left)."""
    if PILImage is None:
        return None
    width, height = max(20, int(width)), max(12, int(height))
    scale = 3
    image = PILImage.new("RGBA", (width * scale, height * scale), (0, 0, 0, 0))
    draw = PILDraw.Draw(image)
    mid = height * scale / 2.0
    thickness = max(4, height * 0.22) * scale
    radius = height * 0.36 * scale
    left, right = radius + scale, width * scale - radius - scale
    x = left + (right - left) * max(0.0, min(1.0, fraction))
    draw.rounded_rectangle([left, mid - thickness / 2, right, mid + thickness / 2], radius=thickness / 2, fill=_rgba(track))
    draw.rounded_rectangle([x, mid - thickness / 2, right, mid + thickness / 2], radius=thickness / 2, fill=_rgba(fill))
    draw.ellipse([x - radius, mid - radius, x + radius, mid + radius], fill=_rgba(face), outline=_rgba(handle), width=int(round(radius * 0.36)))
    return _png_data(image.resize((width, height), PILImage.LANCZOS))


LOGGER = logging.getLogger("taktpause")


class TimerState(str, Enum):
    READY = "ready"
    WORKING = "working"
    WORK_DUE = "work_due"
    RESTING = "resting"
    REST_COMPLETE = "rest_complete"
    PAUSED = "paused"


@dataclass
class TickResult:
    work_seconds: float = 0.0
    break_seconds: float = 0.0
    event: str | None = None


class TimerEngine:
    """Pure timer state. The UI supplies elapsed monotonic seconds."""

    def __init__(self) -> None:
        self.state = TimerState.READY
        self.paused_from: TimerState | None = None
        self.effort = "moderate"
        self.rhythm = "balanced"
        self.planned_work_minutes = 35
        self.planned_break_minutes = 5
        self.block_seconds = 0.0
        self.remaining_seconds = 0.0
        self.overtime_seconds = 0.0
        self.work_since_long_break = 0.0
        self.work_counter_at_break_start = 0.0
        self.work_block_elapsed = 0.0
        self.break_elapsed = 0.0

    @property
    def active(self) -> bool:
        return self.state != TimerState.READY

    @property
    def counting(self) -> bool:
        return self.state in {
            TimerState.WORKING,
            TimerState.WORK_DUE,
            TimerState.RESTING,
            TimerState.REST_COMPLETE,
        }

    @property
    def is_work_context(self) -> bool:
        state = self.paused_from if self.state == TimerState.PAUSED else self.state
        return state in {TimerState.WORKING, TimerState.WORK_DUE}

    def start_work(
        self,
        minutes: int,
        effort: str,
        already_seconds: float = 0.0,
        planned_break_minutes: int | None = None,
        rhythm: str | None = None,
    ) -> None:
        self.effort = effort
        work_minutes = max(1, int(minutes))
        self.planned_work_minutes = work_minutes
        if planned_break_minutes is not None:
            self.planned_break_minutes = max(1, int(planned_break_minutes))
        if rhythm is not None:
            self.rhythm = normalize_rhythm(rhythm, effort)
        self.block_seconds = float(work_minutes * 60)
        self.work_since_long_break += max(0.0, already_seconds)
        self.work_block_elapsed = max(0.0, already_seconds)
        self.remaining_seconds = max(0.0, self.block_seconds - already_seconds)
        self.overtime_seconds = max(0.0, already_seconds - self.block_seconds)
        self.state = TimerState.WORK_DUE if self.remaining_seconds == 0 else TimerState.WORKING
        self.paused_from = None

    def start_break(self, minutes: int) -> None:
        break_minutes = max(1, int(minutes))
        self.work_counter_at_break_start = self.work_since_long_break
        self.block_seconds = float(break_minutes * 60)
        self.remaining_seconds = self.block_seconds
        self.overtime_seconds = 0.0
        self.break_elapsed = 0.0
        self.state = TimerState.RESTING
        self.paused_from = None

    def tick(self, elapsed: float, long_break_seconds: float) -> TickResult:
        elapsed = max(0.0, elapsed)
        result = TickResult()
        if self.state in {TimerState.WORKING, TimerState.WORK_DUE}:
            result.work_seconds = elapsed
            self.work_since_long_break += elapsed
            self.work_block_elapsed += elapsed
            if self.state == TimerState.WORKING:
                self.remaining_seconds -= elapsed
                if self.remaining_seconds <= 0:
                    self.overtime_seconds = -self.remaining_seconds
                    self.remaining_seconds = 0.0
                    self.state = TimerState.WORK_DUE
                    result.event = "work_due"
            else:
                self.overtime_seconds += elapsed
        elif self.state == TimerState.RESTING:
            result.break_seconds = elapsed
            self.break_elapsed += elapsed
            if self.break_elapsed >= long_break_seconds:
                self.work_since_long_break = 0.0
            self.remaining_seconds -= elapsed
            if self.remaining_seconds <= 0:
                self.overtime_seconds = -self.remaining_seconds
                self.remaining_seconds = 0.0
                self.state = TimerState.REST_COMPLETE
                result.event = "rest_complete"
        elif self.state == TimerState.REST_COMPLETE:
            # Show unattended overtime, but do not let a forgotten app inflate history.
            self.overtime_seconds += elapsed
        return result

    def pause(self) -> None:
        if self.counting:
            self.paused_from = self.state
            self.state = TimerState.PAUSED

    def resume(self) -> None:
        if self.state == TimerState.PAUSED and self.paused_from:
            self.state = self.paused_from
            self.paused_from = None

    def snooze_work(self, seconds: int = 300) -> None:
        if self.state == TimerState.WORK_DUE:
            self.state = TimerState.WORKING
            self.block_seconds = float(seconds)
            self.remaining_seconds = float(seconds)
            self.overtime_seconds = 0.0

    def extend_break(self, seconds: int = 300) -> None:
        if self.state in {TimerState.RESTING, TimerState.REST_COMPLETE}:
            self.state = TimerState.RESTING
            self.block_seconds += float(seconds)
            self.remaining_seconds += float(seconds)
            self.overtime_seconds = 0.0

    def finish(self, preserve_work_counter: bool = True) -> None:
        work_counter = self.work_since_long_break if preserve_work_counter else 0.0
        self.__init__()
        self.work_since_long_break = work_counter

    def snapshot(self) -> dict[str, Any]:
        return {
            "state": self.state.value,
            "paused_from": self.paused_from.value if self.paused_from else None,
            "effort": self.effort,
            "rhythm": self.rhythm,
            "planned_work_minutes": self.planned_work_minutes,
            "planned_break_minutes": self.planned_break_minutes,
            "block_seconds": self.block_seconds,
            "remaining_seconds": self.remaining_seconds,
            "overtime_seconds": self.overtime_seconds,
            "work_since_long_break": self.work_since_long_break,
            "work_counter_at_break_start": self.work_counter_at_break_start,
            "work_block_elapsed": self.work_block_elapsed,
            "break_elapsed": self.break_elapsed,
        }

    def restore(self, data: dict[str, Any], pause_active: bool = True) -> None:
        saved_state = TimerState(data.get("state", TimerState.READY.value))
        saved_paused = data.get("paused_from")
        self.state = saved_state
        self.paused_from = TimerState(saved_paused) if saved_paused else None
        self.effort = str(data.get("effort", "moderate"))
        self.rhythm = normalize_rhythm(
            str(data.get("rhythm", "balanced")), self.effort
        )
        self.planned_work_minutes = max(1, int(data.get("planned_work_minutes", 35)))
        self.planned_break_minutes = max(1, int(data.get("planned_break_minutes", 5)))
        self.block_seconds = float(data.get("block_seconds", 0.0))
        self.remaining_seconds = max(0.0, float(data.get("remaining_seconds", 0.0)))
        self.overtime_seconds = max(0.0, float(data.get("overtime_seconds", 0.0)))
        self.work_since_long_break = max(0.0, float(data.get("work_since_long_break", 0.0)))
        self.work_counter_at_break_start = max(
            0.0,
            float(data.get("work_counter_at_break_start", self.work_since_long_break)),
        )
        fallback_work_elapsed = (
            max(0.0, self.block_seconds - self.remaining_seconds) + self.overtime_seconds
            if saved_state in {TimerState.WORKING, TimerState.WORK_DUE}
            else self.planned_work_minutes * 60.0
        )
        self.work_block_elapsed = max(
            0.0, float(data.get("work_block_elapsed", fallback_work_elapsed))
        )
        self.break_elapsed = max(0.0, float(data.get("break_elapsed", 0.0)))
        if pause_active and self.state in {TimerState.WORKING, TimerState.RESTING}:
            self.paused_from = self.state
            self.state = TimerState.PAUSED



def _bounded_recovery_copy(source: Path, destination: Path, limit: int = 2 * 1024 * 1024) -> None:
    """Preserve a small diagnostic copy without allowing recovery files to grow forever."""
    destination.parent.mkdir(parents=True, exist_ok=True)
    with source.open("rb") as src, destination.open("wb") as dst:
        remaining = max(1, min(int(limit), DATA_FILE_HARD_LIMIT_BYTES - 1024))
        while remaining > 0:
            chunk = src.read(min(64 * 1024, remaining))
            if not chunk:
                break
            dst.write(chunk)
            remaining -= len(chunk)


def _compact_event_file(path: Path) -> bool:
    """Keep newest event records while preserving their stable sequence ids.

    The old event format used physical line numbers as interval ids. During the
    first compaction we persist that number as ``seq`` before dropping older
    records, so historical correction references do not change when the file is
    rewritten. Daily totals remain in history.json independently of this detail.
    """
    try:
        if not path.is_file() or path.stat().st_size <= EVENT_COMPACT_TRIGGER_BYTES:
            return False
        original_size = path.stat().st_size
        valid: list[tuple[dict[str, Any], bytes]] = []
        with path.open("r", encoding="utf-8", errors="replace") as stream:
            for line_number, raw_line in enumerate(stream, start=1):
                try:
                    item = json.loads(raw_line)
                except (json.JSONDecodeError, TypeError, ValueError):
                    continue
                if not isinstance(item, dict):
                    continue
                item = dict(item)
                try:
                    sequence = int(item.get("seq", line_number))
                except (TypeError, ValueError):
                    sequence = line_number
                item["seq"] = max(1, sequence)
                encoded = (json.dumps(item, ensure_ascii=False, separators=(",", ":")) + "\n").encode("utf-8")
                valid.append((item, encoded))

        kept: deque[bytes] = deque()
        kept_size = 0
        for _item, encoded in reversed(valid):
            if kept and kept_size + len(encoded) > EVENT_COMPACT_TARGET_BYTES:
                break
            if len(encoded) > DATA_FILE_HARD_LIMIT_BYTES:
                continue
            kept.appendleft(encoded)
            kept_size += len(encoded)
        payload = b"".join(kept)

        handle, temp_name = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=path.parent)
        try:
            with os.fdopen(handle, "wb") as temp:
                temp.write(payload)
                temp.flush()
                os.fsync(temp.fileno())
            os.replace(temp_name, path)
        finally:
            Path(temp_name).unlink(missing_ok=True)
        LOGGER.info(
            "Compacted event history from %.1f MiB to %.1f MiB",
            original_size / 1048576,
            len(payload) / 1048576,
        )
        return True
    except (OSError, UnicodeError):
        LOGGER.exception("Could not compact event history")
        return False


def _path_size(path: Path) -> int:
    try:
        if path.is_file():
            return path.stat().st_size
        if path.is_dir():
            return sum(item.stat().st_size for item in path.rglob("*") if item.is_file())
    except OSError:
        return 0
    return 0


def maintain_storage_limits(data_dir: Path) -> None:
    """Bound Taktpause-managed local storage without deleting durable current data."""
    try:
        data_dir.mkdir(parents=True, exist_ok=True)
        _compact_event_file(data_dir / "events.jsonl")

        backups = data_dir / "backups"
        if backups.is_dir():
            daily = sorted(backups.glob("history-*.json"), key=lambda p: p.stat().st_mtime, reverse=True)
            for old in daily[DAILY_BACKUP_KEEP:]:
                old.unlink(missing_ok=True)
            upgrades = sorted(
                [p for p in backups.glob("upgrade-*") if p.is_dir()],
                key=lambda p: p.stat().st_mtime,
                reverse=True,
            )
            for old in upgrades[UPGRADE_BACKUP_KEEP:]:
                shutil.rmtree(old, ignore_errors=True)

        damaged = sorted(
            [p for p in data_dir.glob("*.damaged-*") if p.is_file()],
            key=lambda p: p.stat().st_mtime,
            reverse=True,
        )
        for old in damaged[RECOVERY_FILE_KEEP:]:
            old.unlink(missing_ok=True)

        # Any disposable managed file that somehow exceeds the single-file limit
        # is removed rather than allowed to grow without bound. Current durable
        # JSON files and the active event log are never deleted here.
        essential = {
            "settings.json", "history.json", "task_history.json", "weekly_notes.json",
            "current_session.json", "custom_messages.json", "events.jsonl", "taktpause_tray.ico",
        }
        for item in data_dir.rglob("*"):
            if not item.is_file():
                continue
            if item.parent == data_dir and item.name in essential:
                continue
            try:
                if item.stat().st_size > DATA_FILE_HARD_LIMIT_BYTES:
                    item.unlink(missing_ok=True)
            except OSError:
                pass

        total = _path_size(data_dir)
        if total <= DATA_DIR_BUDGET_BYTES:
            return
        candidates: list[Path] = []
        if backups.is_dir():
            candidates.extend([p for p in backups.iterdir() if p.exists()])
        candidates.extend([p for p in data_dir.glob("*.damaged-*") if p.is_file()])
        candidates.extend([p for p in data_dir.glob("taktpause.log.*") if p.is_file()])
        candidates.sort(key=lambda p: p.stat().st_mtime if p.exists() else 0)
        for candidate in candidates:
            if total <= DATA_DIR_BUDGET_BYTES:
                break
            size = _path_size(candidate)
            try:
                if candidate.is_dir():
                    shutil.rmtree(candidate, ignore_errors=True)
                else:
                    candidate.unlink(missing_ok=True)
                total = max(0, total - size)
            except OSError:
                continue
    except OSError:
        LOGGER.exception("Could not maintain local storage limits")


class JsonStore:
    def __init__(self, path: Path, default: dict[str, Any]) -> None:
        self.path = path
        self.default = default
        self.loaded_keys: set[str] = set()
        self.load_error: str | None = None
        self.recovery_path: Path | None = None
        self.data = self._load()

    def _load(self) -> dict[str, Any]:
        try:
            loaded = json.loads(self.path.read_text(encoding="utf-8"))
            if not isinstance(loaded, dict):
                raise ValueError("Expected a JSON object")
            self.loaded_keys = set(loaded)
            result = copy.deepcopy(self.default)
            result.update(loaded)
            return result
        except FileNotFoundError:
            return copy.deepcopy(self.default)
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            self.load_error = str(exc)
            if self.path.is_file():
                timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")
                self.recovery_path = self.path.with_name(
                    f"{self.path.stem}.damaged-{timestamp}{self.path.suffix}"
                )
                try:
                    _bounded_recovery_copy(self.path, self.recovery_path)
                    self.path.unlink(missing_ok=True)
                except OSError:
                    self.recovery_path = None
                    LOGGER.exception("Could not preserve unreadable file %s", self.path)
            LOGGER.warning("Could not load %s: %s", self.path, exc)
            return copy.deepcopy(self.default)

    def save(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        payload = json.dumps(self.data, ensure_ascii=False, separators=(",", ":"))
        encoded = payload.encode("utf-8")
        if len(encoded) > DATA_FILE_HARD_LIMIT_BYTES:
            LOGGER.error("Refusing to write oversized local data file %s (%.1f MiB)", self.path.name, len(encoded) / 1048576)
            return
        handle, temporary_name = tempfile.mkstemp(
            prefix=f".{self.path.name}.", suffix=".tmp", dir=self.path.parent
        )
        try:
            with os.fdopen(handle, "wb") as temporary:
                temporary.write(encoded)
                temporary.flush()
                os.fsync(temporary.fileno())
            os.replace(temporary_name, self.path)
        finally:
            try:
                Path(temporary_name).unlink(missing_ok=True)
            except OSError:
                pass


class CustomMessageStore(JsonStore):
    """Small, bounded per-language overrides for Taktpause's user-facing voice."""

    def __init__(self, path: Path) -> None:
        super().__init__(path, {"languages": {language: {} for language in CUSTOM_MESSAGE_LANGUAGES}})
        self.data = self._normalized(self.data)

    @staticmethod
    def _normalized(payload: Any) -> dict[str, Any]:
        result: dict[str, Any] = {"languages": {language: {} for language in CUSTOM_MESSAGE_LANGUAGES}}
        raw_languages = payload.get("languages", {}) if isinstance(payload, dict) else {}
        if not isinstance(raw_languages, dict):
            return result
        for language in CUSTOM_MESSAGE_LANGUAGES:
            raw_categories = raw_languages.get(language, {})
            if not isinstance(raw_categories, dict):
                continue
            clean_categories: dict[str, Any] = {}
            for category, raw_entry in raw_categories.items():
                if category not in MESSAGE_CATEGORY_SPECS or not isinstance(raw_entry, dict):
                    continue
                raw_lines = raw_entry.get("lines", [])
                lines: list[str] = []
                if isinstance(raw_lines, list):
                    for raw_line in raw_lines[:CUSTOM_MESSAGE_MAX_LINES]:
                        if not isinstance(raw_line, str):
                            continue
                        line = raw_line.strip()[:CUSTOM_MESSAGE_MAX_CHARS]
                        if line:
                            lines.append(line)
                if not lines:
                    continue
                clean_categories[category] = {
                    "enabled": bool(raw_entry.get("enabled", False)),
                    "lines": lines,
                }
            result["languages"][language] = clean_categories
        return result

    def active_lines(self, language: str, category: str) -> list[str]:
        language = language if language in CUSTOM_MESSAGE_LANGUAGES else "en"
        entry = self.data.get("languages", {}).get(language, {}).get(category, {})
        if not isinstance(entry, dict) or not bool(entry.get("enabled")):
            return []
        lines = entry.get("lines", [])
        return list(lines) if isinstance(lines, list) else []

    def replace_data(self, payload: Any) -> None:
        self.data = self._normalized(payload)


def _iso_timestamp_sort_value(value: Any) -> float:
    """Return an absolute-time sort value for an ISO timestamp, or -inf if invalid."""
    try:
        parsed = datetime.fromisoformat(str(value or ""))
        return parsed.timestamp()
    except (TypeError, ValueError, OSError, OverflowError):
        return float("-inf")


class TaskHistoryStore(JsonStore):
    """Small local MRU list used only for task-name autocomplete."""

    def __init__(self, path: Path) -> None:
        super().__init__(path, {"tasks": []})
        self._sanitize_tasks()

    @staticmethod
    def _clean_name(value: Any) -> str:
        # Entry widgets cannot contain newlines, but normalize whitespace anyway so
        # accidental double spaces do not create separate autocomplete records.
        return re.sub(r"\s+", " ", str(value or "")).strip()[:160]

    def _sanitize_tasks(self) -> None:
        raw_tasks = self.data.get("tasks")
        clean: list[dict[str, Any]] = []
        seen: set[str] = set()
        if isinstance(raw_tasks, list):
            for raw in raw_tasks:
                if isinstance(raw, str):
                    name = self._clean_name(raw)
                    count = 1
                    last_used = ""
                elif isinstance(raw, dict):
                    name = self._clean_name(raw.get("name", ""))
                    try:
                        count = max(1, int(raw.get("count", 1)))
                    except (TypeError, ValueError):
                        count = 1
                    last_used = str(raw.get("last_used", ""))
                else:
                    continue
                key = name.casefold()
                if not name or key in seen:
                    continue
                seen.add(key)
                clean.append({"name": name, "count": count, "last_used": last_used})
        clean.sort(key=lambda item: str(item.get("last_used", "")), reverse=True)
        self.data["tasks"] = clean[:TASK_HISTORY_LIMIT]

    def remember(self, name: str) -> None:
        """Remember a task only once the user actually starts a session with it."""
        cleaned = self._clean_name(name)
        if not cleaned:
            return
        key = cleaned.casefold()
        tasks = self.data.setdefault("tasks", [])
        existing: dict[str, Any] | None = None
        if isinstance(tasks, list):
            for item in tasks:
                if isinstance(item, dict) and self._clean_name(item.get("name", "")).casefold() == key:
                    existing = item
                    break
        count = 1
        if existing is not None:
            try:
                count = max(1, int(existing.get("count", 1))) + 1
            except (TypeError, ValueError):
                count = 2
            tasks.remove(existing)
        record = {
            "name": cleaned,
            "count": count,
            "last_used": datetime.now().isoformat(timespec="seconds"),
        }
        tasks.insert(0, record)
        del tasks[TASK_HISTORY_LIMIT:]
        self.save()

    def suggestions(self, query: str, limit: int = TASK_SUGGESTION_LIMIT) -> list[str]:
        """Return recent tasks or matching tasks, balancing frequency and recency."""
        cleaned_query = self._clean_name(query).casefold()
        tasks = self.data.get("tasks", [])
        if not isinstance(tasks, list):
            return []
        safe_limit = max(1, int(limit))
        if not cleaned_query:
            # Autofill-style behavior: focusing an empty task field should show
            # recently used tasks immediately instead of requiring a first letter.
            recent: list[str] = []
            for item in tasks:
                if not isinstance(item, dict):
                    continue
                name = self._clean_name(item.get("name", ""))
                if name:
                    recent.append(name)
                if len(recent) >= safe_limit:
                    break
            return recent
        ranked: list[tuple[int, int, int, str]] = []
        for recency, item in enumerate(tasks):
            if not isinstance(item, dict):
                continue
            name = self._clean_name(item.get("name", ""))
            if not name:
                continue
            folded = name.casefold()
            if folded == cleaned_query:
                bucket = 0
            elif folded.startswith(cleaned_query):
                bucket = 1
            elif any(part.startswith(cleaned_query) for part in folded.split()):
                bucket = 2
            elif cleaned_query in folded:
                bucket = 3
            else:
                continue
            try:
                count = max(1, int(item.get("count", 1)))
            except (TypeError, ValueError):
                count = 1
            ranked.append((bucket, -count, recency, name))
        ranked.sort()
        return [name for _bucket, _count, _recency, name in ranked[:safe_limit]]

    def ensure(self, name: str, last_used: str = "") -> bool:
        """Add a task without increasing its use count if it is not already known."""
        cleaned = self._clean_name(name)
        if not cleaned:
            return False
        key = cleaned.casefold()
        tasks = self.data.setdefault("tasks", [])
        if not isinstance(tasks, list):
            tasks = []
            self.data["tasks"] = tasks
        for item in tasks:
            if isinstance(item, dict) and self._clean_name(item.get("name", "")).casefold() == key:
                return False
        tasks.insert(
            0,
            {
                "name": cleaned,
                "count": 1,
                "last_used": str(last_used or datetime.now().isoformat(timespec="seconds")),
            },
        )
        del tasks[TASK_HISTORY_LIMIT:]
        self._sanitize_tasks()
        self.save()
        return True

    def sync_from_events(self, event_path: Path) -> int:
        """Recover task autocomplete history from local session events.

        0.10.1 began writing the task name into event records. Rebuilding from
        session_started/session_restored makes autocomplete survive a missing or
        damaged task_history.json and also imports tasks used earlier in 0.10.x
        whenever those task-bearing events are available.
        """
        if not event_path.is_file():
            return 0
        usage: dict[str, dict[str, Any]] = {}
        seen_sessions: set[str] = set()
        try:
            with event_path.open("r", encoding="utf-8") as stream:
                for line_number, raw_line in enumerate(stream, start=1):
                    try:
                        record = json.loads(raw_line)
                    except (json.JSONDecodeError, TypeError, ValueError):
                        continue
                    if not isinstance(record, dict):
                        continue
                    if record.get("event") not in {"session_started", "session_restored"}:
                        continue
                    name = self._clean_name(record.get("task", ""))
                    if not name:
                        continue
                    session_id = str(record.get("session_id") or "")
                    session_key = session_id or f"line:{line_number}"
                    if session_key in seen_sessions:
                        continue
                    seen_sessions.add(session_key)
                    key = name.casefold()
                    at = str(record.get("at", ""))
                    current = usage.get(key)
                    if current is None:
                        usage[key] = {"name": name, "count": 1, "last_used": at}
                    else:
                        current["count"] = int(current.get("count", 1)) + 1
                        if _iso_timestamp_sort_value(at) >= _iso_timestamp_sort_value(current.get("last_used", "")):
                            current["name"] = name
                            current["last_used"] = at
        except OSError:
            LOGGER.exception("Could not rebuild task autocomplete history from events")
            return 0

        if not usage:
            return 0
        tasks = self.data.setdefault("tasks", [])
        if not isinstance(tasks, list):
            tasks = []
            self.data["tasks"] = tasks
        existing: dict[str, dict[str, Any]] = {
            self._clean_name(item.get("name", "")).casefold(): item
            for item in tasks
            if isinstance(item, dict) and self._clean_name(item.get("name", ""))
        }
        added = 0
        changed = False
        for key, recovered in usage.items():
            item = existing.get(key)
            if item is None:
                tasks.append(dict(recovered))
                added += 1
                changed = True
                continue
            try:
                old_count = max(1, int(item.get("count", 1)))
            except (TypeError, ValueError):
                old_count = 1
            recovered_count = max(1, int(recovered.get("count", 1)))
            recovered_last = str(recovered.get("last_used", ""))
            if recovered_count > old_count:
                item["count"] = recovered_count
                changed = True
            if _iso_timestamp_sort_value(recovered_last) > _iso_timestamp_sort_value(item.get("last_used", "")):
                item["last_used"] = recovered_last
                item["name"] = str(recovered.get("name", item.get("name", "")))
                changed = True
        if changed:
            self._sanitize_tasks()
            self.save()
        return added


class HistoryStore(JsonStore):
    def __init__(self, path: Path) -> None:
        super().__init__(path, {"days": {}})
        if not isinstance(self.data.get("days"), dict):
            self.load_error = "The history 'days' value was not an object."
            if self.path.is_file() and self.recovery_path is None:
                timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")
                self.recovery_path = self.path.with_name(
                    f"{self.path.stem}.damaged-{timestamp}{self.path.suffix}"
                )
                try:
                    _bounded_recovery_copy(self.path, self.recovery_path)
                    self.path.unlink(missing_ok=True)
                except OSError:
                    self.recovery_path = None
                    LOGGER.exception("Could not preserve invalid history file")
            self.data["days"] = {}
        self._sanitize_days()
        self._make_daily_backup()

    @staticmethod
    def _empty_day() -> dict[str, Any]:
        return {
            "work_seconds": 0.0,
            "break_seconds": 0.0,
            "sessions": 0,
            "first_start": "",
            "last_stop": "",
        }

    def _sanitize_days(self) -> None:
        for day_key, raw_entry in list(self.data["days"].items()):
            if not isinstance(day_key, str) or not isinstance(raw_entry, dict):
                self.data["days"][str(day_key)] = self._empty_day()
                if str(day_key) != day_key:
                    self.data["days"].pop(day_key, None)
                continue
            entry = {**raw_entry, **self._empty_day()}
            for key in ("work_seconds", "break_seconds"):
                try:
                    entry[key] = max(0.0, float(raw_entry.get(key, 0.0)))
                except (TypeError, ValueError):
                    pass
            try:
                entry["sessions"] = max(0, int(raw_entry.get("sessions", 0)))
            except (TypeError, ValueError):
                pass
            for key in ("first_start", "last_stop"):
                if isinstance(raw_entry.get(key), str):
                    entry[key] = raw_entry[key]
            self.data["days"][day_key] = entry

    def _make_daily_backup(self) -> None:
        if self.load_error or not self.path.is_file():
            return
        backup = self.path.parent / "backups" / f"history-{date.today().isoformat()}.json"
        if backup.exists():
            return
        try:
            if self.path.stat().st_size > DATA_FILE_HARD_LIMIT_BYTES:
                LOGGER.warning("Skipped oversized daily history backup")
                return
            backup.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(self.path, backup)
        except OSError:
            LOGGER.exception("Could not create daily history backup")

    def day(self, day_key: str | None = None) -> dict[str, Any]:
        day_key = day_key or date.today().isoformat()
        return self.data["days"].setdefault(day_key, self._empty_day())

    def peek_day(self, day_key: str | None = None) -> dict[str, Any]:
        """Read a day without creating an empty history record."""
        day_key = day_key or date.today().isoformat()
        entry = self.data.get("days", {}).get(day_key)
        return entry if isinstance(entry, dict) else self._empty_day()

    def add_seconds(self, kind: str, seconds: float) -> None:
        if seconds <= 0:
            return
        self.adjust_seconds(kind, seconds)

    def adjust_seconds(
        self, kind: str, seconds: float, day_key: str | None = None
    ) -> float:
        """Adjust a daily total and return the amount actually applied."""
        if kind not in {"work", "break"}:
            raise ValueError(f"Unknown history kind: {kind}")
        key = "work_seconds" if kind == "work" else "break_seconds"
        entry = self.day(day_key)
        before = max(0.0, float(entry.get(key, 0.0)))
        after = max(0.0, before + float(seconds))
        entry[key] = after
        if kind == "work" and seconds > 0 and not entry.get("first_start"):
            entry["first_start"] = datetime.now().isoformat(timespec="minutes")
        return after - before

    def start_session(self) -> None:
        entry = self.day()
        entry["sessions"] = int(entry.get("sessions", 0)) + 1
        if not entry.get("first_start"):
            entry["first_start"] = datetime.now().isoformat(timespec="minutes")

    def mark_stop(self) -> None:
        self.day()["last_stop"] = datetime.now().isoformat(timespec="minutes")


class EventStore:
    """Append-only behaviour records, compacted before the local file can grow too large."""

    def __init__(self, path: Path) -> None:
        self.path = path
        _compact_event_file(self.path)
        self._next_seq = self._find_next_seq()

    def _find_next_seq(self) -> int:
        highest = 0
        if not self.path.is_file():
            return 1
        try:
            with self.path.open("r", encoding="utf-8", errors="replace") as stream:
                for line_number, raw_line in enumerate(stream, start=1):
                    highest = max(highest, line_number)
                    try:
                        item = json.loads(raw_line)
                        if isinstance(item, dict):
                            highest = max(highest, int(item.get("seq", line_number)))
                    except (json.JSONDecodeError, TypeError, ValueError):
                        continue
        except OSError:
            return max(1, highest + 1)
        return max(1, highest + 1)

    def append(self, event: str, **details: Any) -> bool:
        record = {
            "schema": EVENT_SCHEMA_VERSION,
            "seq": self._next_seq,
            "at": datetime.now().astimezone().isoformat(timespec="seconds"),
            "event": event,
            **details,
        }
        try:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            line = json.dumps(record, ensure_ascii=False, separators=(",", ":")) + "\n"
            encoded = line.encode("utf-8")
            if len(encoded) >= DATA_FILE_HARD_LIMIT_BYTES:
                LOGGER.error("Refusing oversized event record %s", event)
                return False
            if self.path.is_file() and self.path.stat().st_size + len(encoded) > EVENT_COMPACT_TRIGGER_BYTES:
                _compact_event_file(self.path)
            with self.path.open("a", encoding="utf-8") as stream:
                stream.write(line)
                stream.flush()
                os.fsync(stream.fileno())
            if self.path.stat().st_size > DATA_FILE_HARD_LIMIT_BYTES:
                _compact_event_file(self.path)
            self._next_seq += 1
            return True
        except (OSError, TypeError, ValueError):
            LOGGER.exception("Could not append event %s", event)
            return False

    def records(self) -> list[dict[str, Any]]:
        """Read valid event objects in append order and attach their stable line number."""
        if not self.path.is_file():
            return []
        records: list[dict[str, Any]] = []
        try:
            with self.path.open("r", encoding="utf-8") as stream:
                for line_number, raw_line in enumerate(stream, start=1):
                    try:
                        record = json.loads(raw_line)
                    except (json.JSONDecodeError, TypeError, ValueError):
                        continue
                    if not isinstance(record, dict):
                        continue
                    record = dict(record)
                    try:
                        record["_line"] = int(record.get("seq", line_number))
                    except (TypeError, ValueError):
                        record["_line"] = line_number
                    records.append(record)
        except OSError:
            LOGGER.exception("Could not read event history")
        return records


@dataclass
class ActivityInterval:
    """One reconstructed tracked interval used by Insights and history correction."""

    interval_id: str
    kind: str
    start: datetime
    end: datetime
    task: str = ""
    session_id: str = ""
    work_block_id: str = ""
    source_line: int = 0
    corrected: bool = False
    live: bool = False

    @property
    def seconds(self) -> float:
        return max(0.0, (self.end - self.start).total_seconds())

    def payload(self) -> dict[str, Any]:
        return {
            "kind": self.kind,
            "start": self.start.isoformat(timespec="seconds"),
            "end": self.end.isoformat(timespec="seconds"),
            "task": self.task,
        }


def parse_event_datetime(value: Any) -> datetime | None:
    try:
        parsed = datetime.fromisoformat(str(value or ""))
    except (TypeError, ValueError):
        return None
    if parsed.tzinfo is None:
        try:
            return parsed.astimezone()
        except (OSError, ValueError):
            return parsed.replace(tzinfo=datetime.now().astimezone().tzinfo)
    return parsed


def timeline_kind_from_state(value: Any) -> str | None:
    state = str(value or "")
    if state in {TimerState.WORKING.value, TimerState.WORK_DUE.value}:
        return "work"
    if state == TimerState.RESTING.value:
        return "break"
    return None


def _active_time_correction_lines(records: list[dict[str, Any]]) -> set[int]:
    """Return correction-event lines that still apply after any Undo actions."""
    stack: list[int] = []
    undone: set[int] = set()
    for record in records:
        event = record.get("event")
        if event == "time_corrected":
            try:
                stack.append(int(record.get("_line", 0)))
            except (TypeError, ValueError):
                continue
        elif event == "time_correction_undone" and stack:
            undone.add(stack.pop())
    return {line for line in stack if line not in undone}


def _active_history_edits(records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    edits: list[dict[str, Any]] = []
    undone_ids: set[str] = set()
    for record in records:
        event = record.get("event")
        if event == "timeline_interval_corrected":
            edits.append(record)
        elif event == "timeline_interval_edit_undone":
            edit_id = str(record.get("edit_id") or "")
            if edit_id:
                undone_ids.add(edit_id)
    return [record for record in edits if str(record.get("edit_id") or "") not in undone_ids]


def reconstruct_activity_intervals(
    records: list[dict[str, Any]],
    *,
    day_key: str | None = None,
    live_session_id: str = "",
    live_kind: str | None = None,
    now: datetime | None = None,
) -> list[ActivityInterval]:
    """Reconstruct tracked work/break intervals from append-only events.

    The reconstruction is intentionally conservative. App gaps, paused time and
    completed-break overtime remain untracked. Manual current-time corrections and
    0.11 historical edits are layered on top without rewriting original events.
    """
    active_corrections = _active_time_correction_lines(records)
    raw: list[ActivityInterval] = []
    current_kind: str | None = None
    current_start: datetime | None = None
    current_task = ""
    current_session = ""
    current_block = ""
    current_source_line = 0
    last_event_at: datetime | None = None

    def close_current(end_at: datetime, *, live: bool = False) -> None:
        nonlocal current_kind, current_start, current_task, current_session, current_block, current_source_line
        if current_kind is not None and current_start is not None and end_at > current_start:
            raw.append(
                ActivityInterval(
                    interval_id=f"raw:{current_source_line}",
                    kind=current_kind,
                    start=current_start,
                    end=end_at,
                    task=current_task if current_kind == "work" else "",
                    session_id=current_session,
                    work_block_id=current_block,
                    source_line=current_source_line,
                    live=live,
                )
            )
        current_kind = None
        current_start = None
        current_task = ""
        current_session = ""
        current_block = ""
        current_source_line = 0

    def start_current(kind: str, start_at: datetime, record: dict[str, Any], *, force: bool = False) -> None:
        nonlocal current_kind, current_start, current_task, current_session, current_block, current_source_line
        session_id = str(record.get("session_id") or "")
        block_id = str(record.get("work_block_id") or "")
        task = str(record.get("task") or "").strip()
        source_line = int(record.get("_line", 0) or 0)
        same_identity = (
            current_kind == kind
            and (not block_id or not current_block or block_id == current_block)
            and (not session_id or not current_session or session_id == current_session)
        )
        if current_kind is not None and (force or not same_identity):
            close_current(start_at)
        if current_kind is None:
            current_kind = kind
            current_start = start_at
            current_task = task
            current_session = session_id
            current_block = block_id
            current_source_line = source_line
        else:
            if task and not current_task:
                current_task = task
            if session_id and not current_session:
                current_session = session_id
            if block_id and not current_block:
                current_block = block_id

    for record in records:
        event = str(record.get("event") or "")
        at = parse_event_datetime(record.get("at"))
        if at is None:
            continue
        line = int(record.get("_line", 0) or 0)

        if event == "app_started":
            if current_kind is not None:
                close_at = last_event_at
                interrupted_saved = parse_event_datetime(record.get("interrupted_saved_at"))
                interrupted_session = str(record.get("interrupted_session_id") or "")
                if (
                    interrupted_saved is not None
                    and current_start is not None
                    and interrupted_saved >= current_start
                    and interrupted_saved <= at
                    and (not interrupted_session or not current_session or interrupted_session == current_session)
                ):
                    close_at = interrupted_saved
                if close_at is not None:
                    close_current(close_at)
                else:
                    current_kind = None
                    current_start = None
            else:
                current_kind = None
                current_start = None
            last_event_at = at
            continue

        if event in {"timeline_interval_corrected", "timeline_interval_edit_undone"}:
            last_event_at = at
            continue

        if event == "time_corrected":
            if line not in active_corrections:
                last_event_at = at
                continue
            transition = parse_event_datetime(record.get("corrected_transition_at"))
            if transition is None:
                transition = at
            correction = str(record.get("correction") or "")
            recorded_previous_kind = str(record.get("previous_kind") or "")
            expected_previous_kind = (
                recorded_previous_kind
                if recorded_previous_kind in {"work", "break"}
                else "work" if correction == "started_break_earlier"
                else "break" if correction == "started_work_earlier"
                else None
            )
            target_kind = (
                "break" if correction == "started_break_earlier"
                else "work" if correction == "started_work_earlier"
                else None
            )
            if bool(record.get("window_override")) and target_kind:
                # 0.16.5: the user may correct through a recent transition. Close
                # the current interval at the event, remove every tracked piece in
                # the corrected window for this session, then lay one authoritative
                # interval of the requested kind across that window.
                if current_kind is not None:
                    close_current(at)
                correction_session = str(record.get("session_id") or "")
                rewritten: list[ActivityInterval] = []
                for previous in raw:
                    same_session = (
                        not correction_session
                        or not previous.session_id
                        or previous.session_id == correction_session
                    )
                    overlaps = same_session and previous.end > transition and previous.start < at
                    if not overlaps:
                        rewritten.append(previous)
                        continue
                    original_end = previous.end
                    if previous.start < transition:
                        previous.end = transition
                        if previous.end > previous.start:
                            rewritten.append(previous)
                    if original_end > at:
                        suffix = copy.deepcopy(previous)
                        suffix.start = at
                        suffix.end = original_end
                        suffix.interval_id = f"{previous.interval_id}:after-correction"
                        if suffix.end > suffix.start:
                            rewritten.append(suffix)
                raw[:] = rewritten
                start_current(target_kind, transition, record, force=True)
                last_event_at = at
                continue
            if current_kind is not None:
                # The correction is constrained to the current context, so the
                # backdated transition falls inside (or at the edge of) it.
                if current_start is not None and transition < current_start:
                    transition = current_start
                close_current(transition)
            elif expected_previous_kind and raw:
                # rest_complete / break_ended may already have closed the block
                # that this correction backdates into. Trim only the expected
                # preceding kind from the same session; otherwise the corrected
                # work/break interval would overlap the already-closed interval.
                previous = raw[-1]
                correction_session = str(record.get("session_id") or "")
                same_session = (
                    not correction_session
                    or not previous.session_id
                    or previous.session_id == correction_session
                )
                if (
                    previous.kind == expected_previous_kind
                    and same_session
                    and previous.end > transition
                ):
                    if previous.start < transition:
                        previous.end = transition
                    else:
                        raw.pop()
            if correction == "started_break_earlier":
                start_current("break", transition, record)
            elif correction == "started_work_earlier":
                start_current("work", transition, record)
            last_event_at = at
            continue

        if event == "time_correction_undone":
            last_event_at = at
            continue

        if event in {"session_started", "work_block_started"}:
            start_at = at
            try:
                initial = max(0.0, float(record.get("initial_work_seconds", 0.0)))
            except (TypeError, ValueError):
                initial = 0.0
            if initial > 0:
                start_at = at - timedelta(seconds=initial)
            force = event == "work_block_started" and bool(
                current_kind == "work"
                and current_block
                and record.get("work_block_id")
                and str(record.get("work_block_id")) != current_block
            )
            start_current("work", start_at, record, force=force)
        elif event in {"break_started", "break_restarted"}:
            start_current("break", at, record)
        elif event == "break_ended":
            if current_kind == "break":
                close_current(at)
        elif event == "work_block_ended":
            if current_kind == "work":
                close_current(at)
        elif event == "session_finished":
            if current_kind is not None:
                close_current(at)
        elif event == "timer_paused":
            if current_kind is not None:
                close_current(at)
        elif event == "timer_paused_after_gap":
            try:
                gap = max(0.0, float(record.get("gap_seconds", 0.0)))
            except (TypeError, ValueError):
                gap = 0.0
            end_at = at - timedelta(seconds=gap) if gap > 0 else at
            if current_start is not None and end_at < current_start:
                end_at = current_start
            if current_kind is not None:
                close_current(end_at)
        elif event == "timer_resumed":
            resumed_kind = timeline_kind_from_state(record.get("state"))
            if resumed_kind:
                start_current(resumed_kind, at, record)
        elif event == "rest_complete":
            if current_kind == "break":
                close_current(at)
        elif event == "break_extended":
            if current_kind is None:
                start_current("break", at, record)
        elif event == "session_restored":
            restored_kind = timeline_kind_from_state(record.get("state"))
            if restored_kind:
                start_current(restored_kind, at, record)
        elif event == "app_closed":
            if current_kind is not None:
                close_current(at)

        last_event_at = at

    if current_kind is not None and current_start is not None:
        if live_session_id and current_session == live_session_id and live_kind == current_kind:
            live_end = now or datetime.now().astimezone()
            close_current(live_end, live=True)
        elif last_event_at is not None:
            close_current(last_event_at)

    # Split at local midnight so each displayed/editable interval belongs to one day.
    split: list[ActivityInterval] = []
    for interval in raw:
        start = interval.start
        end = interval.end
        cursor = start
        part = 0
        while cursor.date() < end.date():
            boundary = datetime.combine(
                cursor.date() + timedelta(days=1),
                datetime.min.time(),
                tzinfo=cursor.tzinfo,
            )
            split.append(
                ActivityInterval(
                    interval_id=f"{interval.interval_id}:{cursor.date().isoformat()}:{part}",
                    kind=interval.kind,
                    start=cursor,
                    end=boundary,
                    task=interval.task,
                    session_id=interval.session_id,
                    work_block_id=interval.work_block_id,
                    source_line=interval.source_line,
                    live=interval.live,
                )
            )
            cursor = boundary
            part += 1
        if end > cursor:
            split.append(
                ActivityInterval(
                    interval_id=f"{interval.interval_id}:{cursor.date().isoformat()}:{part}",
                    kind=interval.kind,
                    start=cursor,
                    end=end,
                    task=interval.task,
                    session_id=interval.session_id,
                    work_block_id=interval.work_block_id,
                    source_line=interval.source_line,
                    live=interval.live,
                )
            )

    by_id = {interval.interval_id: interval for interval in split}
    for edit in _active_history_edits(records):
        target_id = str(edit.get("target_interval_id") or "")
        interval = by_id.get(target_id)
        payload = edit.get("new")
        if interval is None or not isinstance(payload, dict):
            continue
        start = parse_event_datetime(payload.get("start"))
        end = parse_event_datetime(payload.get("end"))
        kind = str(payload.get("kind") or interval.kind)
        if start is None or end is None or end <= start or kind not in {"work", "break"}:
            continue
        interval.start = start
        interval.end = end
        interval.kind = kind
        interval.task = str(payload.get("task") or "").strip() if kind == "work" else ""
        interval.corrected = True
        interval.live = False

    result = sorted(split, key=lambda item: (item.start, item.end, item.interval_id))
    if day_key:
        result = [item for item in result if item.start.date().isoformat() == day_key]
    return result


def day_timeline_segments(day_key: str, intervals: list[ActivityInterval]) -> list[ActivityInterval]:
    """Return a full-day sequence including explicit untracked gaps."""
    try:
        day_value = date.fromisoformat(day_key)
    except ValueError:
        return []
    local_tz = intervals[0].start.tzinfo if intervals and intervals[0].start.tzinfo is not None else datetime.now().astimezone().tzinfo
    day_start = datetime.combine(day_value, datetime.min.time(), tzinfo=local_tz)
    day_end = day_start + timedelta(days=1)
    result: list[ActivityInterval] = []
    cursor = day_start
    for interval in sorted(intervals, key=lambda item: item.start):
        start = max(day_start, interval.start)
        end = min(day_end, interval.end)
        if end <= start:
            continue
        if start > cursor:
            result.append(ActivityInterval(f"gap:{day_key}:{len(result)}", "untracked", cursor, start))
        result.append(interval)
        cursor = max(cursor, end)
    if cursor < day_end:
        result.append(ActivityInterval(f"gap:{day_key}:{len(result)}", "untracked", cursor, day_end))
    return result


def timeline_day_summary(
    day_key: str, intervals: list[ActivityInterval]
) -> tuple[dict[str, float], int]:
    """Return 24-hour totals and distinct work-block count for one day."""
    segments = day_timeline_segments(day_key, intervals)
    totals = {"work": 0.0, "break": 0.0, "untracked": 0.0}
    for segment in segments:
        if segment.kind in totals:
            totals[segment.kind] += segment.seconds
    work_ids = {
        interval.work_block_id or interval.interval_id
        for interval in intervals
        if interval.kind == "work" and interval.seconds > 0
    }
    return totals, len(work_ids)


def normalize_task_key(value: Any) -> str:
    return re.sub(r"\s+", " ", str(value or "")).strip().casefold()


def summarize_task_intervals(intervals: list[ActivityInterval]) -> list[dict[str, Any]]:
    """Summarize work intervals by normalized task name.

    Multiple fragments with the same work_block_id count as one block, so a
    pause/resume gap does not inflate the task's block count.  Empty task names
    use the empty key and are labelled in the UI as Unspecified.
    """
    groups: dict[str, dict[str, Any]] = {}
    block_seconds: dict[tuple[str, str], float] = {}
    for interval in intervals:
        if interval.kind != "work" or interval.seconds <= 0:
            continue
        key = normalize_task_key(interval.task)
        item = groups.setdefault(
            key,
            {
                "key": key,
                "name": interval.task.strip(),
                "seconds": 0.0,
                "blocks": 0,
                "average_seconds": 0.0,
                "longest_seconds": 0.0,
                "last_end": interval.end,
            },
        )
        item["seconds"] = float(item.get("seconds", 0.0)) + interval.seconds
        if interval.task.strip() and interval.end >= item.get("last_end", interval.end):
            item["name"] = interval.task.strip()
            item["last_end"] = interval.end
        block_id = interval.work_block_id or interval.interval_id
        block_key = (key, block_id)
        block_seconds[block_key] = block_seconds.get(block_key, 0.0) + interval.seconds

    for key, item in groups.items():
        durations = [seconds for (task_key, _block), seconds in block_seconds.items() if task_key == key]
        item["blocks"] = len(durations)
        if durations:
            item["average_seconds"] = sum(durations) / len(durations)
            item["longest_seconds"] = max(durations)
        item.pop("last_end", None)

    return sorted(
        groups.values(),
        key=lambda item: (-float(item.get("seconds", 0.0)), str(item.get("name", "")).casefold()),
    )



def summarize_week_review(intervals_by_day: dict[str, list[ActivityInterval]]) -> dict[str, Any]:
    """Return neutral weekly facts for review and planning.

    This deliberately reports observed timing only.  It does not produce a
    productivity score or assume that more tracked work is better.
    """
    combined: list[ActivityInterval] = []
    day_work: dict[str, float] = {}
    total_break = 0.0
    block_seconds: dict[str, float] = {}

    for day_key, intervals in intervals_by_day.items():
        work_seconds = 0.0
        for interval in intervals:
            if interval.seconds <= 0:
                continue
            combined.append(interval)
            if interval.kind == "work":
                work_seconds += interval.seconds
                block_id = interval.work_block_id or interval.interval_id
                block_seconds[block_id] = block_seconds.get(block_id, 0.0) + interval.seconds
            elif interval.kind == "break":
                total_break += interval.seconds
        if work_seconds > 0:
            day_work[day_key] = work_seconds

    total_work = sum(day_work.values())
    work_days = len(day_work)
    average_block = sum(block_seconds.values()) / len(block_seconds) if block_seconds else 0.0
    longest_day_key = ""
    longest_day_seconds = 0.0
    if day_work:
        longest_day_key, longest_day_seconds = max(day_work.items(), key=lambda item: item[1])

    work_intervals = [item for item in combined if item.kind == "work" and item.seconds > 0]
    latest_end = max((item.end for item in work_intervals), default=None)
    tasks = summarize_task_intervals(combined)
    top_task = tasks[0] if tasks else None

    return {
        "total_work": total_work,
        "total_break": total_break,
        "work_days": work_days,
        "average_block_seconds": average_block,
        "longest_day_key": longest_day_key,
        "longest_day_seconds": longest_day_seconds,
        "latest_end": latest_end,
        "top_task": top_task,
    }


def configure_logging(data_dir: Path) -> None:
    if LOGGER.handlers:
        return
    try:
        data_dir.mkdir(parents=True, exist_ok=True)
        handler = logging.handlers.RotatingFileHandler(
            data_dir / "taktpause.log",
            maxBytes=512_000,
            backupCount=3,
            encoding="utf-8",
        )
        handler.setFormatter(
            logging.Formatter("%(asctime)s %(levelname)s %(message)s")
        )
        LOGGER.addHandler(handler)
        LOGGER.setLevel(logging.INFO)
    except OSError:
        logging.basicConfig(level=logging.INFO)


def create_upgrade_backup(data_dir: Path) -> None:
    """Keep one pre-release copy of user data before this build can modify it."""
    backup_dir = data_dir / "backups" / f"upgrade-{APP_VERSION}"
    marker = backup_dir / "complete.txt"
    if marker.exists():
        return
    try:
        backup_dir.mkdir(parents=True, exist_ok=True)
        for name in (
            "settings.json", "history.json", "task_history.json",
            "weekly_notes.json", "current_session.json", "custom_messages.json", "events.jsonl",
        ):
            source = data_dir / name
            if source.is_file():
                if source.stat().st_size > DATA_FILE_HARD_LIMIT_BYTES:
                    LOGGER.warning("Skipped oversized backup source: %s", source.name)
                    continue
                shutil.copy2(source, backup_dir / name)
        marker.write_text(
            datetime.now().astimezone().isoformat(timespec="seconds"),
            encoding="utf-8",
        )
        LOGGER.info("Created one-time upgrade backup at %s", backup_dir)
    except OSError:
        LOGGER.exception("Could not create the upgrade backup")


def application_data_dir() -> Path:
    if platform.system() == "Windows":
        root = os.environ.get("APPDATA") or str(Path.home() / "AppData" / "Roaming")
        old_path = Path(root) / "WorkPause"
        new_path = Path(root) / "Taktpause"
        # Existing users keep their current files. New installations use the new name.
        return new_path if new_path.exists() else (old_path if old_path.exists() else new_path)
    if platform.system() == "Linux":
        return linux_data_dir()
    old_path = Path.home() / ".work_pause"
    new_path = Path.home() / ".taktpause"
    return new_path if new_path.exists() else (old_path if old_path.exists() else new_path)


def linux_data_dir(environ: Any = None, home: Path | None = None) -> Path:
    """Where Taktpause keeps its files on Linux.

    Inside a snap, $SNAP_USER_COMMON survives updates without being copied for
    every revision. Elsewhere follow the XDG base-directory convention, but keep
    using an existing ~/.taktpause or ~/.work_pause so earlier installs keep
    their history.
    """
    env = os.environ if environ is None else environ
    home = Path.home() if home is None else home
    snap_common = str(env.get("SNAP_USER_COMMON", "") or "").strip()
    if snap_common:
        return Path(snap_common)
    for legacy in (home / ".taktpause", home / ".work_pause"):
        if legacy.exists():
            return legacy
    xdg = str(env.get("XDG_DATA_HOME", "") or "").strip()
    base = Path(xdg) if xdg and Path(xdg).is_absolute() else home / ".local" / "share"
    return base / "taktpause"


def linux_language(environ: Any = None) -> str:
    """Follow POSIX precedence: LANGUAGE, then LC_ALL, LC_MESSAGES and LANG."""
    env = os.environ if environ is None else environ
    for key in ("LANGUAGE", "LC_ALL", "LC_MESSAGES", "LANG"):
        raw = str(env.get(key, "") or "").strip()
        if not raw or raw in {"C", "POSIX"} or raw.startswith("C."):
            continue
        for item in raw.split(":"):
            code = item.strip().lower()
            if code.startswith("fa"):
                return "fa"
            if code.startswith("de"):
                return "de"
            if code.startswith("en"):
                return "en"
        return "en"
    return "en"


def run_quietly(command: list[str], timeout: float = 2.0) -> str | None:
    """Run a small desktop helper and return its output, or None if unavailable."""
    if not command or shutil.which(command[0]) is None:
        return None
    try:
        completed = subprocess.run(
            command, capture_output=True, text=True, timeout=timeout, check=False
        )
    except (OSError, subprocess.SubprocessError):
        return None
    if completed.returncode != 0:
        return None
    return completed.stdout.strip()


def parse_portal_color_scheme(output: str) -> bool | None:
    """Read the XDG portal answer: 1 prefers dark, 2 prefers light, 0 has no preference."""
    match = re.search(r"uint32\s+(\d+)", output or "")
    if not match:
        return None
    value = int(match.group(1))
    if value == 1:
        return True
    if value == 2:
        return False
    return None


def linux_prefers_dark() -> bool:
    """Read the desktop's light or dark preference.

    The XDG desktop portal answers on GNOME, KDE and inside a snap. gsettings is
    the GNOME fallback when no portal is running.
    """
    portal = run_quietly(
        [
            "gdbus", "call", "--session",
            "--dest", "org.freedesktop.portal.Desktop",
            "--object-path", "/org/freedesktop/portal/desktop",
            "--method", "org.freedesktop.portal.Settings.Read",
            "org.freedesktop.appearance", "color-scheme",
        ],
        timeout=1.5,
    )
    parsed = parse_portal_color_scheme(portal or "")
    if parsed is not None:
        return parsed
    scheme = run_quietly(["gsettings", "get", "org.gnome.desktop.interface", "color-scheme"], timeout=1.5)
    if scheme and "prefer-dark" in scheme:
        return True
    theme = run_quietly(["gsettings", "get", "org.gnome.desktop.interface", "gtk-theme"], timeout=1.5)
    return bool(theme and "dark" in theme.lower())


LINUX_AUDIO_PLAYERS: tuple[tuple[str, ...], ...] = (("paplay",), ("pw-play",), ("aplay", "-q"))


def linux_audio_commands(sound_path: Path) -> list[list[str]]:
    """All installed players able to play this file, best first."""
    commands: list[list[str]] = []
    for player in LINUX_AUDIO_PLAYERS:
        if shutil.which(player[0]) is None:
            continue
        if player[0] == "aplay" and sound_path.suffix.lower() != ".wav":
            continue
        commands.append([*player, str(sound_path)])
    return commands


def linux_audio_command(sound_path: Path) -> list[str] | None:
    """The first installed player able to play this file, or None."""
    commands = linux_audio_commands(sound_path)
    return commands[0] if commands else None


def play_sound_in_background(commands: list[list[str]], *, repeat: int = 1, gap: float = 0.12) -> None:
    """Play a sound off the Tk thread with the first player that works.

    A player can be installed and still fail, for example when it cannot
    reach the sound server.  Then the next player is tried, and the reason is
    written to the diagnostic log.
    """

    def worker() -> None:
        for command in commands:
            failed = False
            for index in range(max(1, repeat)):
                if index:
                    time.sleep(gap)
                try:
                    result = subprocess.run(
                        command,
                        stdout=subprocess.DEVNULL,
                        stderr=subprocess.PIPE,
                        timeout=15.0,
                        check=False,
                    )
                except (OSError, subprocess.SubprocessError) as error:
                    LOGGER.warning("Sound player %s could not run: %s", command[0], error)
                    failed = True
                    break
                if result.returncode != 0:
                    detail = (result.stderr or b"").decode("utf-8", "replace").strip()[:300]
                    LOGGER.warning("Sound player %s failed (%s): %s", command[0], result.returncode, detail)
                    failed = True
                    break
            if not failed:
                return
        if commands:
            LOGGER.warning("No sound player could play the reminder sound")

    threading.Thread(target=worker, name="TaktpauseSound", daemon=True).start()


def linux_system_sound_path() -> Path | None:
    """The desktop's own short completion sound, if a freedesktop theme is present."""
    roots: list[Path] = []
    snap = os.environ.get("SNAP", "")
    if snap:
        roots += [Path(snap) / "data-dir" / "sounds", Path(snap) / "usr" / "share" / "sounds"]
    data_dirs = os.environ.get("XDG_DATA_DIRS", "") or "/usr/local/share:/usr/share"
    roots += [Path(item) / "sounds" for item in data_dirs.split(":") if item]
    for root in roots:
        for name in ("complete.oga", "message.oga", "bell.oga"):
            candidate = root / "freedesktop" / "stereo" / name
            if candidate.is_file():
                return candidate
    return None


def run_in_background(command: list[str], *, repeat: int = 1, gap: float = 0.12, timeout: float = 30.0) -> None:
    """Run a helper off the Tk thread, once or several times in sequence."""

    def worker() -> None:
        for index in range(max(1, repeat)):
            if index:
                time.sleep(gap)
            try:
                subprocess.run(
                    command,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    timeout=timeout,
                    check=False,
                )
            except (OSError, subprocess.SubprocessError):
                LOGGER.debug("Background helper failed: %s", command[0], exc_info=True)
                return

    threading.Thread(target=worker, name="TaktpauseHelper", daemon=True).start()


def open_with_desktop(path: Path) -> None:
    """Open a file or folder with the user's default application."""
    if platform.system() == "Windows":
        os.startfile(path)  # type: ignore[attr-defined]
        return
    opener = "xdg-open" if platform.system() == "Linux" else "open"
    if shutil.which(opener) is None:
        raise OSError(f"{opener} is not available")
    run_in_background([opener, str(path)])


def wrap_logical_lines(text: str, max_width: int, measure: Any) -> list[str]:
    """Greedy word wrap in logical (reading) order.

    Tk wraps the already reordered Persian string from the left, so the first
    words of a paragraph end up on the last line.  Wrapping before reordering
    keeps the reading order correct.
    """
    lines: list[str] = []
    for paragraph in str(text).split("\n"):
        current = ""
        for word in paragraph.split(" "):
            candidate = word if not current else f"{current} {word}"
            if current and measure(candidate) > max_width:
                lines.append(current)
                current = word
            else:
                current = candidate
        lines.append(current)
    return lines


_RTL_WRAP_LABEL_CLASS: Any = None


def rtl_wrap_label_class() -> Any:
    """Return a tk.Label subclass that wraps Persian text in reading order."""
    global _RTL_WRAP_LABEL_CLASS
    if _RTL_WRAP_LABEL_CLASS is not None or tk is None:
        return _RTL_WRAP_LABEL_CLASS

    class RtlWrapLabel(tk.Label):  # type: ignore[misc, valid-type]
        def __init__(self, master: Any, app: Any, *args: Any, **kwargs: Any) -> None:
            self._app = app
            self._wrap_px = 0
            self._source_text: str | None = None
            pending = {key: kwargs.pop(key) for key in ("wraplength", "text") if key in kwargs}
            super().__init__(master, *args, **kwargs)
            if pending:
                self.configure(**pending)

        def configure(self, cnf: Any = None, **kw: Any) -> Any:
            if isinstance(cnf, str) or (cnf is None and not kw):
                return super().configure(cnf, **kw)
            options = dict(cnf or {})
            options.update(kw)
            if "wraplength" in options:
                try:
                    self._wrap_px = int(self.winfo_pixels(options["wraplength"]))
                except (tk.TclError, TypeError, ValueError):
                    self._wrap_px = 0
            relayout = any(key in options for key in ("text", "font", "wraplength"))
            if "text" in options:
                self._source_text = str(options.pop("text"))
            options.pop("wraplength", None)
            result = super().configure(options) if options else None
            if relayout and self._source_text is not None:
                self._relayout()
            return result

        config = configure

        def _relayout(self) -> None:
            app = self._app
            source = self._source_text or ""
            logical = app._rtl_logical_text(source) if app.lang == "fa" else None
            if self._wrap_px <= 0 or logical is None:
                super().configure(text=source, wraplength=self._wrap_px)
                return
            font = self.cget("font")

            def measure(value: str) -> int:
                return int(self.tk.call("font", "measure", font, app._rtl_display(value)))

            lines = wrap_logical_lines(logical, self._wrap_px, measure)
            display = "\n".join(app._rtl_display(line) for line in lines)
            super().configure(text=display, wraplength=0)

    _RTL_WRAP_LABEL_CLASS = RtlWrapLabel
    return _RTL_WRAP_LABEL_CLASS


def startup_remove_message(startup_id: str) -> bytes:
    """Build the X11 startup-notification message that ends a launch."""
    escaped = startup_id.replace("\\", "\\\\").replace('"', '\\"')
    return f'remove: ID="{escaped}"'.encode("utf-8") + b"\0"


def linux_startup_complete(environ: Any = None) -> bool:
    """Tell the desktop that Taktpause has finished starting.

    When started from the app menu, GNOME shows a busy cursor until the app
    reports that it is ready.  GTK apps do this automatically; Tk does not,
    so GNOME waits for its timeout.  This sends the same X11 message GTK
    sends.  Returns True when the message was sent.
    """
    environ = os.environ if environ is None else environ
    startup_id = str(environ.pop("DESKTOP_STARTUP_ID", "") or "")
    environ.pop("XDG_ACTIVATION_TOKEN", None)  # child programs must not reuse it
    if not startup_id or platform.system() != "Linux":
        return False
    try:
        import ctypes
        import ctypes.util

        xlib = ctypes.CDLL(ctypes.util.find_library("X11") or "libX11.so.6")
        xlib.XOpenDisplay.restype = ctypes.c_void_p
        xlib.XOpenDisplay.argtypes = [ctypes.c_char_p]
        xlib.XDefaultRootWindow.restype = ctypes.c_ulong
        xlib.XDefaultRootWindow.argtypes = [ctypes.c_void_p]
        xlib.XInternAtom.restype = ctypes.c_ulong
        xlib.XInternAtom.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_int]
        xlib.XCreateSimpleWindow.restype = ctypes.c_ulong
        xlib.XCreateSimpleWindow.argtypes = [
            ctypes.c_void_p, ctypes.c_ulong, ctypes.c_int, ctypes.c_int,
            ctypes.c_uint, ctypes.c_uint, ctypes.c_uint, ctypes.c_ulong, ctypes.c_ulong,
        ]
        xlib.XSendEvent.argtypes = [
            ctypes.c_void_p, ctypes.c_ulong, ctypes.c_int, ctypes.c_long, ctypes.c_void_p,
        ]
        xlib.XDestroyWindow.argtypes = [ctypes.c_void_p, ctypes.c_ulong]
        xlib.XFlush.argtypes = [ctypes.c_void_p]
        xlib.XCloseDisplay.argtypes = [ctypes.c_void_p]

        class ClientMessage(ctypes.Structure):
            _fields_ = [
                ("type", ctypes.c_int),
                ("serial", ctypes.c_ulong),
                ("send_event", ctypes.c_int),
                ("display", ctypes.c_void_p),
                ("window", ctypes.c_ulong),
                ("message_type", ctypes.c_ulong),
                ("format", ctypes.c_int),
                ("data", ctypes.c_long * 5),
            ]

        class XEvent(ctypes.Union):
            _fields_ = [("xclient", ClientMessage), ("pad", ctypes.c_long * 24)]

        display = xlib.XOpenDisplay(None)
        if not display:
            return False
        try:
            root = xlib.XDefaultRootWindow(display)
            begin_atom = xlib.XInternAtom(display, b"_NET_STARTUP_INFO_BEGIN", 0)
            more_atom = xlib.XInternAtom(display, b"_NET_STARTUP_INFO", 0)
            sender = xlib.XCreateSimpleWindow(display, root, -100, -100, 1, 1, 0, 0, 0)
            message = startup_remove_message(startup_id)
            for offset in range(0, len(message), 20):
                chunk = message[offset:offset + 20]
                event = XEvent()
                event.xclient.type = 33  # ClientMessage
                event.xclient.send_event = 1
                event.xclient.display = display
                event.xclient.window = sender
                event.xclient.message_type = begin_atom if offset == 0 else more_atom
                event.xclient.format = 8
                ctypes.memmove(ctypes.addressof(event.xclient.data), chunk, len(chunk))
                xlib.XSendEvent(display, root, 0, 1 << 22, ctypes.byref(event))  # PropertyChangeMask
            xlib.XFlush(display)
            xlib.XDestroyWindow(display, sender)
            xlib.XFlush(display)
        finally:
            xlib.XCloseDisplay(display)
        return True
    except Exception:
        LOGGER.debug("Could not send the startup-complete message", exc_info=True)
        return False


V018_DEFAULTS_ON = ("mini_timer", "lunch_enabled", "snack_reminders", "state_colours")


def apply_v018_defaults(settings: dict[str, Any]) -> bool:
    """Turn on the 0.18 default options once for people upgrading.

    Earlier versions saved every setting, including the old "off" defaults,
    so existing users would otherwise never see these options.  It runs once;
    afterwards each choice in Settings is respected.
    """
    if settings.get("defaults_v018_applied"):
        return False
    for key in V018_DEFAULTS_ON:
        settings[key] = True
    settings["defaults_v018_applied"] = True
    return True


def blend_colour(foreground: str, background: str, amount: float) -> str:
    """Mix two #RRGGBB colours; amount 1.0 gives the foreground."""
    amount = max(0.0, min(1.0, float(amount)))
    fg = [int(foreground[index:index + 2], 16) for index in (1, 3, 5)]
    bg = [int(background[index:index + 2], 16) for index in (1, 3, 5)]
    return "#" + "".join(f"{round(f * amount + b * (1.0 - amount)):02X}" for f, b in zip(fg, bg))


def circle_scanlines(diameter: int) -> list[tuple[int, int, int]]:
    """(y, x, width) rows that together form a filled circle."""
    radius = diameter / 2.0
    rows: list[tuple[int, int, int]] = []
    for y in range(diameter):
        dy = y + 0.5 - radius
        half = math.sqrt(max(0.0, radius * radius - dy * dy))
        left = int(round(radius - half))
        width = int(round(radius + half)) - left
        if width > 0:
            rows.append((y, left, width))
    return rows


class X11Helper:
    """Small libX11/libXext calls Tk does not offer (Linux only)."""

    def __init__(self) -> None:
        import ctypes
        import ctypes.util

        self.ctypes = ctypes
        self.xlib = ctypes.CDLL(ctypes.util.find_library("X11") or "libX11.so.6")
        self.xlib.XOpenDisplay.restype = ctypes.c_void_p
        self.xlib.XOpenDisplay.argtypes = [ctypes.c_char_p]
        self.xlib.XInternAtom.restype = ctypes.c_ulong
        self.xlib.XInternAtom.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_int]
        self.xlib.XQueryTree.argtypes = [
            ctypes.c_void_p, ctypes.c_ulong, ctypes.POINTER(ctypes.c_ulong), ctypes.POINTER(ctypes.c_ulong),
            ctypes.POINTER(ctypes.c_void_p), ctypes.POINTER(ctypes.c_uint),
        ]
        self.xlib.XGetWindowProperty.argtypes = [
            ctypes.c_void_p, ctypes.c_ulong, ctypes.c_ulong, ctypes.c_long, ctypes.c_long, ctypes.c_int,
            ctypes.c_ulong, ctypes.POINTER(ctypes.c_ulong), ctypes.POINTER(ctypes.c_int),
            ctypes.POINTER(ctypes.c_ulong), ctypes.POINTER(ctypes.c_ulong), ctypes.POINTER(ctypes.c_void_p),
        ]
        self.xlib.XFree.argtypes = [ctypes.c_void_p]
        self.xlib.XFlush.argtypes = [ctypes.c_void_p]
        self.display = self.xlib.XOpenDisplay(None)
        if not self.display:
            raise OSError("No X display")
        self.atom_wm_state = self.xlib.XInternAtom(self.display, b"WM_STATE", 0)
        self.atom_net_state = self.xlib.XInternAtom(self.display, b"_NET_WM_STATE", 0)
        self.atom_hidden = self.xlib.XInternAtom(self.display, b"_NET_WM_STATE_HIDDEN", 0)
        self.xext = None
        try:
            self.xext = ctypes.CDLL(ctypes.util.find_library("Xext") or "libXext.so.6")
        except OSError:
            self.xext = None

    def _tree(self, window: int) -> tuple[int, int]:
        """(root, parent) of an X window, or (0, 0)."""
        c = self.ctypes
        root, parent = c.c_ulong(), c.c_ulong()
        children, count = c.c_void_p(), c.c_uint()
        if not self.xlib.XQueryTree(self.display, window, c.byref(root), c.byref(parent), c.byref(children), c.byref(count)):
            return 0, 0
        if children.value:
            self.xlib.XFree(children)
        return int(root.value), int(parent.value)

    def _parent(self, window: int) -> int:
        return self._tree(window)[1]

    def _longs(self, window: int, atom: int, count: int = 32) -> list[int]:
        c = self.ctypes
        actual_type, actual_format = c.c_ulong(), c.c_int()
        items, after, data = c.c_ulong(), c.c_ulong(), c.c_void_p()
        status = self.xlib.XGetWindowProperty(
            self.display, window, atom, 0, count, 0, 0,  # AnyPropertyType
            c.byref(actual_type), c.byref(actual_format), c.byref(items), c.byref(after), c.byref(data),
        )
        if status != 0 or not data.value:
            return []
        try:
            if actual_format.value != 32:
                return []
            array = c.cast(data, c.POINTER(c.c_long))
            return [int(array[index]) for index in range(int(items.value))]
        finally:
            self.xlib.XFree(data)

    def is_minimized(self, tk_window_id: int) -> bool | None:
        """True when the window manager reports the Tk toplevel as minimized."""
        client = self._parent(tk_window_id)  # Tk's wrapper is the managed client window
        if not client:
            return None
        wm_state = self._longs(client, self.atom_wm_state, 2)
        if wm_state and wm_state[0] == 3:  # IconicState
            return True
        return self.atom_hidden in self._longs(client, self.atom_net_state)

    def is_viewable(self, tk_window_id: int) -> bool | None:
        """True when the managed window is really mapped on screen."""
        c = self.ctypes

        class XWindowAttributes(c.Structure):
            _fields_ = [
                ("x", c.c_int), ("y", c.c_int), ("width", c.c_int), ("height", c.c_int),
                ("border_width", c.c_int), ("depth", c.c_int), ("visual", c.c_void_p), ("root", c.c_ulong),
                ("c_class", c.c_int), ("bit_gravity", c.c_int), ("win_gravity", c.c_int),
                ("backing_store", c.c_int), ("backing_planes", c.c_ulong), ("backing_pixel", c.c_ulong),
                ("save_under", c.c_int), ("colormap", c.c_ulong), ("map_installed", c.c_int),
                ("map_state", c.c_int), ("all_event_masks", c.c_long), ("your_event_mask", c.c_long),
                ("do_not_propagate_mask", c.c_long), ("override_redirect", c.c_int), ("screen", c.c_void_p),
            ]

        client = self._parent(tk_window_id)
        if not client:
            return None
        attributes = XWindowAttributes()
        self.xlib.XGetWindowAttributes.argtypes = [c.c_void_p, c.c_ulong, c.c_void_p]
        if not self.xlib.XGetWindowAttributes(self.display, client, c.byref(attributes)):
            return None
        return attributes.map_state == 2  # IsViewable

    def activate(self, tk_window_id: int, timestamp: int = 0) -> bool:
        """Ask the window manager to un-minimize and focus a Tk toplevel.

        GNOME can minimize a Tk window without Tk noticing.  Tk then thinks
        the window is already visible and deiconify() does nothing, so send
        the standard _NET_ACTIVE_WINDOW request instead.
        """
        c = self.ctypes
        root, client = self._tree(tk_window_id)
        if not client:
            return False

        class ClientMessage(c.Structure):
            _fields_ = [
                ("type", c.c_int), ("serial", c.c_ulong), ("send_event", c.c_int), ("display", c.c_void_p),
                ("window", c.c_ulong), ("message_type", c.c_ulong), ("format", c.c_int), ("data", c.c_long * 5),
            ]

        class XEvent(c.Union):
            _fields_ = [("xclient", ClientMessage), ("pad", c.c_long * 24)]

        self.xlib.XSendEvent.argtypes = [c.c_void_p, c.c_ulong, c.c_int, c.c_long, c.c_void_p]
        event = XEvent()
        event.xclient.type = 33  # ClientMessage
        event.xclient.send_event = 1
        event.xclient.display = self.display
        event.xclient.window = client
        event.xclient.message_type = self.xlib.XInternAtom(self.display, b"_NET_ACTIVE_WINDOW", 0)
        event.xclient.format = 32
        event.xclient.data[0] = 2  # request from a pager-like tool, i.e. a user action
        event.xclient.data[1] = int(timestamp) & 0xFFFFFFFF  # time of the user's click (0 = now)
        mask = (1 << 19) | (1 << 20)  # SubstructureNotifyMask | SubstructureRedirectMask
        self.xlib.XSendEvent(self.display, root, 0, mask, c.byref(event))
        self.xlib.XFlush(self.display)
        return True

    def monitors(self) -> list[tuple[int, int, int, int]]:
        """(x, y, width, height) of each active monitor, from XRandR."""
        c = self.ctypes
        if getattr(self, "xrandr", None) is None:
            import ctypes.util

            self.xrandr = c.CDLL(ctypes.util.find_library("Xrandr") or "libXrandr.so.2")

        class MonitorInfo(c.Structure):
            _fields_ = [
                ("name", c.c_ulong), ("primary", c.c_int), ("automatic", c.c_int), ("noutput", c.c_int),
                ("x", c.c_int), ("y", c.c_int), ("width", c.c_int), ("height", c.c_int),
                ("mwidth", c.c_int), ("mheight", c.c_int), ("outputs", c.c_void_p),
            ]

        self.xlib.XDefaultRootWindow.restype = c.c_ulong
        self.xlib.XDefaultRootWindow.argtypes = [c.c_void_p]
        self.xrandr.XRRGetMonitors.restype = c.POINTER(MonitorInfo)
        self.xrandr.XRRGetMonitors.argtypes = [c.c_void_p, c.c_ulong, c.c_int, c.POINTER(c.c_int)]
        self.xrandr.XRRFreeMonitors.argtypes = [c.c_void_p]
        count = c.c_int(0)
        root = self.xlib.XDefaultRootWindow(self.display)
        info = self.xrandr.XRRGetMonitors(self.display, root, 1, c.byref(count))
        if not info:
            return []
        try:
            return [
                (int(info[i].x), int(info[i].y), int(info[i].width), int(info[i].height))
                for i in range(int(count.value))
                if info[i].width > 0 and info[i].height > 0
            ]
        finally:
            self.xrandr.XRRFreeMonitors(info)

    def shape_circle(self, window: int, diameter: int) -> bool:
        """Cut a top-level X11 window to a circle with the SHAPE extension."""
        if self.xext is None:
            return False
        c = self.ctypes

        class XRectangle(c.Structure):
            _fields_ = [("x", c.c_short), ("y", c.c_short), ("width", c.c_ushort), ("height", c.c_ushort)]

        rows = circle_scanlines(diameter)
        rects = (XRectangle * len(rows))(*[XRectangle(x, y, width, 1) for y, x, width in rows])
        self.xext.XShapeCombineRectangles.argtypes = [
            c.c_void_p, c.c_ulong, c.c_int, c.c_int, c.c_int, c.c_void_p, c.c_int, c.c_int, c.c_int,
        ]
        # Shape the Tk window and its wrapper (the real top-level window).
        targets = [window]
        root, parent = self._tree(window)
        if parent and parent != root:
            targets.append(parent)
        for target in targets:
            # ShapeBounding = 0, ShapeSet = 0, Unsorted = 0
            self.xext.XShapeCombineRectangles(self.display, target, 0, 0, 0, rects, len(rows), 0, 0)
        self.xlib.XFlush(self.display)
        return True


def ensure_png_icon(path: Path) -> str | None:
    """Materialize the bundled PNG mark, used by Linux desktop notifications."""
    try:
        raw = base64.b64decode(APP_ICON_PNG_B64)
        if not path.exists() or path.stat().st_size != len(raw) or path.read_bytes() != raw:
            path.parent.mkdir(parents=True, exist_ok=True)
            tmp = path.with_suffix(path.suffix + ".tmp")
            tmp.write_bytes(raw)
            os.replace(tmp, path)
        return str(path)
    except Exception:
        LOGGER.exception("Could not prepare Taktpause notification icon")
        return None


def system_language() -> str:
    if platform.system() == "Linux":
        return linux_language()
    candidates = [os.environ.get("LANG", ""), os.environ.get("LC_ALL", "")]
    if platform.system() == "Windows":
        try:
            import ctypes
            import locale

            locale_name = ctypes.create_unicode_buffer(85)
            if ctypes.windll.kernel32.GetUserDefaultLocaleName(locale_name, len(locale_name)):
                candidates.insert(0, locale_name.value)
            candidates.insert(0, locale.getlocale()[0] or "")
        except (AttributeError, ImportError, OSError, ValueError):
            pass
    if any(item.lower().startswith("fa") for item in candidates):
        return "fa"
    if any(item.lower().startswith("de") for item in candidates):
        return "de"
    return "en"


def system_uses_dark_theme() -> bool:
    if platform.system() == "Linux":
        return linux_prefers_dark()
    if platform.system() != "Windows":
        return False
    try:
        import winreg

        key_path = r"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize"
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, key_path) as key:
            value, _ = winreg.QueryValueEx(key, "AppsUseLightTheme")
            return value == 0
    except (ImportError, OSError):
        return False


def format_duration(seconds: float, show_sign: bool = False) -> str:
    total = max(0, int(round(seconds)))
    hours, remainder = divmod(total, 3600)
    minutes, secs = divmod(remainder, 60)
    value = f"{hours:d}:{minutes:02d}:{secs:02d}" if hours else f"{minutes:02d}:{secs:02d}"
    return f"+{value}" if show_sign else value


def format_total(seconds: float) -> str:
    total_minutes = int(round(max(0.0, seconds) / 60))
    hours, minutes = divmod(total_minutes, 60)
    if hours and minutes:
        return f"{hours}h {minutes}m"
    if hours:
        return f"{hours}h"
    return f"{minutes}m"


def normalize_rhythm(rhythm: str, effort: str = "moderate") -> str:
    """Map settings from older versions to the simpler rhythm choices."""
    aliases = {"pomodoro": "classic", "long_focus": "long"}
    rhythm = aliases.get(rhythm, rhythm)
    if rhythm == "effort":
        return {
            "easy": "long",
            "demanding": "classic",
            "moderate": "balanced",
        }.get(effort, "balanced")
    return rhythm if rhythm in {*RHYTHM_PRESETS, "custom"} else "balanced"


def resolve_timing(
    rhythm: str, effort: str, settings: dict[str, Any]
) -> tuple[int, int]:
    """Return work and break minutes for the selected rhythm."""
    normalized = normalize_rhythm(rhythm, effort)
    if normalized in RHYTHM_PRESETS:
        return RHYTHM_PRESETS[normalized]
    return (
        max(1, int(settings.get("custom_work_minutes", 35))),
        max(1, int(settings.get("custom_break_minutes", 5))),
    )


def adaptive_break_minutes(
    planned_work_minutes: int,
    planned_break_minutes: int,
    actual_work_seconds: float,
) -> int:
    """Scale a break from the original work/break ratio, never downward.

    Adaptive timing may lengthen the work target, but the user's original rhythm
    remains the reference ratio. A 25/5 rhythm therefore becomes 35/7, 40/8,
    50/10, and so on. The absolute adaptive-break ceiling is 60 minutes; a
    user-selected base break longer than that is never shortened.
    """
    planned_work = max(1, int(planned_work_minutes))
    planned_break = max(1, int(planned_break_minutes))
    actual_minutes = max(0.0, float(actual_work_seconds)) / 60.0
    if actual_minutes <= planned_work:
        return planned_break
    scaled = planned_break * actual_minutes / planned_work
    rounded = max(planned_break, int(math.floor(scaled + 0.5)))
    cap = max(planned_break, ADAPTIVE_MAX_BREAK_MINUTES)
    return min(rounded, cap)


def next_adaptive_work_target(current_target: int, samples: list[float]) -> int:
    """Return a gradual upward-only work target from recent valid blocks."""
    current = max(1, int(current_target))
    valid = [float(value) for value in samples if 5.0 <= float(value) <= ADAPTIVE_MAX_SAMPLE_MINUTES]
    if len(valid) < ADAPTIVE_MIN_BLOCKS:
        return current
    recent = valid[-ADAPTIVE_SAMPLE_WINDOW:]
    average = sum(recent) / len(recent)
    rounded = int(math.floor((average + ADAPTIVE_STEP_MINUTES / 2) / ADAPTIVE_STEP_MINUTES)) * ADAPTIVE_STEP_MINUTES
    if rounded <= current:
        return current
    upper = max(current, ADAPTIVE_MAX_WORK_MINUTES)
    return min(current + ADAPTIVE_STEP_MINUTES, rounded, upper)


def valid_clock_time(value: str) -> bool:
    if not re.fullmatch(r"\d{2}:\d{2}", value):
        return False
    hours, minutes = (int(part) for part in value.split(":"))
    return 0 <= hours <= 23 and 0 <= minutes <= 59


def csv_excel_safe(value: Any) -> str:
    """Return text that Excel will treat as data rather than a formula."""
    text = str(value)
    if text and text[0] in {"=", "+", "-", "@", "\t", "\r", "\n"}:
        return "'" + text
    return text


def sanitize_settings(settings: dict[str, Any]) -> list[str]:
    """Repair valid JSON containing unsafe or obsolete setting values."""
    corrected: list[str] = []
    numeric_keys = (
        "custom_work_minutes",
        "custom_break_minutes",
        "long_break_after",
        "long_break_minutes",
        "lunch_minutes",
    )
    for key in numeric_keys:
        try:
            value = int(settings.get(key, DEFAULT_SETTINGS[key]))
            if not 1 <= value <= 180:
                raise ValueError
        except (TypeError, ValueError):
            value = int(DEFAULT_SETTINGS[key])
            corrected.append(key)
        settings[key] = value

    allowed = {
        "language": {"system", "en", "de", "fa"},
        "theme": {"system", "light", "dark"},
        "sound_style": {"gentle", "system", "custom"},
        "drink_choice": {"off", "coffee", "tea", "either"},
        "personal_mode": {"first_break", "every_break", "daily_time"},
    }
    for key, choices in allowed.items():
        value = settings.get(key)
        if not isinstance(value, str) or value not in choices:
            settings[key] = DEFAULT_SETTINGS[key]
            corrected.append(key)

    for key in (
        "sound",
        "sound_twice",
        "notifications",
        "tray_notice_shown",
        "tray_close_notice_shown_v095",
        "tray_close_notice_shown_v015",
        "friends_welcome_shown",
        "humor_offer_shown",
        "humor",
        "water_reminders",
        "snack_reminders",
        "lunch_enabled",
        "personal_enabled",
        "adaptive_timing",
        "mini_timer",
        "mini_hover_solid",
        "mini_signal",
        "state_colours",
        "defaults_v018_applied",
    ):
        if not isinstance(settings.get(key), bool):
            settings[key] = DEFAULT_SETTINGS[key]
            corrected.append(key)

    for key in ("personal_time", "caffeine_cutoff", "lunch_time"):
        value = settings.get(key)
        if not isinstance(value, str) or not valid_clock_time(value):
            settings[key] = DEFAULT_SETTINGS[key]
            corrected.append(key)

    for key, limit in (("custom_sound_path", 1024), ("personal_text", 500), ("personal_details", 1000)):
        value = settings.get(key, DEFAULT_SETTINGS[key])
        if not isinstance(value, str):
            settings[key] = DEFAULT_SETTINGS[key]
            corrected.append(key)
        else:
            cleaned = value.strip()[:limit]
            if cleaned != value:
                corrected.append(key)
            settings[key] = cleaned

    for key, allowed in (("mini_size", MINI_SIZES), ("mini_opacity", MINI_OPACITY)):
        if settings.get(key) not in allowed:
            settings[key] = DEFAULT_SETTINGS[key]
            corrected.append(key)

    mini_position = settings.get("mini_timer_position", "")
    if not isinstance(mini_position, str) or (mini_position and not re.fullmatch(r"[+-]\d+[+-]\d+", mini_position)):
        settings["mini_timer_position"] = ""
        corrected.append("mini_timer_position")

    geometry = settings.get("window_geometry", "")
    if not isinstance(geometry, str) or (geometry and not re.fullmatch(r"\d+x\d+[+-]\d+[+-]\d+", geometry)):
        settings["window_geometry"] = ""
        corrected.append("window_geometry")

    try:
        work_counter = float(settings.get("work_since_long_break", 0.0))
        if not math.isfinite(work_counter) or work_counter < 0:
            raise ValueError
    except (TypeError, ValueError):
        work_counter = 0.0
        corrected.append("work_since_long_break")
    settings["work_since_long_break"] = work_counter

    for key in ("last_personal_day", "last_drink_day", "last_snack_day", "last_lunch_day", "work_counter_day"):
        value = settings.get(key, "")
        valid = isinstance(value, str)
        if valid and value:
            try:
                date.fromisoformat(value)
            except ValueError:
                valid = False
        if not valid:
            settings[key] = ""
            corrected.append(key)

    water_prompt = settings.get("last_water_prompt", "")
    valid_water = isinstance(water_prompt, str)
    if valid_water and water_prompt:
        try:
            datetime.fromisoformat(water_prompt)
        except ValueError:
            valid_water = False
    if not valid_water:
        settings["last_water_prompt"] = ""
        corrected.append("last_water_prompt")

    raw_profiles = settings.get("adaptive_profiles")
    clean_profiles: dict[str, dict[str, Any]] = {}
    profiles_changed = not isinstance(raw_profiles, dict)
    if isinstance(raw_profiles, dict):
        for rhythm, raw in raw_profiles.items():
            if rhythm not in {*RHYTHM_PRESETS, "custom"} or not isinstance(raw, dict):
                profiles_changed = True
                continue
            try:
                base_work = max(1, min(180, int(raw.get("base_work", 35))))
                base_break = max(1, min(180, int(raw.get("base_break", 5))))
                target = max(base_work, min(180, int(raw.get("target", base_work))))
                sample_target = max(base_work, min(180, int(raw.get("sample_target", target))))
            except (TypeError, ValueError):
                profiles_changed = True
                continue
            samples: list[float] = []
            raw_samples = raw.get("samples", [])
            if isinstance(raw_samples, list):
                for item in raw_samples[-ADAPTIVE_SAMPLE_WINDOW:]:
                    try:
                        value = float(item)
                    except (TypeError, ValueError):
                        profiles_changed = True
                        continue
                    if 5.0 <= value <= ADAPTIVE_MAX_SAMPLE_MINUTES:
                        samples.append(round(value, 3))
                    else:
                        profiles_changed = True
            else:
                profiles_changed = True
            clean_profiles[rhythm] = {
                "base_work": base_work,
                "base_break": base_break,
                "target": target,
                "sample_target": sample_target,
                "samples": samples,
            }
    if profiles_changed or raw_profiles != clean_profiles:
        settings["adaptive_profiles"] = clean_profiles
        corrected.append("adaptive_profiles")

    return corrected


def migrate_legacy_settings(settings: dict[str, Any], loaded_keys: set[str]) -> bool:
    """Preserve a customized effort timer when upgrading from version 0.3."""
    if not loaded_keys or "custom_work_minutes" in loaded_keys:
        return False
    effort = settings.get("last_effort", "moderate")
    if effort not in {"easy", "moderate", "demanding"}:
        effort = "moderate"
    try:
        work = max(1, int(settings.get(f"work_{effort}", 35)))
        rest = max(1, int(settings.get(f"break_{effort}", 5)))
    except (TypeError, ValueError):
        work, rest = 35, 5
    settings["custom_work_minutes"] = work
    settings["custom_break_minutes"] = rest
    if settings.get("last_rhythm") == "effort":
        matching = next(
            (key for key, timing in RHYTHM_PRESETS.items() if timing == (work, rest)),
            "custom",
        )
        settings["last_rhythm"] = matching
    return True


def create_gentle_chime(path: Path) -> None:
    """Create a quiet, original three-note WAV chime."""
    path.parent.mkdir(parents=True, exist_ok=True)
    sample_rate = 44_100
    duration = 3.2
    notes = (
        (0.00, 1.65, 392.00, 0.85),
        (0.38, 1.75, 493.88, 0.72),
        (0.78, 2.20, 587.33, 0.58),
    )
    frames = bytearray()
    for index in range(int(sample_rate * duration)):
        current = index / sample_rate
        value = 0.0
        for start, length, frequency, strength in notes:
            local = current - start
            if not 0.0 <= local <= length:
                continue
            attack = min(1.0, local / 0.08)
            release = max(0.0, 1.0 - local / length) ** 2.2
            envelope = attack * release
            tone = math.sin(2.0 * math.pi * frequency * local)
            tone += 0.12 * math.sin(2.0 * math.pi * frequency * 2.0 * local)
            value += strength * envelope * tone
        fade = min(1.0, current / 0.05, max(0.0, duration - current) / 0.25)
        sample = int(max(-1.0, min(1.0, value * 0.105 * fade)) * 32767)
        frames.extend(struct.pack("<h", sample))
    with wave.open(str(path), "wb") as audio:
        audio.setnchannels(1)
        audio.setsampwidth(2)
        audio.setframerate(sample_rate)
        audio.writeframes(frames)



class WindowsTray:
    """Windows notification-area integration backed by infi.systray.

    infi.systray owns the Windows message loop and right-click popup behavior.
    Callbacks only put small action names on a Queue; all Tk work remains on the
    Tk main thread.  pywin32 is used only to attach balloon notifications to the
    already-registered tray icon.
    """

    def __init__(
        self,
        actions: "queue.Queue[str]",
        labels: dict[str, str] | None = None,
        icon_path: str | None = None,
    ) -> None:
        self.actions = actions
        self.available = False
        self._icon_path = icon_path
        self._systray: Any | None = None
        self._stopping = False
        self._lock = threading.Lock()
        self._last_hover_text: str | None = None
        self._snapshot: dict[str, Any] = {
            "status": APP_NAME,
            "open": APP_NAME,
            "pause_resume": "Pause / Resume",
            "break_label": "Break now",
            "finish": "Finish",
            "about": "About Taktpause",
            "quit": "Quit",
        }
        if labels:
            self._snapshot.update({k: str(v) for k, v in labels.items()})

    def _callback(self, action: str) -> Any:
        def callback(_systray: Any) -> None:
            self.actions.put(action)
        return callback

    def _menu_options(self) -> tuple[Any, ...]:
        with self._lock:
            snapshot = dict(self._snapshot)
        return (
            (str(snapshot.get("open", APP_NAME)), None, self._callback("open")),
            (str(snapshot.get("pause_resume", "Pause / Resume")), None, self._callback("pause")),
            (str(snapshot.get("break_label", "Break now")), None, self._callback("break")),
            (str(snapshot.get("finish", "Finish")), None, self._callback("finish")),
            (str(snapshot.get("about", "About Taktpause")), None, self._callback("about")),
        )

    def _on_library_quit(self, _systray: Any) -> None:
        # infi.systray calls on_quit both for a user-selected Quit and for our
        # programmatic shutdown. Only the former should ask Tk to exit.
        if not self._stopping:
            self.actions.put("quit")

    def start(self) -> bool:
        if platform.system() != "Windows":
            return False
        if InfiSysTrayIcon is None:
            LOGGER.warning("System tray unavailable because infi.systray is not installed or was not bundled")
            return False
        if self.available:
            return True

        with self._lock:
            hover_text = str(self._snapshot.get("status", APP_NAME))[:127]
            quit_label = str(self._snapshot.get("quit", "Quit"))
        try:
            self._stopping = False
            tray = InfiSysTrayIcon(
                self._icon_path,
                hover_text,
                self._menu_options(),
                on_quit=self._on_library_quit,
                default_menu_index=0,
                window_class_name=f"TaktpauseTray-{os.getpid()}",
            )
            # infi.systray always appends its own Quit entry. Localize that text
            # without changing any of the library's message-loop behavior.
            try:
                if getattr(tray, "_menu_options", None):
                    last = tray._menu_options[-1]
                    tray._menu_options[-1] = (quit_label, last[1], last[2], last[3])
            except Exception:
                LOGGER.debug("Could not localize infi.systray Quit label", exc_info=True)

            self._systray = tray
            tray.start()

            # start() launches the library message loop asynchronously. Give it
            # a brief moment to create its hidden owner window before declaring
            # tray availability to the rest of the app.
            deadline = time.monotonic() + 1.5
            while time.monotonic() < deadline:
                if getattr(tray, "_hwnd", None):
                    self.available = True
                    break
                time.sleep(0.01)
            if not self.available:
                LOGGER.warning("System tray did not become ready in time")
            else:
                self._last_hover_text = hover_text
                LOGGER.info("System tray ready")
            return self.available
        except Exception:
            LOGGER.exception("Could not start Windows System Tray integration")
            self.available = False
            self._systray = None
            return False

    def update(self, **snapshot: Any) -> None:
        with self._lock:
            self._snapshot.update(snapshot)
            hover_text = str(self._snapshot.get("status", APP_NAME))[:127]
        tray = self._systray
        if not self.available or tray is None or hover_text == self._last_hover_text:
            return
        try:
            tray.update(hover_text=hover_text)
            self._last_hover_text = hover_text
        except Exception:
            # A transient Explorer restart should not pause or crash the timer.
            LOGGER.exception("Could not update tray status")

    def set_menu_labels(self, labels: dict[str, str]) -> None:
        """Refresh the native menu only when its translated labels actually change.

        infi.systray builds and caches its popup menu. Restarting that integration
        on a language change is safer than mutating its private Win32 menu while
        it is live, and it keeps ordinary timer ticks away from tray-menu code.
        """
        with self._lock:
            changed = any(str(self._snapshot.get(key, "")) != str(value) for key, value in labels.items())
            if not changed:
                return
            self._snapshot.update({key: str(value) for key, value in labels.items()})
        if not self.available:
            return
        self.stop()
        self.start()

    def notify(self, title: str, body: str) -> bool:
        """Show a Windows balloon on the existing infi.systray icon."""
        tray = self._systray
        hwnd = getattr(tray, "_hwnd", None) if tray is not None else None
        if not self.available or not hwnd or win32gui is None:
            return False
        try:
            # NIF_INFO modifies only notification fields of the icon already
            # registered by infi.systray; it does not replace its callback/menu.
            nid = (
                int(hwnd),
                0,
                win32gui.NIF_INFO,
                0,
                0,
                "",
                str(body)[:255],
                8000,
                str(title)[:63],
                win32gui.NIIF_INFO,
            )
            win32gui.Shell_NotifyIcon(win32gui.NIM_MODIFY, nid)
            return True
        except Exception:
            LOGGER.exception("Could not show Windows tray notification")
            return False

    def stop(self) -> None:
        tray = self._systray
        self.available = False
        self._systray = None
        self._last_hover_text = None
        if tray is None:
            return
        self._stopping = True
        try:
            tray.shutdown()
        except Exception:
            LOGGER.exception("Could not close tray integration")
        finally:
            self._stopping = False


class TaktpauseApp:
    def __init__(self) -> None:
        if tk is None or ttk is None:
            raise RuntimeError("Tkinter is not available in this Python installation.")

        self.data_dir = application_data_dir()
        configure_logging(self.data_dir)
        LOGGER.info(
            "Starting %s %s on %s %s (Python %s)",
            APP_NAME, APP_VERSION, platform.system(), platform.release(), platform.python_version(),
        )
        maintain_storage_limits(self.data_dir)
        create_upgrade_backup(self.data_dir)
        maintain_storage_limits(self.data_dir)
        self.settings_store = JsonStore(self.data_dir / "settings.json", DEFAULT_SETTINGS)
        self.settings_data = self.settings_store.data
        self.custom_messages = CustomMessageStore(self.data_dir / "custom_messages.json")
        if migrate_legacy_settings(self.settings_data, self.settings_store.loaded_keys):
            LOGGER.info("Migrated the earlier effort timer settings")
        corrected_settings = sanitize_settings(self.settings_data)
        if corrected_settings:
            LOGGER.warning("Corrected invalid settings: %s", ", ".join(corrected_settings))
        if apply_v018_defaults(self.settings_data):
            LOGGER.info("Turned on the 0.18 default options once")
            self.settings_store.save()
        self.history = HistoryStore(self.data_dir / "history.json")
        self.task_history = TaskHistoryStore(self.data_dir / "task_history.json")
        self.week_notes = JsonStore(self.data_dir / "weekly_notes.json", {"weeks": {}})
        if not isinstance(self.week_notes.data.get("weeks"), dict):
            self.week_notes.data["weeks"] = {}
            self.week_notes.save()
        self.session_store = JsonStore(self.data_dir / "current_session.json", {})
        self.events = EventStore(self.data_dir / "events.jsonl")
        maintain_storage_limits(self.data_dir)
        recovered_tasks = self.task_history.sync_from_events(self.events.path)
        if recovered_tasks:
            LOGGER.info("Recovered %d task name(s) for autocomplete from local events", recovered_tasks)
        if isinstance(self.session_store.data, dict):
            pending_task = str(self.session_store.data.get("task", "")).strip()
            if pending_task:
                self.task_history.ensure(
                    pending_task,
                    str(self.session_store.data.get("saved_at", "")),
                )
        self.engine = TimerEngine()
        today = date.today().isoformat()
        if self.settings_data.get("work_counter_day") == today:
            try:
                self.engine.work_since_long_break = max(
                    0.0, float(self.settings_data.get("work_since_long_break", 0.0))
                )
            except (TypeError, ValueError):
                self.engine.work_since_long_break = 0.0
        else:
            self.settings_data["work_counter_day"] = today
            self.settings_data["work_since_long_break"] = 0.0

        self.lang = self._resolved_language()
        self.recent_custom_messages: deque[str] = deque(maxlen=6)
        self.colors = self._resolved_colors()
        self._configure_dpi()
        # On Linux the window class must match the desktop entry's
        # StartupWMClass, or the dock shows a generic "Tk" entry.
        self.root = tk.Tk(className=APP_NAME) if platform.system() == "Linux" else tk.Tk()
        self.ui_scale = self._compute_ui_scale()
        self.root.title(self.t("app_title"))
        saved_geometry = str(self.settings_data.get("window_geometry", ""))
        available_width = max(self._px(420), self.root.winfo_screenwidth() - self._px(80))
        available_height = max(self._px(480), self.root.winfo_screenheight() - self._px(80))
        default_width = min(self._px(560), available_width)
        default_height = min(self._px(720), available_height)
        self.root.geometry(f"{default_width}x{default_height}")
        self._restore_window_geometry(saved_geometry)
        self.root.minsize(
            min(self._px(470), available_width),
            min(self._px(580), available_height),
        )
        self.root.protocol("WM_DELETE_WINDOW", self._window_close)
        self.root.report_callback_exception = self._report_callback_exception

        self.task = ""
        self.session_id = ""
        self.work_block_id = ""
        self.current_activity: tuple[str, str, str] | None = None
        self.activity_humor_context: str | None = None
        self.activity_index = 0
        self.break_count = 0
        self.recent_humor: deque[str] = deque(maxlen=6)
        self._humor_cache_key: tuple[str, str, tuple[tuple[str, Any], ...]] | None = None
        self._humor_cache_text = ""
        self.humor_hint: str | None = None
        self._earlier_panel_close: Any | None = None
        self.pending_snapshot = self._load_pending_snapshot()
        self.personal_snooze_until: datetime | None = None
        self.personal_popup_open = False
        self.minimize_notice_shown = False
        self.dialog_open = False
        self.exiting = False
        self.last_time_correction: dict[str, Any] | None = None
        self.pause_started_at: datetime | None = None
        self.mini_window: Any | None = None
        self.mini_canvas: Any | None = None
        self.mini_dismissed = False
        self.mini_drag: dict[str, Any] = {}
        self.tray_actions: "queue.Queue[str]" = queue.Queue()
        self.tray = WindowsTray(
            self.tray_actions,
            labels=self._tray_menu_labels(),
            icon_path=(
                ensure_tray_icon(self.data_dir / "taktpause_tray.ico")
                if platform.system() == "Windows" else None
            ),
        )

        self.task_var = tk.StringVar(value="")
        self.already_var = tk.StringVar(value="0")
        self.effort_var = tk.StringVar(value=self.settings_data.get("last_effort", "moderate"))
        saved_rhythm = str(self.settings_data.get("last_rhythm", "balanced"))
        self.rhythm_key = normalize_rhythm(saved_rhythm, self.effort_var.get())
        self.settings_data["last_rhythm"] = self.rhythm_key
        self.rhythm_label_var = tk.StringVar(value="")
        self.adaptive_var = tk.BooleanVar(value=bool(self.settings_data.get("adaptive_timing", False)))
        self.adaptive_notice_minutes: int | None = None

        self.last_tick = time.monotonic()
        self.last_wall_tick = time.time()
        self.last_save = self.last_tick
        self.dynamic_timer = None
        self.dynamic_note = None
        self.dynamic_progress = None
        self.dynamic_break_button = None
        self.timer_canvas = None
        self.timer_arc = None
        self.timer_text = None
        self.content = None
        self.content_canvas = None
        self.content_scrollbar = None
        self.content_window = None

        self._apply_style()
        self._set_window_icon()
        self.tray.start()
        self._build_shell()
        self._render()
        self._sync_tray_state()
        self.root.bind("<Control-p>", lambda _event: self._toggle_pause())
        self.root.bind("<Control-b>", lambda _event: self._take_break())
        interrupted_saved_at = ""
        interrupted_session_id = ""
        interrupted_state = ""
        if isinstance(self.pending_snapshot, dict):
            interrupted_saved_at = str(self.pending_snapshot.get("saved_at", ""))
            interrupted_session_id = str(self.pending_snapshot.get("session_id", ""))
            saved_engine = self.pending_snapshot.get("engine")
            if isinstance(saved_engine, dict):
                interrupted_state = str(saved_engine.get("state", ""))
        self.events.append(
            "app_started",
            version=APP_VERSION,
            interrupted_saved_at=interrupted_saved_at or None,
            interrupted_session_id=interrupted_session_id or None,
            interrupted_state=interrupted_state or None,
        )
        self.root.after_idle(self._show_storage_warnings)
        self.root.after(500, self._show_first_run_help)
        self.root.after(250, self._tick)

    @staticmethod
    def _contains_rtl_text(value: str) -> bool:
        return bool(re.search(r"[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF]", value))

    @staticmethod
    def _strip_direction_controls(value: str) -> str:
        """Remove direction controls left by older builds or copied text."""
        return value.translate({
            ord("\u061c"): None,  # Arabic letter mark
            ord("\u200e"): None,  # LRM
            ord("\u200f"): None,  # RLM
            ord("\u202a"): None,  # LRE
            ord("\u202b"): None,  # RLE
            ord("\u202c"): None,  # PDF
            ord("\u202d"): None,  # LRO
            ord("\u202e"): None,  # RLO
            ord("\u2066"): None,  # LRI
            ord("\u2067"): None,  # RLI
            ord("\u2068"): None,  # FSI
            ord("\u2069"): None,  # PDI
        })

    @staticmethod
    def _contains_presentation_forms(value: str) -> bool:
        # arabic_reshaper outputs Arabic Presentation Forms.  Seeing one means
        # the string has already been prepared for Tk and must not be reordered
        # a second time by _apply_directionality().
        return bool(re.search(r"[\uFB50-\uFDFF\uFE70-\uFEFF]", value))

    def _rtl_display(self, text: str) -> str:
        if self.lang != "fa":
            return text
        text = self._strip_direction_controls(str(text))
        if not self._contains_rtl_text(text) and not self._contains_presentation_forms(text):
            return text
        if self._contains_presentation_forms(text):
            return text
        if arabic_reshaper is None or bidi_get_display is None:
            # Raw logical Persian is preferable to inserting bidi control
            # characters that some Tk builds render visibly.  The About screen
            # reports whether full Persian rendering support is available.
            return text
        try:
            reshaped = arabic_reshaper.reshape(text)
            display = bidi_get_display(reshaped, base_dir="R")
            cache = self.__dict__.setdefault("_rtl_logical", {})
            if len(cache) > 4000:
                cache.clear()
            cache[display] = text
            return display
        except Exception:
            LOGGER.exception("Could not prepare Persian text for Tk display")
            return text

    def _rtl_logical_text(self, text: str) -> str | None:
        """Return reading-order text for a label, or None if it cannot be known."""
        cache = self.__dict__.get("_rtl_logical", {})
        if text in cache:
            return cache[text]
        if self._contains_presentation_forms(text):
            return None
        return self._strip_direction_controls(text)

    def _language_name_fa(self) -> str:
        text = self.t("persian")
        if (
            self.lang != "fa"
            and platform.system() != "Windows"
            and arabic_reshaper is not None
            and bidi_get_display is not None
        ):
            try:
                return bidi_get_display(arabic_reshaper.reshape(text), base_dir="R")
            except Exception:
                LOGGER.debug("Could not prepare the Persian language name", exc_info=True)
        return text

    def _mixed_display(self, text: str) -> str:
        """Prepare Persian text assembled outside the translation catalogue."""
        return self._rtl_display(self._strip_direction_controls(str(text)))

    def _message_format_values(self) -> dict[str, Any]:
        engine = getattr(self, "engine", None)
        planned_work = max(1, int(getattr(engine, "planned_work_minutes", 1) or 1))
        planned_break = max(1, int(getattr(engine, "planned_break_minutes", 1) or 1))
        task = str(getattr(self, "task", "") or "").strip()
        if not task:
            task = TEXT.get(self.lang, TEXT["en"]).get("focus_session", "Focus session")
        return {
            "minutes": planned_work,
            "rest": planned_break,
            "task": task,
            "time": datetime.now().strftime("%H:%M"),
        }

    def _format_message_template(self, template: str, **values: Any) -> str:
        merged = self._message_format_values()
        merged.update(values)
        try:
            return str(template).format(**merged)
        except (KeyError, ValueError, IndexError):
            # A user's literal braces should never make a reminder fail to render.
            return str(template)

    def _custom_message_template(self, category: str, language: str | None = None) -> str:
        store = getattr(self, "custom_messages", None)
        if store is None:
            return ""
        language = language or getattr(self, "lang", "en")
        lines = store.active_lines(language, category)
        if not lines:
            return ""
        recent = getattr(self, "recent_custom_messages", None)
        candidates = [line for line in lines if recent is None or line not in recent]
        if not candidates:
            candidates = lines
        chosen = random.choice(candidates)
        if recent is not None:
            recent.append(chosen)
        return chosen

    def _custom_message_text(self, category: str, **values: Any) -> str:
        template = self._custom_message_template(category)
        return self._format_message_template(template, **values) if template else ""

    def _t_plain(self, key: str, **values: Any) -> str:
        """Return logical-order text for native Windows controls such as tray menus."""
        text = TEXT[self.lang].get(key, TEXT["en"].get(key, key))
        category = VOICE_TEXT_KEY_TO_CATEGORY.get(key)
        if category:
            custom = self._custom_message_template(category)
            if custom:
                text = custom
        if values or category:
            text = self._format_message_template(text, **values)
        return self._strip_direction_controls(text)

    def t(self, key: str, **values: Any) -> str:
        return self._rtl_display(self._t_plain(key, **values))

    def _record_event(self, event: str, **details: Any) -> None:
        self.events.append(
            event,
            session_id=self.session_id or None,
            work_block_id=self.work_block_id or None,
            state=self.engine.state.value,
            rhythm=self.engine.rhythm,
            planned_work_minutes=self.engine.planned_work_minutes,
            planned_break_minutes=self.engine.planned_break_minutes,
            task=self.task or None,
            **details,
        )

    def _resolved_language(self) -> str:
        choice = self.settings_data.get("language", "system")
        if choice == "system":
            return system_language()
        return choice if choice in {"en", "de", "fa"} else "en"

    def _resolved_colors(self) -> dict[str, str]:
        choice = self.settings_data.get("theme", "system")
        dark = system_uses_dark_theme() if choice == "system" else choice == "dark"
        return DARK if dark else LIGHT

    def _configure_dpi(self) -> None:
        if platform.system() == "Windows":
            try:
                import ctypes

                ctypes.windll.shcore.SetProcessDpiAwareness(1)
            except (AttributeError, OSError):
                pass

    def _compute_ui_scale(self) -> float:
        """Return a geometry scale relative to Tk's usual 96-DPI Windows baseline."""
        try:
            tk_scaling = float(self.root.tk.call("tk", "scaling"))
        except (tk.TclError, TypeError, ValueError):
            tk_scaling = 1.3333
        # Tk fonts are point-based and already scale with DPI. Pixel geometry is not,
        # so scale only the pixel measurements used by canvases and window minimums.
        return max(0.85, min(2.5, tk_scaling / 1.3333))

    def _px(self, value: float) -> int:
        return max(1, int(round(float(value) * float(getattr(self, "ui_scale", 1.0)))))

    def _pxf(self, value: float) -> float:
        return float(value) * float(getattr(self, "ui_scale", 1.0))

    def _restore_window_geometry(self, geometry: str) -> None:
        match = re.fullmatch(r"(\d+)x(\d+)([+-]\d+)([+-]\d+)", geometry)
        if not match:
            return
        width, height, x, y = (int(value) for value in match.groups())
        left = top = 0
        screen_width = self.root.winfo_screenwidth()
        screen_height = self.root.winfo_screenheight()
        if platform.system() == "Windows":
            try:
                import ctypes

                user32 = ctypes.windll.user32
                # Virtual-screen metrics include monitors positioned left/above
                # the primary display, where coordinates are legitimately negative.
                left = int(user32.GetSystemMetrics(76))   # SM_XVIRTUALSCREEN
                top = int(user32.GetSystemMetrics(77))    # SM_YVIRTUALSCREEN
                virtual_width = int(user32.GetSystemMetrics(78))   # SM_CXVIRTUALSCREEN
                virtual_height = int(user32.GetSystemMetrics(79))  # SM_CYVIRTUALSCREEN
                if virtual_width > 0 and virtual_height > 0:
                    screen_width = virtual_width
                    screen_height = virtual_height
            except (AttributeError, OSError):
                pass
        width = min(max(470, width), screen_width)
        height = min(max(580, height), screen_height)
        max_x = max(left, left + screen_width - width)
        max_y = max(top, top + screen_height - height)
        x = min(max(left, x), max_x)
        y = min(max(top, y), max_y)
        self.root.geometry(f"{width}x{height}{x:+d}{y:+d}")

    def _set_window_icon(self) -> None:
        """Show the real app mark, not Tk's default feather.

        Tk 8.6 reads PNG from base64, so the window icon is the same artwork as
        the notification-area icon rather than a hand-plotted approximation.
        """
        self.app_icon = None
        try:
            self.app_icon = tk.PhotoImage(data=APP_ICON_PNG_B64)
            self.root.iconphoto(True, self.app_icon)
        except tk.TclError:
            LOGGER.debug("Could not apply the embedded window icon", exc_info=True)
        if platform.system() == "Windows":
            # The .ico additionally gives the taskbar and Alt-Tab the right sizes.
            try:
                ico_path = ensure_tray_icon(self.data_dir / "taktpause_tray.ico")
                if ico_path:
                    self.root.iconbitmap(default=ico_path)
            except tk.TclError:
                LOGGER.debug("Could not apply the window .ico", exc_info=True)

    def _tray_menu_labels(self) -> dict[str, str]:
        return {
            "open": self._t_plain("tray_open"),
            "pause_resume": f"{self._t_plain('pause')} / {self._t_plain('resume')}",
            "break_label": self._t_plain("take_break"),
            "finish": self._t_plain("finish"),
            "about": self._t_plain("tray_about"),
            "quit": self._t_plain("tray_quit"),
        }

    def _reset_tick_clocks(self) -> None:
        self.last_tick = time.monotonic()
        self.last_wall_tick = time.time()

    def _run_dialog(self, dialog: Any, *args: Any, **kwargs: Any) -> Any:
        """Run a blocking Tk dialog without mistaking it for computer sleep."""
        self.dialog_open = True
        self._reset_tick_clocks()
        try:
            return dialog(*args, **kwargs)
        finally:
            self._reset_tick_clocks()
            self.dialog_open = False

    def _show_storage_warnings(self) -> None:
        damaged = [
            store.path.name
            for store in (self.settings_store, self.custom_messages, self.history, self.task_history, self.week_notes, self.session_store)
            if store.load_error
        ]
        if damaged:
            self._run_dialog(
                messagebox.showwarning,
                self.t("load_warning_title"),
                self.t("load_warning_body", files=", ".join(damaged)),
                parent=self.root,
            )

    def _show_first_run_help(self) -> None:
        if bool(self.settings_data.get("friends_welcome_shown", False)) or self.exiting:
            return
        self.settings_data["friends_welcome_shown"] = True
        try:
            self.settings_store.save()
        except OSError:
            LOGGER.exception("Could not remember that the quick-start message was shown")
        self._run_dialog(
            messagebox.showinfo,
            self.t("friends_welcome_title"),
            self.t("friends_welcome_body"),
            parent=self.root,
        )

    def _report_callback_exception(
        self, exception_type: type[BaseException], exception: BaseException, trace: Any
    ) -> None:
        LOGGER.error(
            "Unhandled interface error\n%s",
            "".join(traceback.format_exception(exception_type, exception, trace)),
        )
        timer_was_counting = self.engine.counting
        if timer_was_counting:
            self.engine.pause()
        try:
            self._save_all()
        except Exception:
            LOGGER.exception("Could not save after an interface error")
        try:
            self._render()
        except Exception:
            LOGGER.exception("Could not redraw after an interface error")
        try:
            self._run_dialog(
                messagebox.showerror,
                self.t("unexpected_error_title"),
                self.t("unexpected_error_body") if timer_was_counting else self.t("unexpected_error_body_idle"),
                parent=self.root,
            )
        except Exception:
            LOGGER.exception("Could not show the interface error")

    def _flash_window(self) -> None:
        if platform.system() != "Windows":
            return
        try:
            import ctypes

            class FlashInfo(ctypes.Structure):
                _fields_ = [
                    ("cbSize", ctypes.c_uint),
                    ("hwnd", ctypes.c_void_p),
                    ("dwFlags", ctypes.c_uint),
                    ("uCount", ctypes.c_uint),
                    ("dwTimeout", ctypes.c_uint),
                ]

            self.root.update_idletasks()
            ctypes.windll.user32.GetParent.restype = ctypes.c_void_p
            handle = ctypes.windll.user32.GetParent(self.root.winfo_id())
            info = FlashInfo(ctypes.sizeof(FlashInfo), handle, 0x00000006, 3, 0)
            ctypes.windll.user32.FlashWindowEx(ctypes.byref(info))
        except (AttributeError, OSError, tk.TclError):
            LOGGER.exception("Could not flash the taskbar button")

    def _resolve_font_families(self) -> None:
        """Pick the best available family for each role, once per process."""
        if getattr(self, "_font_families", None):
            return
        try:
            import tkinter.font as tkfont

            available = {name.lower() for name in tkfont.families(self.root)}
        except Exception:
            available = set()

        def first(candidates: tuple[str, ...], fallback: str) -> str:
            for name in candidates:
                if name.lower() in available:
                    return name
            return fallback

        self._font_families = {
            "ui": first(UI_FONT_CANDIDATES, "TkDefaultFont"),
            "semi": first(UI_SEMIBOLD_CANDIDATES, ""),
            "mono": first(MONO_FONT_CANDIDATES, "TkFixedFont"),
        }
        if not self._font_families["semi"]:
            # No semibold face installed: draw the UI family in bold.
            self._font_families["semi"] = self._font_families["ui"]
        # If no real semibold face exists, emulate it with a bold weight.
        self._semibold_is_family = self._font_families["semi"] != self._font_families["ui"]

    def _font(self, role: str = "ui", size: int = 10, bold: bool = False) -> tuple[Any, ...]:
        self._resolve_font_families()
        family = self._font_families.get(role, self._font_families["ui"])
        if role == "semi" and not self._semibold_is_family:
            return (family, size, "bold")
        return (family, size, "bold") if bold else (family, size)

    def _label(self, parent: Any, *args: Any, style: str = "TLabel", **kwargs: Any) -> Any:
        """Flat Tk label with explicit colours.

        Some Windows/sv-ttk combinations paint a white themed patch behind ttk
        label text even when a background is configured.  Text is a large part
        of Taktpause's visual language, so use a plain Tk label for display text
        and make its surface explicit.
        """
        specs: dict[str, tuple[str, str, tuple[Any, ...]]] = {
            "TLabel": (self.colors["bg"], self.colors["text"], self._font("ui", 10)),
            "Muted.TLabel": (self.colors["bg"], self.colors["muted"], self._font("ui", 9)),
            "Title.TLabel": (self.colors["bg"], self.colors["text"], self._font("semi", 19)),
            "Section.TLabel": (self.colors["bg"], self.colors["text"], self._font("semi", 11)),
            "Card.TLabel": (self.colors["surface"], self.colors["text"], self._font("ui", 10)),
            "CardMuted.TLabel": (self.colors["surface"], self.colors["muted"], self._font("ui", 9)),
            "Error.TLabel": (self.colors["bg"], self.colors["error"], self._font("ui", 9)),
            "CardError.TLabel": (self.colors["surface"], self.colors["error"], self._font("ui", 9)),
            "CardTitle.TLabel": (self.colors["surface"], self.colors["text"], self._font("semi", 13)),
            "Brand.TLabel": (self.colors["bg"], self.colors["text"], self._font("semi", 12)),
            "BrandTag.TLabel": (self.colors["bg"], self.colors["muted"], self._font("mono", 8)),
            "Mono.TLabel": (self.colors["bg"], self.colors["muted"], self._font("mono", 9)),
            "CardMono.TLabel": (self.colors["surface"], self.colors["muted"], self._font("mono", 9)),
            "Chip.TLabel": (self.colors["chip_bg"], self.colors["chip_text"], self._font("mono", 9)),
            "CardStat.TLabel": (self.colors["surface"], self.colors["text"], self._font("semi", 15)),
            "CardFigure.TLabel": (self.colors["surface"], self.colors["text"], self._font("mono", 16, bold=True)),
            "Timer.TLabel": (self.colors["bg"], self.colors["text"], self._font("mono", 44, bold=True)),
        }
        background, foreground, font = specs.get(style, specs["TLabel"])
        kwargs.setdefault("background", background)
        kwargs.setdefault("foreground", foreground)
        kwargs.setdefault("font", font)
        kwargs.setdefault("borderwidth", 0)
        kwargs.setdefault("highlightthickness", 0)
        if self.lang == "fa" and kwargs.get("wraplength"):
            label_class = rtl_wrap_label_class()
            if label_class is not None:
                return label_class(parent, self, *args, **kwargs)
        return tk.Label(parent, *args, **kwargs)

    def _palette_for_state(self) -> dict[str, str]:
        """Base light/dark palette, tinted for the current timer state."""
        base = getattr(self, "_base_colors", None) or self._resolved_colors()
        engine = getattr(self, "engine", None)
        if engine is None or not self.settings_data.get("state_colours", True):
            return base
        state = engine.state
        if state == TimerState.PAUSED and engine.paused_from:
            state = engine.paused_from
        if state == TimerState.RESTING:
            return state_palette(base, "break")
        if state in {TimerState.WORK_DUE, TimerState.REST_COMPLETE}:
            return state_palette(base, "due")
        return base

    def _other_popups_open(self) -> bool:
        """True while a dialog is open; its colours must not change underneath it."""
        try:
            for child in self.root.winfo_children():
                if isinstance(child, tk.Toplevel) and child is not self.mini_window and child.winfo_exists():
                    return True
        except tk.TclError:
            return False
        return False

    def _apply_style(self, palette: dict[str, str] | None = None) -> None:
        if palette is None:
            self._base_colors = self._resolved_colors()
            palette = self._palette_for_state()
        self.colors = palette
        self._resolve_font_families()
        self.root.configure(background=self.colors["bg"])
        style = ttk.Style(self.root)
        theme_name = "dark" if self.colors.get("is_dark") else "light"
        if sv_ttk is not None:
            if getattr(self, "_sv_theme", None) != theme_name:
                sv_ttk.set_theme(theme_name)
                self._sv_theme = theme_name
        else:
            # Native Windows themes can ignore a custom button background while
            # accepting its white foreground, producing an apparently blank
            # button. Clam renders both colors consistently.
            style.theme_use("clam")

        body = self._font("ui", 10)
        small = self._font("ui", 9)

        style.configure(
            ".", background=self.colors["bg"], foreground=self.colors["text"], font=body
        )
        style.configure("TFrame", background=self.colors["bg"])
        # NOTE: not "Card.TFrame" - sv_ttk defines that name itself with an image
        # element, which overrides any background given here.
        # Borderless: the surface is told apart by its fill, and a border here
        # would also outline the plain grouping frames that reuse this style.
        style.configure("Surface.TFrame", background=self.colors["surface"], relief="flat", borderwidth=0)
        style.configure("Rule.TFrame", background=self.colors["rule"])
        style.configure("Chip.TFrame", background=self.colors["chip_bg"], relief="flat")
        style.configure("Accent.TFrame", background=self.colors["accent"])

        style.configure("TLabel", background=self.colors["bg"], foreground=self.colors["text"])
        style.configure("Card.TLabel", background=self.colors["surface"], foreground=self.colors["text"])
        style.configure("Muted.TLabel", background=self.colors["bg"], foreground=self.colors["muted"], font=small)
        style.configure("CardMuted.TLabel", background=self.colors["surface"], foreground=self.colors["muted"], font=small)
        style.configure("Error.TLabel", background=self.colors["bg"], foreground=self.colors["error"], font=small)
        style.configure("CardError.TLabel", background=self.colors["surface"], foreground=self.colors["error"], font=small)

        # Display type: one large title, nothing else competing with it.
        style.configure("Title.TLabel", font=self._font("semi", 19), background=self.colors["bg"])
        style.configure("Section.TLabel", font=self._font("semi", 11), background=self.colors["bg"])
        style.configure("CardTitle.TLabel", font=self._font("semi", 13), background=self.colors["surface"])

        # The wordmark and the small technical captions carry the character:
        # the name in the accent, measurements in mono.
        style.configure(
            "Brand.TLabel",
            font=self._font("semi", 12),
            background=self.colors["bg"],
            foreground=self.colors["text"],
        )
        style.configure(
            "BrandTag.TLabel",
            font=self._font("mono", 8),
            background=self.colors["bg"],
            foreground=self.colors["muted"],
        )
        style.configure(
            "Mono.TLabel",
            font=self._font("mono", 9),
            background=self.colors["bg"],
            foreground=self.colors["muted"],
        )
        style.configure(
            "CardMono.TLabel",
            font=self._font("mono", 9),
            background=self.colors["surface"],
            foreground=self.colors["muted"],
        )
        style.configure(
            "Chip.TLabel",
            font=self._font("mono", 9),
            background=self.colors["chip_bg"],
            foreground=self.colors["chip_text"],
        )
        style.configure(
            "CardStat.TLabel",
            font=self._font("semi", 15),
            background=self.colors["surface"],
            foreground=self.colors["text"],
        )
        style.configure(
            "CardFigure.TLabel",
            font=self._font("mono", 16, bold=True),
            background=self.colors["surface"],
            foreground=self.colors["text"],
        )
        style.configure("Timer.TLabel", font=self._font("mono", 44, bold=True), background=self.colors["bg"])

        style.configure(
            "TButton", padding=(14, 8), background=self.colors["field"],
            foreground=self.colors["text"], borderwidth=1, font=body,
        )
        style.map("TButton", background=[("active", self.colors["soft"])])
        style.configure(
            "Primary.TButton",
            padding=(16, 10),
            background=self.colors["accent"],
            foreground=self.colors["on_accent"],
            borderwidth=0,
            font=self._font("semi", 10),
        )
        if sv_ttk is not None:
            try:
                style.layout("Primary.TButton", style.layout("Accent.TButton"))
            except tk.TclError:
                pass
        style.map(
            "Primary.TButton",
            background=[("pressed", self.colors["accent_hover"]), ("active", self.colors["accent_hover"])],
            foreground=[("disabled", self.colors["muted"]), ("!disabled", self.colors["on_accent"])],
        )
        try:
            style.layout(
                "Link.TButton",
                [("Button.padding", {"sticky": "nswe", "children": [
                    ("Button.label", {"sticky": "nswe"})]})],
            )
        except tk.TclError:
            pass
        style.configure(
            "Link.TButton", padding=(4, 4), borderwidth=0, relief="flat",
            background=self.colors["bg"], foreground=self.colors["muted"], font=small,
        )
        style.map(
            "Link.TButton",
            background=[("active", self.colors["bg"]), ("pressed", self.colors["bg"])],
            foreground=[("active", self.colors["accent"]), ("pressed", self.colors["accent"])],
        )
        # Secondary actions remain calm, but should still look unmistakably clickable.
        # Keep Link.TButton only for true navigation/links such as the header and LinkedIn.
        style.configure(
            "Secondary.TButton",
            padding=(10, 6),
            borderwidth=1,
            relief="solid",
            background=self.colors["bg"],
            foreground=self.colors["text"],
            font=small,
        )
        style.map(
            "Secondary.TButton",
            background=[("active", self.colors["soft"]), ("pressed", self.colors["soft"])],
            foreground=[("active", self.colors["accent"]), ("pressed", self.colors["accent"])],
        )
        style.configure("TRadiobutton", padding=(7, 5), background=self.colors["bg"])
        style.configure("Card.TRadiobutton", padding=(7, 5), background=self.colors["surface"])
        style.configure("TCheckbutton", padding=(4, 6), background=self.colors["bg"])
        style.configure("Surface.TCheckbutton", padding=(4, 6), background=self.colors["surface"])
        style.map("Surface.TCheckbutton", background=[("active", self.colors["surface"])])
        if sv_ttk is not None:
            style.configure("Switch.TCheckbutton", background=self.colors["bg"], padding=(2, 7))
        style.configure("TEntry", fieldbackground=self.colors["field"], foreground=self.colors["text"], padding=8)
        style.configure("TSpinbox", fieldbackground=self.colors["field"], foreground=self.colors["text"], padding=8)
        style.configure("TCombobox", fieldbackground=self.colors["field"], foreground=self.colors["text"], padding=7)
        style.configure("Horizontal.TProgressbar", troughcolor=self.colors["track"], background=self.colors["accent"])
        style.configure(
            "Treeview", background=self.colors["field"], fieldbackground=self.colors["field"],
            foreground=self.colors["text"], rowheight=self._px(30), borderwidth=0, font=self._font("mono", 9),
        )
        style.configure(
            "Treeview.Heading", background=self.colors["bg"], foreground=self.colors["muted"],
            font=small, relief="flat", borderwidth=0, padding=(6, 6),
        )
        style.map("Treeview.Heading", background=[("active", self.colors["soft"])])
        self.root.after_idle(lambda: self._apply_windows_titlebar(self.root))

    def _chip(self, parent: Any, text: str) -> Any:
        """A small status pill, used instead of a second grey line of prose."""
        chip = ttk.Frame(parent, style="Chip.TFrame", padding=(9, 3))
        self._label(chip, text=text, style="Chip.TLabel").pack()
        return chip

    def _hairline(self, parent: Any, pady: Any = 0) -> Any:
        rule = ttk.Frame(parent, style="Rule.TFrame", height=1)
        rule.pack(fill="x", pady=pady)
        return rule

    def _primary_button(self, parent: Any, text: str, command: Any) -> Any:
        """A theme-independent primary button with reliable text contrast."""
        foreground = self.colors["on_accent"]
        button = tk.Button(
            parent,
            text=text,
            command=command,
            background=self.colors["accent"],
            foreground=foreground,
            activebackground=self.colors["accent_hover"],
            activeforeground=foreground,
            disabledforeground=self.colors["muted"],
            borderwidth=0,
            relief="flat",
            font=self._font("semi", 10),
            padx=16,
            pady=11,
            cursor="hand2",
            takefocus=True,
            highlightthickness=2,
            highlightbackground=self.colors["accent"],
            highlightcolor=self.colors["text"],
        )
        button.bind("<Return>", lambda _event: button.invoke())
        button.bind("<space>", lambda _event: button.invoke())
        return button

    def _render_undo_correction(self, parent: Any) -> None:
        if not self.last_time_correction:
            return
        link = self._label(
            parent,
            text=self.t("undo_correction"),
            style="Muted.TLabel",
            cursor="hand2",
            takefocus=True,
        )
        link.pack(anchor="center", pady=(2, 4))
        link.bind("<Button-1>", lambda _event: self._undo_time_correction())
        link.bind("<Return>", lambda _event: self._undo_time_correction())
        link.bind("<space>", lambda _event: self._undo_time_correction())

    def _timer_font_size(self, text: str) -> int:
        """Choose the largest mono size that stays safely inside the dial.

        Font point sizes already follow Windows DPI. The dial geometry now follows
        the same scale, and measuring the real selected font keeps the digits clear
        of the ring across display scaling levels.
        """
        if len(text) <= 5:
            candidate = 34
        elif len(text) <= 7:
            candidate = 28
        else:
            candidate = 24

        ring_diameter = self._px(TIMER_RING_SIZE) - (2 * self._px(TIMER_RING_MARGIN))
        inner_diameter = ring_diameter - self._px(TIMER_RING_WIDTH)
        max_width = max(self._px(80), int(inner_diameter - self._px(28)))
        max_height = max(self._px(48), int(inner_diameter - self._px(30)))
        try:
            import tkinter.font as tkfont

            while candidate > 14:
                probe = tkfont.Font(
                    root=self.root,
                    font=self._font("mono", candidate, bold=True),
                )
                if probe.measure(text) <= max_width and probe.metrics("linespace") <= max_height:
                    break
                candidate -= 1
        except Exception:
            # Conservative fallback for minimal/atypical Tk installations.
            if len(text) <= 5:
                candidate = min(candidate, 28)
            elif len(text) <= 7:
                candidate = min(candidate, 24)
            else:
                candidate = min(candidate, 18)
        return candidate

    @staticmethod
    def _ring_points(
        fraction: float, size: int = TIMER_RING_SIZE, margin: int = TIMER_RING_MARGIN
    ) -> list[float]:
        """Return one clockwise blue path starting at 12 o'clock."""
        fraction = max(0.0, min(1.0, fraction))
        if fraction <= 0.0 or fraction >= 1.0:
            return []
        center = size / 2.0
        radius = (size - (2 * margin)) / 2.0
        steps = max(2, int(180 * fraction))
        points: list[float] = []
        for step in range(steps + 1):
            angle = math.radians(-90.0 + 360.0 * fraction * (step / steps))
            points.extend(
                [
                    center + radius * math.cos(angle),
                    center + radius * math.sin(angle),
                ]
            )
        return points

    def _apply_directionality(self, parent: Any) -> None:
        """Right-align Persian text while keeping timer digits unchanged."""
        rtl = self.lang == "fa"
        text_anchor = "e" if rtl else "w"
        justify = "right" if rtl else "left"

        widgets = [parent]
        index = 0
        while index < len(widgets):
            widget = widgets[index]
            index += 1
            try:
                widgets.extend(widget.winfo_children())
            except tk.TclError:
                pass

            try:
                if isinstance(widget, (ttk.Label, tk.Label)):
                    widget.configure(anchor=text_anchor, justify=justify)
                    if rtl:
                        raw_text = str(widget.cget("text"))
                        display_text = self._rtl_display(raw_text)
                        if display_text != raw_text:
                            widget.configure(text=display_text)
                elif isinstance(widget, (ttk.Entry, ttk.Spinbox, ttk.Combobox)):
                    widget.configure(justify=justify)
                elif isinstance(widget, (ttk.Checkbutton, ttk.Radiobutton, ttk.Button)):
                    widget.configure(anchor=text_anchor)
                    if rtl:
                        raw_text = str(widget.cget("text"))
                        display_text = self._rtl_display(raw_text)
                        if display_text != raw_text:
                            widget.configure(text=display_text)
            except (tk.TclError, TypeError):
                pass

            try:
                manager = widget.winfo_manager()
                if manager == "pack":
                    info = widget.pack_info()
                    if info.get("anchor") in {"w", "e"}:
                        widget.pack_configure(anchor=text_anchor)
                elif manager == "grid":
                    info = widget.grid_info()
                    sticky = str(info.get("sticky", ""))
                    if sticky in {"w", "e"}:
                        widget.grid_configure(sticky=text_anchor)
            except tk.TclError:
                pass

    def _apply_windows_titlebar(self, window: Any) -> None:
        if platform.system() != "Windows":
            return
        try:
            import ctypes

            window.update_idletasks()
            ctypes.windll.user32.GetParent.restype = ctypes.c_void_p
            handle = ctypes.windll.user32.GetParent(window.winfo_id())
            enabled = ctypes.c_int(1 if self.colors.get("is_dark") else 0)
            for attribute in (20, 19):
                result = ctypes.windll.dwmapi.DwmSetWindowAttribute(
                    handle, attribute, ctypes.byref(enabled), ctypes.sizeof(enabled)
                )
                if result == 0:
                    break
        except (AttributeError, OSError, tk.TclError):
            pass

    def _build_shell(self) -> None:
        for child in self.root.winfo_children():
            if isinstance(child, tk.Toplevel):
                continue  # dialogs and the floating timer survive a colour change
            child.destroy()
        outer = ttk.Frame(self.root, padding=(26, 16, 18, 16))
        outer.pack(fill="both", expand=True)
        header = ttk.Frame(outer)
        header.pack(fill="x")
        header_side = "left" if self.lang == "fa" else "right"
        brand_side = "right" if self.lang == "fa" else "left"

        # A quiet wordmark anchors the window; the navigation stays as text.
        brand = ttk.Frame(header)
        brand.pack(side=brand_side)
        mark_size = self._px(16)
        mark = tk.Canvas(
            brand, width=mark_size, height=mark_size, background=self.colors["bg"],
            highlightthickness=0, borderwidth=0,
        )
        mark.create_oval(self._px(1), self._px(1), self._px(15), self._px(15), outline=self.colors["accent"], width=self._px(2))
        mark.create_rectangle(self._px(6), self._px(5), self._px(7), self._px(11), fill=self.colors["accent"], outline="")
        mark.create_rectangle(self._px(9), self._px(5), self._px(10), self._px(11), fill=self.colors["accent"], outline="")
        mark.pack(side="left", pady=(1, 0))
        tk.Label(
            brand,
            text=self.t("app_title"),
            background=self.colors["bg"],
            foreground=self.colors["text"],
            font=self._font("semi", 12),
            borderwidth=0,
            highlightthickness=0,
        ).pack(side="left", padx=(7, 6))
        tk.Label(
            brand,
            text=APP_VERSION,
            background=self.colors["bg"],
            foreground=self.colors["muted"],
            font=self._font("mono", 8),
            borderwidth=0,
            highlightthickness=0,
        ).pack(side="left", pady=(3, 0))

        ttk.Button(header, text=self.t("settings"), style="Link.TButton", command=self._open_settings).pack(
            side=header_side
        )
        ttk.Button(header, text=self.t("stats"), style="Link.TButton", command=self._open_stats).pack(
            side=header_side, padx=(12, 0) if self.lang == "fa" else (0, 12)
        )
        self._hairline(outer, pady=(12, 0))

        body = ttk.Frame(outer)
        body.pack(fill="both", expand=True, pady=(4, 0))
        canvas = tk.Canvas(
            body,
            background=self.colors["bg"],
            highlightthickness=0,
            borderwidth=0,
        )
        scrollbar = ttk.Scrollbar(body, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=scrollbar.set)
        body.columnconfigure(0, weight=1)
        body.rowconfigure(0, weight=1)
        canvas.grid(row=0, column=0, sticky="nsew")
        scrollbar.grid(row=0, column=1, sticky="ns", padx=(8, 0))
        scrollbar.grid_remove()

        self._content_height = None
        self.content = ttk.Frame(canvas, padding=(0, 10, 10, 6))
        self.content_window = canvas.create_window((0, 0), window=self.content, anchor="nw")
        self.content_canvas = canvas
        self.content_scrollbar = scrollbar

        def stretch_content() -> None:
            """Let short screens use the whole window height.

            Without this the content frame is only as tall as its widgets, so
            everything crowds the top edge and leaves a large empty area below.
            Giving it at least the canvas height lets the renderers push the
            day total to the bottom and centre the dial in what is left.
            """
            try:
                target = max(self.content.winfo_reqheight(), canvas.winfo_height())
                if target != getattr(self, "_content_height", None):
                    self._content_height = target
                    canvas.itemconfigure(self.content_window, height=target)
            except tk.TclError:
                pass

        def update_scroll_region(_event: Any | None = None) -> None:
            try:
                stretch_content()
                bounds = canvas.bbox("all")
                canvas.configure(scrollregion=bounds)
                if bounds:
                    content_height = max(0, bounds[3] - bounds[1])
                    needs_scroll = content_height > canvas.winfo_height() + 2
                    if needs_scroll:
                        scrollbar.grid()
                    else:
                        scrollbar.grid_remove()
                        canvas.yview_moveto(0.0)
            except tk.TclError:
                pass

        def fit_content(event: Any) -> None:
            try:
                canvas.itemconfigure(self.content_window, width=max(1, event.width))
                stretch_content()
            except tk.TclError:
                pass

        def on_mousewheel(event: Any) -> None:
            try:
                if platform.system() == "Windows":
                    canvas.yview_scroll(int(-event.delta / 120), "units")
                elif getattr(event, "num", None) == 4:
                    canvas.yview_scroll(-1, "units")
                elif getattr(event, "num", None) == 5:
                    canvas.yview_scroll(1, "units")
                elif getattr(event, "delta", 0):
                    canvas.yview_scroll(-1 if event.delta > 0 else 1, "units")
            except tk.TclError:
                pass

        self.content.bind("<Configure>", update_scroll_region)
        canvas.bind("<Configure>", fit_content)
        canvas.bind("<MouseWheel>", on_mousewheel)
        canvas.bind("<Button-4>", on_mousewheel)
        canvas.bind("<Button-5>", on_mousewheel)

    def _scroll_content_widget_into_view(self, widget: Any, margin: int = 12) -> None:
        """Scroll the main canvas just enough to expose a newly expanded control."""
        canvas = self.content_canvas
        content = self.content
        if canvas is None or content is None:
            return
        try:
            content.update_idletasks()
            bounds = canvas.bbox("all")
            if not bounds:
                return
            canvas.configure(scrollregion=bounds)
            content_height = max(0, bounds[3] - bounds[1])
            viewport_height = max(1, canvas.winfo_height())
            scrollbar = getattr(self, "content_scrollbar", None)
            if scrollbar is not None:
                if content_height > viewport_height + 2:
                    scrollbar.grid()
                else:
                    scrollbar.grid_remove()

            widget_top = widget.winfo_rooty() - content.winfo_rooty()
            widget_bottom = widget_top + widget.winfo_height()
            view_top = canvas.canvasy(0)
            view_bottom = view_top + viewport_height
            pad = self._px(margin)
            desired_top = view_top
            if widget_bottom + pad > view_bottom:
                desired_top = widget_bottom + pad - viewport_height
            elif widget_top - pad < view_top:
                desired_top = max(0.0, widget_top - pad)
            else:
                return

            maximum_top = max(0.0, content_height - viewport_height)
            desired_top = min(max(0.0, desired_top), maximum_top)
            canvas.yview_moveto(desired_top / max(1.0, float(content_height)))
        except (tk.TclError, AttributeError):
            pass

    def _spacer(self) -> None:
        """Absorb leftover height so a screen composes instead of stacking."""
        ttk.Frame(self.content).pack(fill="both", expand=True)

    def _clear_content(self) -> None:
        closer = self._earlier_panel_close
        self._earlier_panel_close = None
        if closer is not None:
            try:
                closer(restore=False)
            except (tk.TclError, TypeError):
                pass
        self.timer_subtext = None
        self.screen_stage = None
        self.screen_actions = None
        self._content_height = None
        self.dynamic_timer = None
        self.dynamic_note = None
        self.dynamic_progress = None
        self.dynamic_break_button = None
        self.timer_canvas = None
        self.timer_arc = None
        self.timer_text = None
        for child in self.content.winfo_children():
            child.destroy()
        if self.content_canvas is not None:
            try:
                self.content_canvas.yview_moveto(0.0)
            except tk.TclError:
                pass

    def _render(self) -> None:
        desired = self._palette_for_state()
        if desired.get("name") != self.colors.get("name") and not self._other_popups_open():
            self._clear_content()
            self._apply_style(desired)
            self._build_shell()
        self._clear_content()
        state = self.engine.state
        if state == TimerState.READY:
            self._render_ready()
        elif state == TimerState.WORK_DUE:
            self._render_work_due()
        elif state in {TimerState.RESTING, TimerState.REST_COMPLETE}:
            self._render_break()
        elif state == TimerState.PAUSED:
            self._render_paused()
        else:
            self._render_working()
        self._apply_directionality(self.content)

    # ------------------------------------------------------------------ 0.18 building blocks
    DIAL_SIZE = 300

    def _parent_bg(self, parent: Any) -> str:
        try:
            if str(parent.cget("style")) == "Surface.TFrame":
                return self.colors["surface"]
        except (tk.TclError, AttributeError):
            pass
        try:
            return str(parent.cget("background"))
        except (tk.TclError, AttributeError):
            return self.colors["bg"]

    def _pill(
        self,
        parent: Any,
        text: str,
        command: Any = None,
        *,
        kind: str = "secondary",
        height: int = 44,
        fill_x: bool = False,
        font: Any = None,
        min_width: int = 0,
        pad_x: int = 20,
    ) -> Any:
        """A rounded, smooth button or chip drawn with Pillow (plain button without it)."""

        def palette(which: str) -> tuple[str, str, str | None, str]:
            c = self.colors
            return {
                "primary": (c["accent"], c["accent_hover"], None, c["on_accent"]),
                "secondary": (c["face"], c["soft"], c["border"], c["text"]),
                "chip": (c["chip"], c["soft"], None, c["text"]),
                "chip_on": (c["soft"], c["soft"], c["accent"], c["accent"]),
                "round": (c["chip"], c["soft"], None, c["text"]),
                "quiet": (c["chip"], c["soft"], None, c["text"]),
            }.get(which, (c["face"], c["soft"], c["border"], c["text"]))

        if font is None:
            font = self._font("semi", 10) if kind == "primary" else self._font("ui", 10)
        pixel_height = self._px(height)
        state: dict[str, Any] = {"width": 0, "hover": False, "kind": kind}
        label = tk.Label(
            parent,
            text=text,
            compound="center",
            background=self._parent_bg(parent),
            foreground=palette(kind)[3],
            font=font,
            borderwidth=0,
            highlightthickness=0,
            cursor="hand2",
            takefocus=1,
        )

        def natural_width() -> int:
            if state["kind"] == "round":
                return pixel_height
            try:
                measured = int(self.root.tk.call("font", "measure", font, str(label.cget("text"))))
            except tk.TclError:
                measured = 80
            return max(self._px(min_width), measured + 2 * self._px(pad_x))

        def draw(width: int | None = None) -> None:
            try:
                if not label.winfo_exists():
                    return
                fill, hover, outline, foreground = palette(state["kind"])
                target = int(width or (state["width"] if fill_x and state["width"] else natural_width()))
                data = pill_image_data(target, pixel_height, hover if state["hover"] else fill, outline)
                if data is None:
                    label.configure(
                        background=hover if state["hover"] else fill, foreground=foreground,
                        padx=self._px(pad_x), pady=self._px(8),
                    )
                    return
                image = tk.PhotoImage(master=self.root, data=data)
                # A stretched pill requests only its natural width.  Requesting
                # the drawn width would feed back into the layout and loop.
                requested = min(target, natural_width()) if fill_x else target
                label.configure(image=image, width=requested, height=pixel_height, foreground=foreground)
                label._pill_image = image  # keep a reference; Tk does not
                state["width"] = target
            except tk.TclError:
                pass

        def on_configure(event: Any) -> None:
            if fill_x and abs(int(event.width) - int(state["width"])) > 1:
                draw(int(event.width))

        def run(_event: Any = None) -> str:
            if command is not None:
                command()
            return "break"

        def release(event: Any) -> None:
            try:
                inside = 0 <= event.x < label.winfo_width() and 0 <= event.y < label.winfo_height()
            except tk.TclError:
                return
            if inside:
                run()

        def set_kind(new_kind: str) -> None:
            if new_kind != state["kind"]:
                state["kind"] = new_kind
                draw()

        def set_text(new_text: str) -> None:
            label.configure(text=new_text)
            if not fill_x:
                draw()

        label.bind("<Enter>", lambda _e: (state.update(hover=True), draw()))
        label.bind("<Leave>", lambda _e: (state.update(hover=False), draw()))
        label.bind("<ButtonRelease-1>", release)
        label.bind("<Return>", run)
        label.bind("<space>", run)
        if fill_x:
            label.bind("<Configure>", on_configure)
        label.pill_set_kind = set_kind
        label.pill_set_text = set_text
        draw()
        return label

    def _link(self, parent: Any, text: str, command: Any, *, muted: bool = False) -> Any:
        colour = self.colors["muted"] if muted else self.colors["accent"]
        normal = self._font("ui", 9)
        underlined = (*normal, "underline")
        link = tk.Label(
            parent, text=text, foreground=colour, background=self._parent_bg(parent),
            font=normal, cursor="hand2", borderwidth=0, highlightthickness=0, takefocus=1,
        )
        link.bind("<Enter>", lambda _e: link.configure(font=underlined))
        link.bind("<Leave>", lambda _e: link.configure(font=normal))
        link.bind("<ButtonRelease-1>", lambda _e: command())
        link.bind("<Return>", lambda _e: command())
        return link

    def _link_row(self, parent: Any, items: list[tuple[str, Any]], pady: Any = (10, 0)) -> Any:
        """Less important actions as small, quiet buttons in centred rows.

        They stay clearly clickable but do not compete with the main button.
        Rows wrap when the labels are long (German).
        """
        holder = tk.Frame(parent, background=self._parent_bg(parent))
        holder.pack(anchor="center", pady=pady)
        font = self._font("ui", 9)
        pad = self._px(14)
        gap = self._px(8)
        try:
            available = max(self._px(300), self.root.winfo_width() - self._px(70))
        except tk.TclError:
            available = self._px(460)
        rows: list[list[tuple[str, Any]]] = [[]]
        used = 0
        for text, command in items:
            try:
                width = int(self.root.tk.call("font", "measure", font, text)) + 2 * pad
            except tk.TclError:
                width = 8 * len(text) + 2 * pad
            if rows[-1] and used + gap + width > available:
                rows.append([])
                used = 0
            used += (gap if rows[-1] else 0) + width
            rows[-1].append((text, command))
        for row_items in rows:
            row = tk.Frame(holder, background=self._parent_bg(parent))
            row.pack(anchor="center", pady=(0, self._px(6)))
            ordered = list(reversed(row_items)) if self.lang == "fa" else row_items
            for index, (text, command) in enumerate(ordered):
                self._pill(row, text, command, kind="quiet", height=32, pad_x=14, font=font).pack(
                    side="left", padx=(gap if index else 0, 0)
                )
        return holder

    def _screen_title(self, title: str, subtitle: str | None = None, *, centred: bool = True) -> None:
        anchor = "center" if centred else "w"
        self._label(self.content, text=title, style="Title.TLabel").pack(anchor=anchor)
        if subtitle:
            self._label(
                self.content, text=subtitle, style="Muted.TLabel",
                wraplength=self._px(440), justify="center" if centred else "left",
            ).pack(anchor=anchor, pady=(4, 0))

    def _screen_frames(self) -> tuple[Any, Any]:
        """Footer at the bottom, then a stage (dial) and an action area.

        The Started-earlier panel temporarily takes the place of both.
        """
        self._today_footer()
        stage = ttk.Frame(self.content)
        stage.pack(fill="both", expand=True)
        actions = ttk.Frame(self.content)
        actions.pack(fill="x")
        self.screen_stage = stage
        self.screen_actions = actions
        return stage, actions

    def _today_footer(self) -> None:
        entry = self.history.day()
        text = self.t(
            "footer_today",
            work=self._format_total_ui(entry.get("work_seconds", 0.0)),
            rest=self._format_total_ui(entry.get("break_seconds", 0.0)),
        )
        footer = tk.Frame(self.content, background=self.colors["bg"])
        footer.pack(side="bottom", fill="x", pady=(10, 0))
        tk.Frame(footer, background=self.colors["rule"], height=1).pack(fill="x")
        self._label(footer, text=text, style="Mono.TLabel").pack(anchor="center", pady=(8, 0))

    # ------------------------------------------------------------------ dial
    def _dial_colours(self) -> dict[str, Any]:
        c = self.colors
        engine = self.engine
        state = engine.state
        paused = state == TimerState.PAUSED
        base = engine.paused_from if paused and engine.paused_from else state
        overtime = base in {TimerState.WORK_DUE, TimerState.REST_COMPLETE}
        if paused:
            ring = c["muted"]
        elif overtime:
            ring = c["warm"]
        elif base == TimerState.RESTING:
            ring = c["timeline_break"]
        else:
            ring = c["accent"]
        return {
            "ring": ring,
            "wedge": blend_colour(ring, c["face"], 0.2 if c.get("is_dark") else 0.14),
            "overtime": overtime and not paused,
            "text": c["warm"] if overtime and not paused else (c["muted"] if paused else c["text"]),
        }

    def _dial_font_size(self, text: str, size: int) -> int:
        limit = dial_geometry(size)["wedge_r"] * 1.55
        candidate = max(12, int(size / 8.6))
        try:
            while candidate > 12:
                font = self._font("mono", candidate, bold=True)
                if int(self.root.tk.call("font", "measure", font, text)) <= limit:
                    break
                candidate -= 1
        except tk.TclError:
            pass
        return candidate

    def _dial_sub_text(self) -> str:
        engine = self.engine
        state = engine.state
        if state == TimerState.WORKING:
            back = datetime.now() + timedelta(seconds=max(0.0, engine.remaining_seconds))
            return self.t("dial_work_sub", minutes=int(engine.planned_work_minutes), time=back.strftime("%H:%M"))
        if state == TimerState.RESTING:
            back = datetime.now() + timedelta(seconds=max(0.0, engine.remaining_seconds))
            return self.t("dial_break_sub", minutes=int(engine.planned_break_minutes), time=back.strftime("%H:%M"))
        if state in {TimerState.WORK_DUE, TimerState.REST_COMPLETE}:
            return self.t("dial_over")
        if state == TimerState.PAUSED:
            return self.t("dial_paused")
        return ""

    def _dial_time_text(self) -> tuple[str, float]:
        engine = self.engine
        state = engine.state
        base = engine.paused_from if state == TimerState.PAUSED and engine.paused_from else state
        if base in {TimerState.WORK_DUE, TimerState.REST_COMPLETE}:
            return "+" + format_duration(engine.overtime_seconds), 0.0
        return (
            format_duration(engine.remaining_seconds),
            engine.remaining_seconds / max(1.0, engine.block_seconds),
        )

    def _create_timer_ring(self, parent: Any, text: str | None = None, remaining_fraction: float | None = None, size: int | None = None) -> None:
        """The smooth countdown dial with the time and one short line inside it."""
        if text is None or remaining_fraction is None:
            text, remaining_fraction = self._dial_time_text()
        pixel_size = self._px(size or self.DIAL_SIZE)
        canvas = tk.Canvas(
            parent, width=pixel_size, height=pixel_size, background=self.colors["bg"],
            highlightthickness=0, borderwidth=0,
        )
        canvas.pack(anchor="center", pady=(self._px(4), self._px(4)))
        self.timer_canvas = canvas
        self.timer_size = pixel_size
        self._dial_cache_key = None
        self.timer_arc = canvas.create_image(pixel_size / 2, pixel_size / 2)
        colours = self._dial_colours()
        self.timer_text = canvas.create_text(
            pixel_size / 2, pixel_size / 2 - pixel_size * 0.035, text=text, fill=colours["text"],
            font=self._font("mono", self._dial_font_size(text, pixel_size), bold=True),
        )
        self.timer_subtext = canvas.create_text(
            pixel_size / 2, pixel_size / 2 + pixel_size * 0.11, text=self._rtl_display(self._dial_sub_text()),
            fill=self.colors["muted"], font=self._font("ui", 8),
        )
        if PILImage is None:
            self._draw_legacy_dial(canvas, pixel_size)
        self._draw_timer_progress(remaining_fraction)

    def _draw_legacy_dial(self, canvas: Any, size: int) -> None:
        """Plain Tk dial used only when Pillow is missing."""
        g = dial_geometry(size)
        centre = size / 2.0
        canvas.create_oval(
            centre - g["face_r"], centre - g["face_r"], centre + g["face_r"], centre + g["face_r"],
            fill=self.colors["face"], outline=self.colors["border"], tags=("dial_static",),
        )
        r = g["ring_r"]
        canvas.create_oval(
            centre - r, centre - r, centre + r, centre + r, outline=self.colors["track"],
            width=g["ring_w"], tags=("dial_static",),
        )
        canvas.tag_lower("dial_static")

    def _draw_timer_progress(self, fraction: float) -> None:
        canvas = self.timer_canvas
        if not canvas:
            return
        size = int(getattr(self, "timer_size", self._px(self.DIAL_SIZE)))
        colours = self._dial_colours()
        fraction = max(0.0, min(1.0, float(fraction)))
        key = (round(fraction * 1500), colours["ring"], self.colors.get("name"), size)
        if key == getattr(self, "_dial_cache_key", None):
            return
        self._dial_cache_key = key
        try:
            canvas.itemconfigure(self.timer_text, fill=colours["text"])
            if PILImage is None:
                canvas.delete("dial_progress")
                points = self._ring_points(fraction, size, int((size - 2 * dial_geometry(size)["ring_r"]) / 2))
                if points:
                    canvas.create_line(
                        *points, fill=colours["ring"], width=dial_geometry(size)["ring_w"],
                        capstyle="round", tags=("dial_progress",),
                    )
                return
            data = dial_image_data(
                size,
                fraction=fraction,
                ring=colours["ring"],
                wedge=colours["wedge"],
                face=self.colors["face"],
                border=self.colors["border"],
                track=self.colors["track"],
                tick=self.colors["tick"],
                tick_major=blend_colour(self.colors["muted"], self.colors["face"], 0.7),
                overtime=colours["overtime"],
            )
            image = tk.PhotoImage(master=self.root, data=data)
            canvas.itemconfigure(self.timer_arc, image=image)
            canvas._dial_image = image
        except tk.TclError:
            pass

    def _update_timer_ring(self, text: str | None = None, remaining_fraction: float | None = None) -> None:
        if not self.timer_canvas or self.timer_text is None:
            return
        if text is None or remaining_fraction is None:
            text, remaining_fraction = self._dial_time_text()
        try:
            size = int(getattr(self, "timer_size", self._px(self.DIAL_SIZE)))
            self.timer_canvas.itemconfigure(
                self.timer_text, text=text, font=self._font("mono", self._dial_font_size(text, size), bold=True),
            )
            if self.timer_subtext is not None:
                self.timer_canvas.itemconfigure(self.timer_subtext, text=self._rtl_display(self._dial_sub_text()))
            self._draw_timer_progress(remaining_fraction)
        except tk.TclError:
            pass

    # ------------------------------------------------------------------ Started earlier panel
    def _earlier_action(
        self,
        link_key: str,
        hint_key: str,
        on_confirm: Any,
        max_minutes: Any,
        context: tuple[str, Any] | None = None,
    ) -> tuple[str, Any] | None:
        """A link that opens the Started-earlier panel, or None when nothing can be corrected."""
        try:
            limit = int(max_minutes() if callable(max_minutes) else max_minutes)
        except Exception:
            LOGGER.exception("Could not compute the Started earlier limit")
            return None
        if limit < 1:
            return None
        return (
            self.t(link_key),
            lambda: self._open_earlier_panel(hint_key, on_confirm, max_minutes, context),
        )

    def _open_earlier_panel(
        self, hint_key: str, on_confirm: Any, max_minutes: Any, context: tuple[str, Any] | None = None,
    ) -> None:
        stage, actions = self.screen_stage, self.screen_actions
        if stage is None or actions is None:
            return

        def current_limit() -> int:
            try:
                return max(0, int(max_minutes() if callable(max_minutes) else max_minutes))
            except Exception:
                LOGGER.exception("Could not compute the Started earlier limit")
                return 0

        limit = current_limit()
        if limit < 1:
            return
        if self._earlier_panel_close is not None:
            self._earlier_panel_close(restore=True)
        # Remember where stage and actions sit, so Cancel puts them back in place.
        slaves = list(self.content.pack_slaves())
        following = None
        if actions in slaves and slaves.index(actions) + 1 < len(slaves):
            following = slaves[slaves.index(actions) + 1]
        stage_info = dict(stage.pack_info())
        actions_info = dict(actions.pack_info())
        stage.pack_forget()
        actions.pack_forget()
        bg = self.colors["bg"]
        panel = tk.Frame(self.content, background=bg)
        panel_options: dict[str, Any] = {"fill": "both", "expand": True, "pady": (self._px(12), 0)}
        if following is not None:
            panel_options["before"] = following
        panel.pack(**panel_options)
        rtl = self.lang == "fa"
        start_side, end_side = ("right", "left") if rtl else ("left", "right")

        context_minutes = None
        context_label = ""
        if context is not None:
            try:
                raw = context[1]() if callable(context[1]) else context[1]
                if raw is not None and 1 <= int(raw) <= limit:
                    context_minutes = int(raw)
                    context_label = self.t(context[0])
            except Exception:
                context_minutes = None
        value = {"minutes": context_minutes or (10 if limit >= 10 else limit)}
        timeline_range = limit if limit <= 240 else 180

        def clock(minutes: int) -> str:
            return (datetime.now() - timedelta(minutes=minutes)).strftime("%H:%M")

        def readout(minutes: int) -> str:
            hours, rest = divmod(int(minutes), 60)
            if hours:
                return self.t("earlier_readout_h", hours=hours, minutes=rest)
            return self.t("earlier_readout", minutes=minutes)

        # Title row
        top = tk.Frame(panel, background=bg)
        top.pack(fill="x")
        question = self._label(top, text=self.t(f"earlier_q_{hint_key}"), style="Section.TLabel")
        question.configure(font=self._font("semi", 13))
        question.pack(side=start_side)
        close_link = self._link(top, "✕", lambda: close(restore=True), muted=True)
        close_link.configure(font=self._font("ui", 12))
        close_link.pack(side=end_side)

        # Big readout with − and +
        dial_row = tk.Frame(panel, background=bg)
        dial_row.pack(fill="x", pady=(self._px(18), 0))
        minus = self._pill(dial_row, "−", lambda: change(-1), kind="round", height=44, font=self._font("ui", 16))
        plus = self._pill(dial_row, "+", lambda: change(+1), kind="round", height=44, font=self._font("ui", 16))
        (plus if rtl else minus).pack(side="left", padx=(self._px(24), 0))
        (minus if rtl else plus).pack(side="right", padx=(0, self._px(24)))
        big = tk.Label(dial_row, text="", background=bg, foreground=self.colors["text"], font=self._font("semi", 24), borderwidth=0)
        big.pack(side="left", fill="x", expand=True)
        sub = self._label(panel, text="", style="Muted.TLabel")
        sub.pack(anchor="center", pady=(self._px(2), 0))

        # Quick choices
        chips_row = tk.Frame(panel, background=bg)
        chips_row.pack(anchor="center", pady=(self._px(16), 0))
        chip_values = [minutes for minutes in (5, 10, 15, 30, 60) if minutes <= limit][:5]
        chips: list[tuple[Any, int]] = []
        entries = [(f"{minutes}", minutes) for minutes in chip_values]
        if context_minutes is not None:
            entries.append((context_label, context_minutes))
        if rtl:
            entries.reverse()
        for text, minutes in entries:
            chip = self._pill(
                chips_row, text, lambda chosen=minutes: set_value(chosen), kind="chip", height=32,
                min_width=44, pad_x=14, font=self._font("ui", 9),
            )
            chip.pack(side="left", padx=self._px(3))
            chips.append((chip, minutes))
        self._label(panel, text=self.t("earlier_hint"), style="Muted.TLabel").pack(anchor="center", pady=(self._px(6), 0))

        # Timeline: drag back from "now"
        line = tk.Label(panel, background=bg, borderwidth=0, cursor="sb_h_double_arrow")
        line.pack(fill="x", padx=self._px(18), pady=(self._px(14), 0))
        scale_row = tk.Frame(panel, background=bg)
        scale_row.pack(fill="x", padx=self._px(18))
        left_label = tk.Label(scale_row, background=bg, foreground=self.colors["muted"], font=self._font("mono", 8))
        mid_label = tk.Label(scale_row, background=bg, foreground=self.colors["muted"], font=self._font("mono", 8))
        right_label = tk.Label(scale_row, background=bg, foreground=self.colors["muted"], font=self._font("mono", 8))
        left_label.pack(side="left")
        right_label.pack(side="right")
        mid_label.pack(side="left", expand=True)
        line_state = {"width": 0}
        line_height = self._px(26)

        def draw_line() -> None:
            width = line_state["width"] or self._px(420)
            fraction = 1.0 - min(value["minutes"], timeline_range) / float(timeline_range)
            data = track_image_data(
                width, line_height, fraction, track=self.colors["track"],
                fill=blend_colour(self.colors["accent"], bg, 0.35), handle=self.colors["accent"], face=self.colors["face"],
            )
            if data is None:
                line.configure(text="", height=1)
                return
            try:
                image = tk.PhotoImage(master=self.root, data=data)
                line.configure(image=image, width=width, height=line_height)
                line._track_image = image
            except tk.TclError:
                pass

        def line_resized(event: Any) -> None:
            if abs(int(event.width) - line_state["width"]) > 1:
                line_state["width"] = int(event.width)
                draw_line()

        def line_pick(event: Any) -> None:
            width = max(1, line_state["width"] or line.winfo_width())
            fraction = max(0.0, min(1.0, event.x / float(width)))
            set_value(int(round((1.0 - fraction) * timeline_range)))

        line.bind("<Configure>", line_resized)
        line.bind("<Button-1>", line_pick)
        line.bind("<B1-Motion>", line_pick)

        error = self._label(panel, text="", style="Error.TLabel")
        error.pack(anchor="center", pady=(self._px(6), 0))

        buttons = tk.Frame(panel, background=bg)
        buttons.pack(fill="x", pady=(self._px(10), 0))
        cancel = self._pill(buttons, self.t("cancel"), lambda: close(restore=True), kind="secondary", height=48, min_width=110)
        cancel.pack(side=end_side)
        go = self._pill(buttons, "", lambda: confirm(), kind="primary", height=48, fill_x=True)
        go.pack(side=start_side, fill="x", expand=True, padx=(self._px(10), 0) if rtl else (0, self._px(10)))

        def refresh() -> None:
            minutes = value["minutes"]
            try:
                big.configure(text=self._rtl_display(readout(minutes)))
                sub.configure(text=self._rtl_display(self.t("earlier_sub", time=clock(minutes))))
                go.configure(text=self._rtl_display(self.t(f"earlier_go_{hint_key}", time=clock(minutes))))
                for chip, chip_minutes in chips:
                    chip.pill_set_kind("chip_on" if chip_minutes == minutes else "chip")
                left_label.configure(text=clock(timeline_range))
                mid_label.configure(text=clock(timeline_range // 2))
                right_label.configure(text=self._rtl_display(self.t("earlier_now", time=clock(0))))
                error.configure(text="")
            except tk.TclError:
                return
            draw_line()

        def set_value(minutes: int) -> None:
            value["minutes"] = max(1, min(int(minutes), current_limit() or limit))
            refresh()

        def change(step: int) -> None:
            set_value(value["minutes"] + step)

        def wheel(event: Any) -> str:
            number = getattr(event, "num", None)
            delta = getattr(event, "delta", 0)
            if number == 4 or delta > 0:
                change(+1)
            elif number == 5 or delta < 0:
                change(-1)
            return "break"

        def confirm() -> None:
            minutes = value["minutes"]
            live_limit = current_limit()
            if not 1 <= minutes <= max(1, live_limit):
                error.configure(text=self._rtl_display(self.t("started_earlier_invalid", minutes=live_limit)))
                return
            result = on_confirm(minutes)
            if isinstance(result, str) and result:
                try:
                    error.configure(text=self._rtl_display(result))
                except tk.TclError:
                    pass

        bindings = {
            "<Return>": lambda _e: (confirm(), "break")[1],
            "<KP_Enter>": lambda _e: (confirm(), "break")[1],
            "<Escape>": lambda _e: (close(restore=True), "break")[1],
            "<Up>": lambda _e: (change(+1), "break")[1],
            "<Down>": lambda _e: (change(-1), "break")[1],
            "<Prior>": lambda _e: (change(+5), "break")[1],
            "<Next>": lambda _e: (change(-5), "break")[1],
        }
        for sequence, handler in bindings.items():
            self.root.bind(sequence, handler)
        for widget in (panel, big, sub, dial_row, line):
            for sequence in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
                widget.bind(sequence, wheel)

        def close(restore: bool = True) -> None:
            for sequence in bindings:
                try:
                    self.root.unbind(sequence)
                except tk.TclError:
                    pass
            if self._earlier_panel_close is close:
                self._earlier_panel_close = None
            try:
                panel.destroy()
            except tk.TclError:
                pass
            if restore:
                try:
                    for widget, info in ((stage, stage_info), (actions, actions_info)):
                        options = dict(info)
                        if following is not None and following.winfo_exists():
                            options["before"] = following
                        widget.pack_configure(options)
                except tk.TclError:
                    pass

        self._earlier_panel_close = close
        refresh()
        self._apply_directionality(panel)
        try:
            panel.focus_set()
        except tk.TclError:
            pass

    # ------------------------------------------------------------------ screens
    def _render_ready(self) -> None:
        self._label(self.content, text=self.t("ready_title"), style="Title.TLabel").pack(anchor="w")
        stage, actions = self._screen_frames()
        # A form reads top-down: keep Start right under it, leave the rest empty.
        stage.pack_configure(fill="x", expand=False)
        ttk.Frame(self.content).pack(fill="both", expand=True)

        if self.pending_snapshot:
            card = ttk.Frame(stage, style="Surface.TFrame", padding=16)
            card.pack(fill="x", pady=(10, 4))
            self._label(card, text=self.t("previous_title"), style="CardTitle.TLabel").pack(anchor="w")
            self._label(card, text=self.t("previous_body"), style="CardMuted.TLabel", wraplength=self._px(400)).pack(anchor="w", pady=(4, 10))
            buttons = tk.Frame(card, background=self.colors["surface"])
            buttons.pack(fill="x")
            self._pill(buttons, self.t("resume_previous"), self._resume_snapshot, kind="primary", height=38).pack(side="left")
            self._pill(buttons, self.t("discard"), self._discard_snapshot, kind="secondary", height=38).pack(side="left", padx=(8, 0))

        # Task first: what you work on is the intention of the session.
        self._label(stage, text=self.t("task_prompt"), style="Section.TLabel").pack(anchor="w", pady=(16, 6))
        task_entry = ttk.Entry(stage, textvariable=self.task_var, font=self._font("ui", 11))
        task_entry.pack(fill="x")
        suggestion_box = tk.Listbox(
            stage, height=1, exportselection=False, activestyle="none", relief="solid", borderwidth=1,
            highlightthickness=0, background=self.colors["field"], foreground=self.colors["text"],
            selectbackground=self.colors["accent"], selectforeground="#FFFFFF",
        )
        recent_row = tk.Frame(stage, background=self.colors["bg"])
        recent_row.pack(fill="x", pady=(8, 0))
        recent = [name for name in self.task_history.suggestions("") if name][:3]
        if recent:
            side = "right" if self.lang == "fa" else "left"
            for name in recent:
                shown = name if len(name) <= 26 else name[:25].rstrip() + "…"
                self._pill(
                    recent_row, self._rtl_display(shown), lambda chosen=name: self.task_var.set(chosen),
                    kind="chip", height=30, pad_x=12, font=self._font("ui", 9),
                ).pack(side=side, padx=(0, 6) if side == "left" else (6, 0))
        else:
            self._label(recent_row, text=self.t("task_prompt_help"), style="Muted.TLabel", wraplength=self._px(440)).pack(anchor="w")

        def widgets_alive() -> bool:
            try:
                return bool(task_entry.winfo_exists() and suggestion_box.winfo_exists())
            except tk.TclError:
                return False

        def hide_task_suggestions() -> None:
            if widgets_alive():
                try:
                    suggestion_box.pack_forget()
                except tk.TclError:
                    pass

        def refresh_task_suggestions(_event: Any | None = None) -> None:
            if not widgets_alive():
                return
            if _event is not None and getattr(_event, "keysym", "") in {
                "Up", "Down", "Return", "Escape", "Tab", "Shift_L", "Shift_R",
                "Control_L", "Control_R", "Alt_L", "Alt_R",
            }:
                return
            try:
                typed = self.task_var.get().strip()
                matches = self.task_history.suggestions(typed) if typed else []
                matches = [name for name in matches if name.casefold() != typed.casefold()]
                suggestion_box.delete(0, "end")
                for name in matches:
                    suggestion_box.insert("end", name)
                if matches:
                    suggestion_box.configure(height=min(len(matches), TASK_SUGGESTION_LIMIT))
                    if not suggestion_box.winfo_manager():
                        suggestion_box.pack(fill="x", pady=(2, 0), before=recent_row)
                else:
                    hide_task_suggestions()
            except tk.TclError:
                return

        def accept_task_suggestion(index: int | None = None) -> str:
            if not widgets_alive() or suggestion_box.size() <= 0:
                return "break"
            if index is None:
                selected = suggestion_box.curselection()
                index = int(selected[0]) if selected else 0
            try:
                self.task_var.set(str(suggestion_box.get(index)))
                task_entry.icursor("end")
            except (tk.TclError, IndexError):
                return "break"
            hide_task_suggestions()
            try:
                task_entry.focus_set()
            except tk.TclError:
                pass
            return "break"

        def task_entry_down(_event: Any) -> str | None:
            refresh_task_suggestions()
            if widgets_alive() and suggestion_box.size() > 0 and suggestion_box.winfo_ismapped():
                suggestion_box.focus_set()
                suggestion_box.selection_clear(0, "end")
                suggestion_box.selection_set(0)
                suggestion_box.activate(0)
                return "break"
            return None

        def task_entry_return(_event: Any) -> str | None:
            if widgets_alive() and suggestion_box.size() > 0 and suggestion_box.winfo_ismapped():
                return accept_task_suggestion(0)
            self._start_session()
            return "break"

        def task_list_key(_event: Any) -> str | None:
            key = getattr(_event, "keysym", "")
            if key == "Return":
                return accept_task_suggestion()
            if key == "Escape" or (key == "Up" and suggestion_box.curselection() == (0,)):
                hide_task_suggestions()
                if widgets_alive():
                    task_entry.focus_set()
                return "break"
            return None

        def task_list_click(event: Any) -> str:
            if not widgets_alive():
                return "break"
            return accept_task_suggestion(int(suggestion_box.nearest(event.y)))

        def delayed_hide() -> None:
            if not widgets_alive():
                return
            try:
                # Read the raw Tcl focus path: focus_get() can raise KeyError for
                # a Combobox popdown, which Tkinter does not know by name.
                if str(self.root.tk.call("focus")) != str(suggestion_box):
                    hide_task_suggestions()
            except (tk.TclError, KeyError):
                pass

        task_entry.bind("<KeyRelease>", refresh_task_suggestions)
        task_entry.bind("<Down>", task_entry_down)
        task_entry.bind("<Return>", task_entry_return)
        task_entry.bind("<Escape>", lambda _event: (hide_task_suggestions(), "break")[1])
        task_entry.bind("<FocusOut>", lambda _event: self.root.after(120, delayed_hide))
        task_entry.bind("<<Paste>>", lambda _event: self.root.after_idle(refresh_task_suggestions))
        task_entry.bind("<<Cut>>", lambda _event: self.root.after_idle(refresh_task_suggestions))
        suggestion_box.bind("<KeyPress>", task_list_key)
        suggestion_box.bind("<ButtonRelease-1>", task_list_click)

        # Rhythm as visible choices instead of a drop-down.
        self._label(stage, text=self.t("rhythm"), style="Section.TLabel").pack(anchor="w", pady=(18, 6))
        rhythm_row = tk.Frame(stage, background=self.colors["bg"])
        rhythm_row.pack(fill="x")
        side = "right" if self.lang == "fa" else "left"
        for key in ("classic", "balanced", "long", "52_17", "custom"):
            work, rest = resolve_timing(key, self.effort_var.get(), self.settings_data)
            label = f"{work} / {rest}" if key != "custom" else self.t("rhythm_custom_chip", work=work, rest=rest)
            self._pill(
                rhythm_row, self._rtl_display(label), lambda chosen=key: self._choose_rhythm(chosen),
                kind="chip_on" if key == self.rhythm_key else "chip", height=34, pad_x=13, font=self._font("ui", 9),
            ).pack(side=side, padx=(0, 6) if side == "left" else (6, 0))
        self.dynamic_note = self._label(stage, text=self._preset_summary(), style="Muted.TLabel", wraplength=self._px(440))
        self.dynamic_note.pack(anchor="w", pady=(8, 0))

        start = self._pill(actions, self.t("start_focus"), self._start_session, kind="primary", height=52, fill_x=True,
                           font=self._font("semi", 11))
        start.pack(fill="x", pady=(16, 0))

        def start_earlier(minutes: int) -> None:
            # READY has no earlier tracked state to reclassify: start a fresh block
            # with explicit already-worked time.
            self.already_var.set(str(minutes))
            self._start_session()

        link = self._earlier_action("link_already_started", "started_earlier_work", start_earlier, 600)
        if link:
            self._link_row(actions, [link], pady=(12, 0))

        tip = ttk.Frame(actions, style="Surface.TFrame", padding=(14, 10))
        tip.pack(fill="x", pady=(16, 0))
        self._label(tip, text=self._time_tip(), style="CardMuted.TLabel", wraplength=self._px(430)).pack(anchor="w")

    def _choose_rhythm(self, key: str) -> None:
        self.rhythm_key = key
        self.settings_data["last_rhythm"] = key
        self.settings_store.save()
        self._render()

    def _render_working(self) -> None:
        task_text = self.task.strip()
        self._screen_title(self.t("focus_title"), task_text or None)
        stage, actions = self._screen_frames()
        ttk.Frame(stage).pack(fill="both", expand=True)
        self._create_timer_ring(stage)
        self._render_humor_line(stage, self._work_humor_context(), anchor="center", pady=(2, 0))
        self._render_undo_correction(stage)
        ttk.Frame(stage).pack(fill="both", expand=True)

        row = tk.Frame(actions, background=self.colors["bg"])
        row.pack(fill="x", pady=(8, 0))
        pause = self._pill(row, self.t("pause_short"), self._toggle_pause, kind="secondary", height=48, fill_x=True)
        take_break = self._pill(row, self.t("take_break"), self._take_break, kind="secondary", height=48, fill_x=True)
        first, second = (take_break, pause) if self.lang == "fa" else (pause, take_break)
        first.pack(side="left", fill="x", expand=True, padx=(0, 6))
        second.pack(side="left", fill="x", expand=True, padx=(6, 0))
        links = [
            self._earlier_action(
                "link_break_earlier", "started_earlier_break",
                lambda minutes: self._apply_time_correction("break", minutes),
                lambda: self._earlier_limit_minutes("break"),
            ),
            (self.t("finish"), self._finish_session),
        ]
        self._link_row(actions, [item for item in links if item])

    def _render_work_due(self) -> None:
        self._screen_title(self.t("due_title"), self.t("due_body", minutes=max(1, int(self.engine.planned_work_minutes))))
        stage, actions = self._screen_frames()
        ttk.Frame(stage).pack(fill="both", expand=True)
        self._create_timer_ring(stage)
        due_context = "break_due_overrun" if self.engine.overtime_seconds >= 10 * 60 else "break_due"
        self._render_humor_line(
            stage, due_context, anchor="center", pady=(2, 0),
            minutes=max(1, int(self.engine.planned_work_minutes)),
            rest=max(1, int(self._suggested_break_minutes())),
            elapsed_minutes=max(0.0, self.engine.work_block_elapsed / 60.0),
        )
        self._render_undo_correction(stage)
        ttk.Frame(stage).pack(fill="both", expand=True)

        start = self._pill(
            actions, self.t("start_break", minutes=self._suggested_break_minutes()),
            lambda: self._begin_break(self._suggested_break_minutes()), kind="primary", height=52, fill_x=True,
            font=self._font("semi", 11),
        )
        start.pack(fill="x", pady=(8, 0))
        self.dynamic_break_button = start
        self._pill(actions, self.t("snooze"), self._snooze, kind="secondary", height=44, fill_x=True).pack(fill="x", pady=(8, 0))
        links = [
            self._earlier_action(
                "link_break_earlier", "started_earlier_break",
                lambda minutes: self._apply_time_correction("break", minutes),
                lambda: self._earlier_limit_minutes("break"),
                context=("chip_work_ended", lambda: int(round(self.engine.overtime_seconds / 60.0))),
            ),
            (self.t("finish"), self._finish_session),
        ]
        self._link_row(actions, [item for item in links if item])

    def _render_paused(self) -> None:
        self._screen_title(self.t("paused"), self.t("paused_body"))
        stage, actions = self._screen_frames()
        ttk.Frame(stage).pack(fill="both", expand=True)
        self._create_timer_ring(stage)
        if self.humor_hint == "after_sleep_gap":
            self._render_humor_line(stage, "after_sleep_gap", anchor="center", pady=(2, 0))
        self._render_undo_correction(stage)
        ttk.Frame(stage).pack(fill="both", expand=True)

        kind = self._paused_context_kind()
        links: list[Any] = []
        if kind == "work":
            self._pill(actions, self.t("resume_work"), self._toggle_pause, kind="primary", height=52, fill_x=True,
                       font=self._font("semi", 11)).pack(fill="x", pady=(8, 0))
            self._pill(actions, self.t("take_break"), self._take_break, kind="secondary", height=44, fill_x=True).pack(fill="x", pady=(8, 0))
            links = [
                self._earlier_action(
                    "link_resumed_earlier", "started_earlier_paused_work",
                    lambda minutes: self._apply_time_correction("work", minutes),
                    lambda: self._earlier_limit_minutes("work"),
                ),
                self._earlier_action(
                    "link_break_earlier", "started_earlier_break",
                    lambda minutes: self._apply_time_correction("break", minutes),
                    lambda: self._earlier_limit_minutes("break"),
                ),
            ]
        elif kind == "break":
            self._pill(actions, self.t("resume_break"), self._toggle_pause, kind="primary", height=52, fill_x=True,
                       font=self._font("semi", 11)).pack(fill="x", pady=(8, 0))
            self._pill(actions, self.t("resume_work"), self._resume_after_break, kind="secondary", height=44, fill_x=True).pack(fill="x", pady=(8, 0))
            links = [
                self._earlier_action(
                    "link_break_continued", "started_earlier_paused_break",
                    lambda minutes: self._apply_time_correction("break", minutes),
                    lambda: self._earlier_limit_minutes("break"),
                ),
                self._earlier_action(
                    "link_back_earlier", "started_earlier_resume",
                    lambda minutes: self._apply_time_correction("work", minutes),
                    lambda: self._earlier_limit_minutes("work"),
                ),
            ]
        else:
            self._pill(actions, self.t("resume"), self._toggle_pause, kind="primary", height=52, fill_x=True,
                       font=self._font("semi", 11)).pack(fill="x", pady=(8, 0))
        links.append((self.t("finish"), self._finish_session))
        self._link_row(actions, [item for item in links if item])

    def _render_break(self) -> None:
        complete = self.engine.state == TimerState.REST_COMPLETE
        if self.current_activity is None:
            self.current_activity = self._choose_activity()
        title, body, note = self.current_activity
        if complete:
            self._screen_title(self.t("rest_complete"), self.t("rest_complete_body"))
        else:
            self._screen_title(self.t("break_title"), title)
        stage, actions = self._screen_frames()
        ttk.Frame(stage).pack(fill="both", expand=True)
        self._create_timer_ring(stage, size=262)
        self._render_undo_correction(stage)

        card = ttk.Frame(stage, style="Surface.TFrame", padding=(14, 10))
        card.pack(fill="x", pady=(6, 0))
        if complete:
            self._label(card, text=title, style="CardTitle.TLabel", wraplength=self._px(430)).pack(anchor="w")
        self._label(card, text=body, style="CardMuted.TLabel", wraplength=self._px(430), justify="left").pack(anchor="w")
        humor_context = "rest_complete" if complete else (self.activity_humor_context or "break_started")
        self._render_humor_line(
            card, humor_context, style="CardMuted.TLabel", wraplength=self._px(430), pady=(6, 0),
            minutes=max(1, int(self.engine.planned_break_minutes)),
        )
        if note:
            self._label(card, text=note, style="CardMuted.TLabel", wraplength=self._px(430), justify="left").pack(anchor="w", pady=(6, 0))
        if (
            not self.settings_data.get("humor")
            and not self.settings_data.get("humor_offer_shown")
            and self.break_count == 1
        ):
            self._label(card, text=self.t("humor_offer"), style="CardMuted.TLabel", wraplength=self._px(430), justify="left").pack(anchor="w", pady=(6, 0))
            self.settings_data["humor_offer_shown"] = True
            self.settings_store.save()
        idea_row = tk.Frame(card, background=self.colors["surface"])
        idea_row.pack(anchor="w", pady=(8, 0))
        self._pill(idea_row, self.t("another_idea"), self._another_activity, kind="quiet", height=30, pad_x=12,
                   font=self._font("ui", 9)).pack(side="left")
        if self.adaptive_notice_minutes:
            self._label(
                stage, text=self.t("adaptive_next_work", minutes=self.adaptive_notice_minutes),
                style="Muted.TLabel", wraplength=self._px(440),
            ).pack(anchor="center", pady=(6, 0))
        ttk.Frame(stage).pack(fill="both", expand=True)

        row = tk.Frame(actions, background=self.colors["bg"])
        row.pack(fill="x", pady=(8, 0))
        back = self._pill(row, self.t("resume_work"), self._resume_after_break, kind="primary", height=50, fill_x=True,
                          font=self._font("semi", 11))
        more = self._pill(row, self.t("add_five"), self._extend_break, kind="secondary", height=50, min_width=120)
        if self.lang == "fa":
            more.pack(side="left")
            back.pack(side="left", fill="x", expand=True, padx=(8, 0))
        else:
            back.pack(side="left", fill="x", expand=True, padx=(0, 8))
            more.pack(side="left")
        links = [
            self._earlier_action(
                "link_back_earlier", "started_earlier_resume",
                lambda minutes: self._apply_time_correction("work", minutes),
                lambda: self._earlier_limit_minutes("work"),
                context=("chip_break_ended", lambda: int(round(self.engine.overtime_seconds / 60.0)) if self.engine.state == TimerState.REST_COMPLETE else None),
            ),
            (self.t("reset_options"), self._open_quick_reset),
            (self.t("finish"), self._finish_session),
        ]
        self._link_row(actions, [item for item in links if item])

    def _humor_line(self, context: str | None, **values: Any) -> str:
        """Return one non-repeating, native-language humour line for this context."""
        if not context or not bool(self.settings_data.get("humor")):
            return ""
        language = self.lang if self.lang in HUMOR_LINES else "en"
        category = HUMOR_CONTEXT_TO_CATEGORY.get(context)
        bucket = (
            self.custom_messages.active_lines(language, category)
            if category and getattr(self, "custom_messages", None) is not None
            else []
        )
        if not bucket:
            bucket = list(HUMOR_LINES.get(language, {}).get(context, []))
        if not bucket:
            bucket = list(HUMOR_LINES.get("en", {}).get(context, []))
        if not bucket:
            return ""

        cache_values = tuple(sorted(values.items(), key=lambda item: item[0]))
        cache_key = (language, context, cache_values)
        if self._humor_cache_key == cache_key:
            return self._humor_cache_text

        elapsed_minutes = float(values.get("elapsed_minutes", 0.0) or 0.0)
        if context == "break_due_overrun" and elapsed_minutes < 50.0:
            bucket = [
                line for line in bucket
                if "minute fifty" not in line.lower()
                and "minute fünfzig" not in line.lower()
                and "دقیقه‌ی پنجاه" not in line
            ] or bucket

        candidates = [line for line in bucket if line not in self.recent_humor]
        if not candidates:
            candidates = bucket
        template = random.choice(candidates)
        self.recent_humor.append(template)
        raw = self._format_message_template(template, **values)
        shown = self._rtl_display(raw)
        self._humor_cache_key = cache_key
        self._humor_cache_text = shown
        return shown

    def _render_humor_line(
        self,
        parent: Any,
        context: str | None,
        *,
        style: str = "Muted.TLabel",
        wraplength: int = 440,
        anchor: str = "w",
        pady: tuple[int, int] = (4, 4),
        **values: Any,
    ) -> Any | None:
        text = self._humor_line(context, **values)
        if not text:
            return None
        label = self._label(parent, text=text, style=style, wraplength=wraplength, justify="left")
        label.pack(anchor=anchor, pady=pady)
        return label

    def _work_humor_context(self) -> str | None:
        if not bool(self.settings_data.get("humor")):
            return None
        if self.humor_hint == "resume_work":
            return "resume_work"
        if int(self.engine.planned_work_minutes) < 15:
            return "short_block"
        hour = datetime.now().hour
        if hour >= 20:
            return "late_evening"
        if hour < 9:
            return "early_morning"
        try:
            if float(self.history.day().get("work_seconds", 0.0)) >= 5 * 60 * 60:
                return "long_day"
        except (TypeError, ValueError):
            pass
        if date.today().weekday() == 4:
            return "friday"
        return None

    def _compact_total(self, seconds: float) -> str:
        """Short duration for chart labels: 3h 20m, or 3:20 in Persian."""
        if self.lang == "fa":
            total_minutes = max(0, int(round(float(seconds) / 60.0)))
            hours, minutes = divmod(total_minutes, 60)
            return f"{hours}:{minutes:02d}"
        return format_total(seconds)

    def _format_total_ui(self, seconds: float) -> str:
        """Format recorded totals without English h/m abbreviations in Persian UI."""
        total_minutes = max(0, int(round(float(seconds) / 60.0)))
        hours, minutes = divmod(total_minutes, 60)
        if self.lang == "fa":
            if hours and minutes:
                return f"{hours} ساعت {minutes} دقیقه"
            if hours:
                return f"{hours} ساعت"
            return f"{minutes} دقیقه"
        return format_total(seconds)

    def _rhythm_labels(self) -> dict[str, str]:
        return {
            "classic": self.t("rhythm_classic"),
            "balanced": self.t("rhythm_balanced"),
            "long": self.t("rhythm_long"),
            "52_17": self.t("rhythm_52_17"),
            "custom": self.t("rhythm_custom"),
        }

    def _adaptive_profile(
        self,
        rhythm: str,
        base_work: int | None = None,
        base_break: int | None = None,
    ) -> dict[str, Any]:
        rhythm = normalize_rhythm(rhythm, self.effort_var.get())
        profiles = self.settings_data.setdefault("adaptive_profiles", {})
        if not isinstance(profiles, dict):
            profiles = {}
            self.settings_data["adaptive_profiles"] = profiles
        profile = profiles.get(rhythm)
        if base_work is not None and base_break is not None:
            base_work = max(1, int(base_work))
            base_break = max(1, int(base_break))
            if (
                not isinstance(profile, dict)
                or int(profile.get("base_work", -1)) != base_work
                or int(profile.get("base_break", -1)) != base_break
            ):
                profile = {
                    "base_work": base_work,
                    "base_break": base_break,
                    "target": base_work,
                    "sample_target": base_work,
                    "samples": [],
                }
                profiles[rhythm] = profile
        if not isinstance(profile, dict):
            fallback_work, fallback_break = resolve_timing(rhythm, self.effort_var.get(), self.settings_data)
            profile = {
                "base_work": fallback_work,
                "base_break": fallback_break,
                "target": fallback_work,
                "sample_target": fallback_work,
                "samples": [],
            }
            profiles[rhythm] = profile
        return profile

    def _adaptive_work_target(self, rhythm: str, base_work: int, base_break: int) -> int:
        if not bool(self.settings_data.get("adaptive_timing", False)):
            return max(1, int(base_work))
        profile = self._adaptive_profile(rhythm, base_work, base_break)
        try:
            target = int(profile.get("target", base_work))
        except (TypeError, ValueError):
            target = int(base_work)
        adaptive_cap = max(int(base_work), ADAPTIVE_MAX_WORK_MINUTES)
        return max(int(base_work), min(adaptive_cap, target))

    def _selected_timing(self) -> tuple[int, int]:
        base_work, base_break = resolve_timing(self.rhythm_key, self.effort_var.get(), self.settings_data)
        work = self._adaptive_work_target(self.rhythm_key, base_work, base_break)
        rest = base_break
        if bool(self.settings_data.get("adaptive_timing", False)):
            rest = adaptive_break_minutes(base_work, base_break, work * 60.0)
        return work, rest

    def _preset_summary(self) -> str:
        work, rest = self._selected_timing()
        key = "ready_summary_adaptive" if bool(self.settings_data.get("adaptive_timing", False)) else "ready_summary"
        return self.t(key, work=work, rest=rest)

    def _adaptive_toggled(self) -> None:
        self.settings_data["adaptive_timing"] = bool(self.adaptive_var.get())
        self.settings_store.save()
        if self.engine.state == TimerState.READY and self.dynamic_note is not None:
            try:
                self.dynamic_note.configure(text=self._preset_summary())
                return
            except tk.TclError:
                pass
        self._render()

    def _record_adaptive_work_block(self, actual_seconds: float | None = None) -> int | None:
        """Learn only while Adaptive timing is selected; never shorten work."""
        if not bool(self.settings_data.get("adaptive_timing", False)):
            return None
        actual_minutes = max(0.0, float(
            self.engine.work_block_elapsed if actual_seconds is None else actual_seconds
        )) / 60.0
        if not 5.0 <= actual_minutes <= ADAPTIVE_MAX_SAMPLE_MINUTES:
            return None

        rhythm = normalize_rhythm(self.engine.rhythm, self.engine.effort)
        profile = self._adaptive_profile(rhythm)
        current_target = max(1, int(self.engine.planned_work_minutes))
        try:
            sample_target = int(profile.get("sample_target", current_target))
        except (TypeError, ValueError):
            sample_target = current_target
        samples = profile.get("samples")
        if sample_target != current_target or not isinstance(samples, list):
            samples = []
            profile["sample_target"] = current_target
        samples.append(round(actual_minutes, 3))
        samples = samples[-ADAPTIVE_SAMPLE_WINDOW:]
        profile["samples"] = samples

        new_target = next_adaptive_work_target(current_target, samples)
        if new_target > current_target:
            average = sum(samples) / len(samples)
            profile["target"] = new_target
            profile["sample_target"] = new_target
            profile["samples"] = []
            self.adaptive_notice_minutes = new_target
            self._record_event(
                "adaptive_work_target_changed",
                old_work_minutes=current_target,
                new_work_minutes=new_target,
                sample_count=len(samples),
                average_work_minutes=round(average, 2),
            )
        self.settings_store.save()
        return new_target

    def _time_tip(self) -> str:
        hour = datetime.now().hour
        if hour < 12:
            return self.t("morning_tip")
        if hour < 18:
            return self.t("afternoon_tip")
        return self.t("evening_tip")

    def _effort_changed(self) -> None:
        effort = self.effort_var.get()
        if effort not in {"easy", "moderate", "demanding"}:
            effort = "moderate"
        self.settings_data["last_effort"] = effort
        self.settings_store.save()
        if self.dynamic_note:
            self.dynamic_note.configure(text=self._preset_summary())

    def _rhythm_changed(self, _event: Any | None = None) -> None:
        reverse_labels = {label: key for key, label in self._rhythm_labels().items()}
        self.rhythm_key = reverse_labels.get(self.rhythm_label_var.get(), "balanced")
        self.settings_data["last_rhythm"] = self.rhythm_key
        self.settings_store.save()
        if self.engine.state == TimerState.READY and self.dynamic_note is not None:
            try:
                self.dynamic_note.configure(text=self._preset_summary())
                return
            except tk.TclError:
                pass
        self._render()

    def _start_session(self, override_minutes: int | None = None) -> None:
        self._forget_time_correction()
        self.humor_hint = None
        self.activity_humor_context = None
        self.break_count = 0
        effort = "moderate"  # Compatibility field for snapshots created before 0.5.
        try:
            already_minutes = max(0, int(self.already_var.get() or "0"))
        except ValueError:
            already_minutes = 0
        base_work, selected_break = resolve_timing(self.rhythm_key, effort, self.settings_data)
        selected_work = self._adaptive_work_target(self.rhythm_key, base_work, selected_break)
        work_minutes = override_minutes or selected_work
        self.task = self.task_var.get().strip()
        if self.task:
            self.task_history.remember(self.task)
        self.settings_data["last_effort"] = effort
        self.settings_data["last_rhythm"] = self.rhythm_key
        self.session_id = uuid.uuid4().hex
        self.work_block_id = uuid.uuid4().hex
        self.engine.start_work(
            work_minutes,
            effort,
            already_minutes * 60,
            planned_break_minutes=selected_break,
            rhythm=self.rhythm_key,
        )
        self.history.start_session()
        if already_minutes:
            self.history.add_seconds("work", already_minutes * 60)
        self._record_event(
            "session_started",
            initial_work_seconds=already_minutes * 60,
        )
        self._record_event(
            "work_block_started",
            reason="session_start",
            initial_work_seconds=already_minutes * 60,
        )
        self.history.save()
        self.settings_store.save()
        self.pending_snapshot = None
        self._save_session()
        self._render()
        if self.engine.state == TimerState.WORK_DUE:
            self._notify()

    def _toggle_pause(self) -> None:
        if not self.engine.active:
            return
        self.humor_hint = None
        self._forget_time_correction()
        if self.engine.state == TimerState.PAUSED:
            self.engine.resume()
            self.pause_started_at = None
            self._record_event("timer_resumed")
        else:
            self.engine.pause()
            self.pause_started_at = datetime.now().astimezone()
            self._record_event("timer_paused")
        self._reset_tick_clocks()
        self._save_session()
        self._render()

    def _suggested_break_minutes(self, actual_work_seconds: float | None = None) -> int:
        ordinary = int(self.engine.planned_break_minutes)
        if bool(self.settings_data.get("adaptive_timing", False)):
            profile = self._adaptive_profile(self.engine.rhythm)
            try:
                base_work = max(1, int(profile.get("base_work", self.engine.planned_work_minutes)))
                base_break = max(1, int(profile.get("base_break", self.engine.planned_break_minutes)))
            except (TypeError, ValueError):
                base_work, base_break = resolve_timing(
                    self.engine.rhythm, self.engine.effort, self.settings_data
                )
            ordinary = adaptive_break_minutes(
                base_work,
                base_break,
                self.engine.work_block_elapsed if actual_work_seconds is None else actual_work_seconds,
            )
        if self._lunch_is_due():
            return max(int(self.settings_data["lunch_minutes"]), ordinary)
        threshold = int(self.settings_data["long_break_after"]) * 60
        if self.engine.work_since_long_break >= threshold:
            return max(
                int(self.settings_data["long_break_minutes"]),
                ordinary,
            )
        return ordinary

    def _take_break(self) -> None:
        if not self.engine.active:
            return
        self._begin_break(self._suggested_break_minutes(), reason="user")

    def _begin_break(
        self,
        minutes: int,
        allow_scheduled_suggestions: bool = True,
        reason: str = "due",
    ) -> None:
        self._forget_time_correction()
        self.humor_hint = "break_started"
        effective_state = (
            self.engine.paused_from
            if self.engine.state == TimerState.PAUSED
            else self.engine.state
        )
        event_name = (
            "break_restarted"
            if effective_state in {TimerState.RESTING, TimerState.REST_COMPLETE}
            else "break_started"
        )
        if effective_state in {TimerState.WORKING, TimerState.WORK_DUE}:
            self._record_adaptive_work_block()
        self._record_event(
            event_name,
            reason=reason,
            early=(
                effective_state == TimerState.WORKING
                and self.engine.work_block_elapsed
                < self.engine.planned_work_minutes * 60
            ),
            work_elapsed_seconds=round(self.engine.work_block_elapsed, 3),
            break_minutes=max(1, int(minutes)),
        )
        self.engine.start_break(minutes)
        self.pause_started_at = None
        self.break_count += 1
        self.current_activity = self._choose_activity(force_regular=not allow_scheduled_suggestions)
        self._save_session()
        self._render()

    def _snooze(self) -> None:
        self._forget_time_correction()
        self._record_event("break_snoozed", seconds=300)
        self.engine.snooze_work(300)
        self._save_session()
        self._render()

    def _resume_after_break(self) -> None:
        self._forget_time_correction()
        self.humor_hint = "resume_work"
        self.activity_humor_context = None
        effective_state = self.engine.paused_from if self.engine.state == TimerState.PAUSED else self.engine.state
        self._record_event(
            "break_ended",
            completed=effective_state == TimerState.REST_COMPLETE,
            break_elapsed_seconds=round(self.engine.break_elapsed, 3),
            uncounted_overtime_seconds=round(self.engine.overtime_seconds, 3),
        )
        effort = self.engine.effort
        break_minutes = self.engine.planned_break_minutes
        rhythm = self.engine.rhythm
        profile = self._adaptive_profile(rhythm) if bool(self.settings_data.get("adaptive_timing", False)) else None
        work_minutes = self.engine.planned_work_minutes
        if profile is not None:
            try:
                work_minutes = max(work_minutes, int(profile.get("target", work_minutes)))
                base_work = max(1, int(profile.get("base_work", work_minutes)))
                base_break = max(1, int(profile.get("base_break", break_minutes)))
                break_minutes = adaptive_break_minutes(base_work, base_break, work_minutes * 60.0)
            except (TypeError, ValueError):
                pass
        self.work_block_id = uuid.uuid4().hex
        self.engine.start_work(
            work_minutes,
            effort,
            planned_break_minutes=break_minutes,
            rhythm=rhythm,
        )
        self.pause_started_at = None
        self._record_event("work_block_started", reason="after_break", initial_work_seconds=0)
        self.adaptive_notice_minutes = None
        self.current_activity = None
        self._save_session()
        self._render()

    def _extend_break(self) -> None:
        self._forget_time_correction()
        self._record_event("break_extended", seconds=300)
        self.engine.extend_break(300)
        self._save_session()
        self._render()

    def _another_activity(self) -> None:
        self.current_activity = self._choose_activity(force_regular=True)
        self._render()

    def _finish_session(self) -> None:
        self._forget_time_correction()
        self.pause_started_at = None
        effective_state = (
            self.engine.paused_from
            if self.engine.state == TimerState.PAUSED
            else self.engine.state
        )
        if effective_state in {TimerState.RESTING, TimerState.REST_COMPLETE}:
            self._record_event(
                "break_ended",
                reason="session_finished",
                completed=effective_state == TimerState.REST_COMPLETE,
                break_elapsed_seconds=round(self.engine.break_elapsed, 3),
                uncounted_overtime_seconds=round(self.engine.overtime_seconds, 3),
            )
        elif effective_state in {TimerState.WORKING, TimerState.WORK_DUE}:
            self._record_adaptive_work_block()
            self._record_event(
                "work_block_ended",
                reason="session_finished",
                work_elapsed_seconds=round(self.engine.work_block_elapsed, 3),
            )
        self._record_event(
            "session_finished",
            work_elapsed_seconds=round(self.engine.work_block_elapsed, 3),
            break_elapsed_seconds=round(self.engine.break_elapsed, 3),
        )
        self.history.mark_stop()
        self.engine.finish()
        self.humor_hint = None
        self.activity_humor_context = None
        self.task = ""
        self.task_var.set("")
        self.already_var.set("0")
        self.current_activity = None
        self.session_id = ""
        self.work_block_id = ""
        self._save_all()
        self._render()

    @staticmethod
    def _split_time_range(start: datetime, end: datetime) -> list[tuple[str, float]]:
        """Split a local datetime range at midnight for daily history totals."""
        if end <= start:
            return []
        pieces: list[tuple[str, float]] = []
        cursor = start
        while cursor.date() < end.date():
            midnight = datetime.combine(cursor.date() + timedelta(days=1), datetime.min.time())
            pieces.append((cursor.date().isoformat(), max(0.0, (midnight - cursor).total_seconds())))
            cursor = midnight
        pieces.append((cursor.date().isoformat(), max(0.0, (end - cursor).total_seconds())))
        return [(day_key, seconds) for day_key, seconds in pieces if seconds > 0]

    def _adjust_history_range(
        self, kind: str, start: datetime, end: datetime, direction: int
    ) -> float:
        """Add or subtract one real-time interval from daily history totals."""
        applied = 0.0
        for day_key, seconds in self._split_time_range(start, end):
            delta = seconds if direction > 0 else -seconds
            applied += self.history.adjust_seconds(kind, delta, day_key)
        return applied

    def _paused_elapsed_seconds(self) -> float:
        if self.engine.state != TimerState.PAUSED:
            return 0.0
        started = self.pause_started_at
        if started is None:
            # Backward-compatible fallback for a pause created before 0.16.4 or
            # an unusual callback path. The most recent pause event is enough to
            # bound an explicit Started earlier correction.
            try:
                for record in reversed(self.events.records()):
                    if record.get("event") not in {"timer_paused", "timer_paused_after_gap"}:
                        continue
                    if self.session_id and record.get("session_id") not in {None, self.session_id}:
                        continue
                    at = parse_event_datetime(record.get("at"))
                    if at is not None:
                        if record.get("event") == "timer_paused_after_gap":
                            try:
                                at -= timedelta(seconds=max(0.0, float(record.get("gap_seconds", 0.0))))
                            except (TypeError, ValueError):
                                pass
                        started = at
                        break
            except Exception:
                started = None
        if started is None:
            return 0.0
        now = datetime.now().astimezone()
        try:
            if started.tzinfo is None:
                started = started.astimezone()
            return max(0.0, (now - started).total_seconds())
        except (TypeError, ValueError, OSError):
            return 0.0

    def _paused_context_kind(self) -> str | None:
        paused_from = self.engine.paused_from
        if paused_from in {TimerState.WORKING, TimerState.WORK_DUE}:
            return "work"
        if paused_from in {TimerState.RESTING, TimerState.REST_COMPLETE}:
            return "break"
        return None

    def _current_session_start(self) -> datetime | None:
        """Best known logical start of the current session."""
        if not self.session_id:
            return None
        earliest: datetime | None = None
        try:
            for record in self.events.records():
                if str(record.get("session_id") or "") != self.session_id:
                    continue
                at = parse_event_datetime(record.get("at"))
                if at is None:
                    continue
                if record.get("event") == "session_started":
                    try:
                        initial = max(0.0, float(record.get("initial_work_seconds", 0.0)))
                    except (TypeError, ValueError):
                        initial = 0.0
                    return at - timedelta(seconds=initial)
                if earliest is None or at < earliest:
                    earliest = at
        except Exception:
            LOGGER.exception("Could not determine current session start")
        return earliest

    def _recent_correction_intervals(self, now: datetime | None = None) -> list[ActivityInterval]:
        """Current-session intervals exactly as Insights presently reconstructs them."""
        now = now or datetime.now().astimezone()
        intervals = reconstruct_activity_intervals(
            self.events.records(),
            live_session_id=self.session_id,
            live_kind=self._current_timeline_kind(),
            now=now,
        )
        if not self.session_id:
            return intervals
        return [item for item in intervals if not item.session_id or item.session_id == self.session_id]

    def _earliest_correction_start(self, target_kind: str, now: datetime | None = None) -> datetime | None:
        """Bound one correction to the current transition, not several work/break cycles."""
        target_kind = "work" if target_kind == "work" else "break"
        now = now or datetime.now().astimezone()
        session_start = self._current_session_start()
        # The immediately preceding interval of the requested kind is already
        # correct. Let the window extend through it, then stop at its start. This
        # covers: break -> Resume -> forgot Break, and the reverse, without
        # reaching into an older cycle. Untracked gaps between those intervals are
        # intentionally eligible because the user is explicitly correcting them.
        for item in reversed(self._recent_correction_intervals(now)):
            if item.kind != target_kind:
                continue
            candidate = item.start
            if session_start is not None and candidate < session_start:
                candidate = session_start
            return candidate
        return session_start

    @staticmethod
    def _window_overlap(interval: ActivityInterval, start: datetime, end: datetime) -> tuple[datetime, datetime] | None:
        overlap_start = max(start, interval.start)
        overlap_end = min(end, interval.end)
        return (overlap_start, overlap_end) if overlap_end > overlap_start else None

    def _correction_window_stats(
        self, start: datetime, end: datetime
    ) -> tuple[list[ActivityInterval], float, float, float, float]:
        """Return intervals plus work/break/current-block/untracked seconds in a window."""
        intervals = self._recent_correction_intervals(end)
        work = 0.0
        rest = 0.0
        current_block_work = 0.0
        covered: list[tuple[datetime, datetime]] = []
        for item in intervals:
            overlap = self._window_overlap(item, start, end)
            if overlap is None:
                continue
            a, b = overlap
            seconds = (b - a).total_seconds()
            covered.append((a, b))
            if item.kind == "work":
                work += seconds
                if self.work_block_id and item.work_block_id == self.work_block_id:
                    current_block_work += seconds
            elif item.kind == "break":
                rest += seconds
        # Union the covered ranges so even a legacy overlapping timeline cannot
        # make the computed untracked amount negative or double-counted.
        covered.sort(key=lambda pair: pair[0])
        merged: list[list[datetime]] = []
        for a, b in covered:
            if not merged or a > merged[-1][1]:
                merged.append([a, b])
            elif b > merged[-1][1]:
                merged[-1][1] = b
        tracked_union = sum((b - a).total_seconds() for a, b in merged)
        untracked = max(0.0, (end - start).total_seconds() - tracked_union)
        return intervals, work, rest, current_block_work, untracked

    def _adjust_overlapping_intervals(
        self, kind: str, intervals: list[ActivityInterval], start: datetime, end: datetime, direction: int
    ) -> float:
        """Adjust history only where reconstructed intervals of one kind overlap a window."""
        applied = 0.0
        for item in intervals:
            if item.kind != kind:
                continue
            overlap = self._window_overlap(item, start, end)
            if overlap is None:
                continue
            applied += self._adjust_history_range(kind, overlap[0], overlap[1], direction)
        return applied

    def _adjust_target_replacement(
        self, kind: str, intervals: list[ActivityInterval], start: datetime, end: datetime
    ) -> float:
        """Count every part of a correction window not already recorded as target kind."""
        spans: list[tuple[datetime, datetime]] = []
        for item in intervals:
            if item.kind != kind:
                continue
            overlap = self._window_overlap(item, start, end)
            if overlap is not None:
                spans.append(overlap)
        spans.sort(key=lambda pair: pair[0])
        applied = 0.0
        cursor = start
        for a, b in spans:
            if a > cursor:
                applied += self._adjust_history_range(kind, cursor, a, 1)
            if b > cursor:
                cursor = b
        if cursor < end:
            applied += self._adjust_history_range(kind, cursor, end, 1)
        return applied

    def _earlier_limit_minutes(self, target_kind: str) -> int:
        """Maximum sensible Started earlier window for the current transition."""
        target_kind = "work" if target_kind == "work" else "break"
        if self.engine.state == TimerState.PAUSED:
            context_kind = self._paused_context_kind()
            if context_kind is None:
                return 0
            paused = self._paused_elapsed_seconds()
            if target_kind == context_kind:
                available = paused
            else:
                if context_kind == "work":
                    legacy_available = paused + max(0.0, self.engine.work_block_elapsed)
                else:
                    legacy_available = paused + max(0.0, self.engine.break_elapsed + self.engine.overtime_seconds)
                now = datetime.now().astimezone()
                earliest = self._earliest_correction_start(target_kind, now)
                expanded_available = (
                    0.0 if earliest is None else max(0.0, (now - earliest).total_seconds())
                )
                available = max(legacy_available, expanded_available)
            return max(0, int(available // 60))
        context = self._correction_context()
        if context is None or context[0] == target_kind:
            return 0
        now = datetime.now().astimezone()
        earliest = self._earliest_correction_start(target_kind, now)
        available = context[1] if earliest is None else max(context[1], (now - earliest).total_seconds())
        return max(0, int(max(0.0, available) // 60))

    def _correction_context(self) -> tuple[str, float] | None:
        if self.engine.state in {TimerState.WORKING, TimerState.WORK_DUE}:
            return "work", max(0.0, self.engine.work_block_elapsed)
        if self.engine.state == TimerState.RESTING:
            return "break", max(0.0, self.engine.break_elapsed)
        if self.engine.state == TimerState.REST_COMPLETE:
            return "break", max(0.0, self.engine.break_elapsed + self.engine.overtime_seconds)
        return None

    def _capture_time_correction(self) -> dict[str, Any]:
        return {
            "engine": copy.deepcopy(self.engine.snapshot()),
            "history": copy.deepcopy(self.history.data),
            "work_block_id": self.work_block_id,
            "current_activity": copy.deepcopy(self.current_activity),
            "activity_humor_context": self.activity_humor_context,
            "humor_hint": self.humor_hint,
            "activity_index": self.activity_index,
            "break_count": self.break_count,
            "pause_started_at": getattr(self, "pause_started_at", None).isoformat(timespec="seconds") if getattr(self, "pause_started_at", None) else "",
            "runtime_settings": {
                "work_counter_day": self.settings_data.get("work_counter_day", ""),
                "work_since_long_break": self.settings_data.get("work_since_long_break", 0.0),
            },
        }

    def _undo_time_correction(self) -> bool:
        snapshot = self.last_time_correction
        if not snapshot:
            return False
        try:
            self.engine.restore(copy.deepcopy(snapshot["engine"]), pause_active=False)
            self.history.data = copy.deepcopy(snapshot["history"])
            self.work_block_id = str(snapshot.get("work_block_id", self.work_block_id))
            self.current_activity = copy.deepcopy(snapshot.get("current_activity"))
            self.activity_humor_context = snapshot.get("activity_humor_context")
            self.humor_hint = snapshot.get("humor_hint")
            self.activity_index = max(0, int(snapshot.get("activity_index", self.activity_index)))
            self.break_count = max(0, int(snapshot.get("break_count", self.break_count)))
            raw_pause = snapshot.get("pause_started_at")
            self.pause_started_at = parse_event_datetime(raw_pause) if raw_pause else None
            saved_runtime = snapshot.get("runtime_settings")
            if isinstance(saved_runtime, dict):
                for key in ("work_counter_day", "work_since_long_break"):
                    if key in saved_runtime:
                        self.settings_data[key] = copy.deepcopy(saved_runtime[key])
            self.last_time_correction = None
            self._reset_tick_clocks()
            self._record_event("time_correction_undone")
            self._save_all()
            self._render()
            self._sync_tray_state()
            return True
        except (KeyError, TypeError, ValueError, tk.TclError):
            LOGGER.exception("Could not undo the last time correction")
            return False

    def _apply_paused_time_correction(self, target_kind: str, minutes: int) -> str | None:
        """Apply Started earlier while the timer itself is paused.

        Paused time is intentionally untracked. An explicit correction may backfill
        that gap, and a cross-state correction may also reclassify the tail of the
        activity that was being counted immediately before Pause.
        """
        context_kind = self._paused_context_kind()
        if context_kind is None:
            return self.t("correct_wrong_context")
        limit = self._earlier_limit_minutes(target_kind)
        if limit < 1:
            return self.t("correct_too_far", minutes=0)
        if minutes < 1 or minutes > limit:
            return self.t("correct_too_far", minutes=limit)

        undo = self._capture_time_correction()
        now = datetime.now().astimezone()
        seconds = float(minutes * 60)
        pause_seconds = self._paused_elapsed_seconds()
        pause_part = min(seconds, pause_seconds)
        pre_pause_part = max(0.0, seconds - pause_part)
        start = now - timedelta(seconds=seconds)
        pause_at = now - timedelta(seconds=pause_seconds)
        long_break_seconds = float(int(self.settings_data["long_break_minutes"]) * 60)
        previous_state = self.engine.state.value
        previous_work_block_id = self.work_block_id

        removed_work = 0.0
        removed_break = 0.0
        added_work = 0.0
        added_break = 0.0

        if context_kind == "work":
            tracked_before_pause = min(pre_pause_part, max(0.0, self.engine.work_block_elapsed))
            if target_kind == "work":
                # Only the chosen tail of the pause gap was untracked; earlier work
                # before Pause was already counted correctly.
                add_start = now - timedelta(seconds=pause_part)
                if pause_part > 0:
                    added_work = self._adjust_history_range("work", add_start, now, 1)
                self.engine.resume()
                if pause_part > 0:
                    self.engine.tick(pause_part, long_break_seconds)
                self.humor_hint = "resume_work"
            else:
                # Reclassify any tracked work reached by the correction and count
                # the paused tail as break as well.
                if tracked_before_pause > 0:
                    remove_end = pause_at
                    remove_start = remove_end - timedelta(seconds=tracked_before_pause)
                    removed_work = -self._adjust_history_range("work", remove_start, remove_end, -1)
                added_break = self._adjust_history_range("break", start, now, 1)
                corrected_work_elapsed = max(0.0, self.engine.work_block_elapsed - removed_work)
                self.engine.work_since_long_break = max(0.0, self.engine.work_since_long_break - removed_work)
                suggested_break = self._suggested_break_minutes(corrected_work_elapsed)
                effective_break_minutes = max(suggested_break, max(1, minutes))
                self.engine.start_break(effective_break_minutes)
                self.engine.tick(seconds, long_break_seconds)
                self.humor_hint = "break_started"
                self.current_activity = self._choose_activity()
                self.break_count += 1
        else:
            # A paused break can contain counted break time, uncounted completed-
            # break overtime, then the pause gap. Keep those portions distinct.
            overtime_before_pause = min(pre_pause_part, max(0.0, self.engine.overtime_seconds))
            tracked_break_before_pause = max(0.0, pre_pause_part - overtime_before_pause)
            tracked_break_before_pause = min(tracked_break_before_pause, max(0.0, self.engine.break_elapsed))
            if target_kind == "break":
                # Same-state correction only backfills the pause gap by design.
                if pause_part > 0:
                    add_start = now - timedelta(seconds=pause_part)
                    added_break = self._adjust_history_range("break", add_start, now, 1)
                self.engine.resume()
                if pause_part > 0:
                    # Ensure an explicitly confirmed break interval is counted even
                    # if the planned break had already completed.
                    if self.engine.state == TimerState.REST_COMPLETE:
                        self.engine.extend_break(int(math.ceil(pause_part)))
                    elif self.engine.state == TimerState.RESTING and self.engine.remaining_seconds < pause_part:
                        self.engine.extend_break(int(math.ceil(pause_part - self.engine.remaining_seconds)))
                    self.engine.tick(pause_part, long_break_seconds)
                self.humor_hint = "break_started"
            else:
                if tracked_break_before_pause > 0:
                    tracked_end = pause_at - timedelta(seconds=overtime_before_pause)
                    tracked_start = tracked_end - timedelta(seconds=tracked_break_before_pause)
                    removed_break = -self._adjust_history_range("break", tracked_start, tracked_end, -1)
                added_work = self._adjust_history_range("work", start, now, 1)
                actual_break_before_work = max(0.0, self.engine.break_elapsed - removed_break)
                corrected_counter = 0.0 if actual_break_before_work >= long_break_seconds else max(
                    0.0, self.engine.work_counter_at_break_start
                )
                effort = self.engine.effort
                work_minutes = self.engine.planned_work_minutes
                break_minutes = self.engine.planned_break_minutes
                rhythm = self.engine.rhythm
                self.engine.work_since_long_break = corrected_counter
                self.work_block_id = uuid.uuid4().hex
                self.engine.start_work(
                    work_minutes,
                    effort,
                    planned_break_minutes=break_minutes,
                    rhythm=rhythm,
                )
                self.engine.tick(seconds, long_break_seconds)
                self.current_activity = None
                self.activity_humor_context = None
                self.humor_hint = "resume_work"

        self.pause_started_at = None
        correction = "started_work_earlier" if target_kind == "work" else "started_break_earlier"
        self._record_event(
            "time_corrected",
            correction=correction,
            previous_state=previous_state,
            previous_kind=context_kind,
            corrected_transition_at=start.isoformat(timespec="seconds"),
            corrected_seconds=round(seconds, 3),
            paused_backfill_seconds=round(pause_part, 3),
            work_removed_seconds=round(removed_work, 3),
            break_removed_seconds=round(removed_break, 3),
            work_added_seconds=round(added_work, 3),
            break_added_seconds=round(added_break, 3),
            previous_work_block_id=previous_work_block_id,
        )
        self.last_time_correction = undo
        self._reset_tick_clocks()
        self._save_all()
        self._render()
        self._sync_tray_state()
        return None

    def _apply_time_correction(self, target: str, minutes: int) -> str | None:
        """Reconcile a recent transition window and return a translated error, if any."""
        target_kind = "work" if target == "work" else "break"
        try:
            minutes = int(minutes)
        except (TypeError, ValueError):
            return self.t("correct_invalid")
        if minutes < 1:
            return self.t("correct_invalid")
        if self.engine.state == TimerState.PAUSED:
            return self._apply_paused_time_correction(target_kind, minutes)
        context = self._correction_context()
        if context is None:
            return self.t("correct_wrong_context")
        current_kind, context_seconds = context
        if target_kind == current_kind:
            return self.t("correct_wrong_context")

        limit = self._earlier_limit_minutes(target_kind)
        if limit < 1 or minutes > limit:
            return self.t("correct_too_far", minutes=max(0, limit))

        undo = self._capture_time_correction()
        now = datetime.now().astimezone()
        seconds = float(minutes * 60)
        start = now - timedelta(seconds=seconds)
        long_break_seconds = float(int(self.settings_data["long_break_minutes"]) * 60)
        previous_state = self.engine.state.value
        previous_work_block_id = self.work_block_id
        intervals, tracked_work, tracked_break, current_block_work, untracked = (
            self._correction_window_stats(start, now)
        )
        # Event history is normally authoritative, but keep the correction path
        # resilient if an old/compacted/corrupt event file lacks the live interval.
        # Synthesize only the current counted tail; never guess beyond it.
        if tracked_work + tracked_break < 1.0 and context_seconds > 0:
            if current_kind == "work":
                fallback = min(seconds, max(0.0, self.engine.work_block_elapsed))
                if fallback > 0:
                    synthetic = ActivityInterval(
                        interval_id="fallback:current-work",
                        kind="work",
                        start=now - timedelta(seconds=fallback),
                        end=now,
                        task=self.task,
                        session_id=self.session_id,
                        work_block_id=self.work_block_id,
                    )
                    intervals.append(synthetic)
                    tracked_work = fallback
                    current_block_work = fallback
            else:
                overtime_recent = (
                    min(seconds, max(0.0, self.engine.overtime_seconds))
                    if self.engine.state == TimerState.REST_COMPLETE
                    else 0.0
                )
                counted = min(
                    max(0.0, seconds - overtime_recent),
                    max(0.0, self.engine.break_elapsed),
                )
                if counted > 0:
                    end_counted = now - timedelta(seconds=overtime_recent)
                    synthetic = ActivityInterval(
                        interval_id="fallback:current-break",
                        kind="break",
                        start=end_counted - timedelta(seconds=counted),
                        end=end_counted,
                        session_id=self.session_id,
                        work_block_id=self.work_block_id,
                    )
                    intervals.append(synthetic)
                    tracked_break = counted
            untracked = max(0.0, seconds - min(seconds, tracked_work + tracked_break))

        removed_work = 0.0
        removed_break = 0.0
        added_work = 0.0
        added_break = 0.0

        if target_kind == "break":
            if tracked_work > 0:
                removed_work = -self._adjust_overlapping_intervals(
                    "work", intervals, start, now, -1
                )
            added_break = self._adjust_target_replacement("break", intervals, start, now)

            corrected_work_elapsed = max(0.0, self.engine.work_block_elapsed - current_block_work)
            if seconds >= long_break_seconds:
                self.engine.work_since_long_break = 0.0
            else:
                self.engine.work_since_long_break = max(
                    0.0, self.engine.work_since_long_break - removed_work
                )
            suggested_break = self._suggested_break_minutes(corrected_work_elapsed)
            effective_break_minutes = max(suggested_break, max(1, minutes))
            self.engine.start_break(effective_break_minutes)
            self.engine.tick(seconds, long_break_seconds)
            self.humor_hint = "break_started"
            self.current_activity = self._choose_activity()
            self.break_count += 1
        else:
            # The engine knows exactly which part of a completed break was counted
            # and which part is untracked overtime. Use that authoritative split
            # for history removal, even if an old/missing event makes the timeline
            # reconstruction less precise.
            overtime_recent = (
                min(seconds, max(0.0, self.engine.overtime_seconds))
                if self.engine.state == TimerState.REST_COMPLETE
                else 0.0
            )
            counted_break_seconds = min(
                max(0.0, seconds - overtime_recent),
                max(0.0, self.engine.break_elapsed),
            )
            if counted_break_seconds > 0:
                break_end = now - timedelta(seconds=overtime_recent)
                break_start = break_end - timedelta(seconds=counted_break_seconds)
                removed_break = -self._adjust_history_range(
                    "break", break_start, break_end, -1
                )
            tracked_break = counted_break_seconds
            untracked = max(0.0, seconds - min(seconds, tracked_work + tracked_break))
            added_work = self._adjust_target_replacement("work", intervals, start, now)

            actual_break_before_work = max(0.0, context_seconds - seconds)
            if actual_break_before_work >= long_break_seconds:
                corrected_counter = 0.0
            else:
                # Any target-work overlap before the break was already present in
                # work_counter_at_break_start. Remove it from the baseline before
                # advancing the new work block through the full corrected window.
                corrected_counter = max(
                    0.0, self.engine.work_counter_at_break_start - tracked_work
                )
            effort = self.engine.effort
            work_minutes = self.engine.planned_work_minutes
            break_minutes = self.engine.planned_break_minutes
            rhythm = self.engine.rhythm
            self.engine.work_since_long_break = corrected_counter
            self.work_block_id = uuid.uuid4().hex
            self.engine.start_work(
                work_minutes,
                effort,
                planned_break_minutes=break_minutes,
                rhythm=rhythm,
            )
            self.engine.tick(seconds, long_break_seconds)
            self.current_activity = None
            self.activity_humor_context = None
            self.humor_hint = "resume_work"

        correction = "started_work_earlier" if target_kind == "work" else "started_break_earlier"
        self._record_event(
            "time_corrected",
            correction=correction,
            previous_state=previous_state,
            previous_kind=current_kind,
            corrected_transition_at=start.isoformat(timespec="seconds"),
            corrected_seconds=round(seconds, 3),
            window_override=True,
            tracked_work_seconds=round(tracked_work, 3),
            tracked_break_seconds=round(tracked_break, 3),
            untracked_backfill_seconds=round(untracked, 3),
            work_removed_seconds=round(removed_work, 3),
            break_removed_seconds=round(removed_break, 3),
            work_added_seconds=round(added_work, 3),
            break_added_seconds=round(added_break, 3),
            previous_work_block_id=previous_work_block_id,
        )

        self.last_time_correction = undo
        self._reset_tick_clocks()
        self._save_all()
        self._render()
        self._sync_tray_state()
        return None

    def _forget_time_correction(self) -> None:
        self.last_time_correction = None

    def _open_quick_reset(self) -> None:
        popup = self._popup(self.t("quick_reset_title"), 450, 335)
        frame = ttk.Frame(popup, padding=22)
        frame.pack(fill="both", expand=True)
        self._label(frame, text=self.t("quick_reset_title"), style="Section.TLabel", wraplength=370).pack(anchor="w")
        self._label(frame, text=self.t("quick_reset_body"), style="Muted.TLabel", wraplength=370).pack(anchor="w", pady=(6, 18))

        def rest(minutes: int) -> None:
            popup.destroy()
            self._begin_break(minutes, allow_scheduled_suggestions=False, reason="reset")

        def short_block() -> None:
            popup.destroy()
            self._forget_time_correction()
            self._record_event("work_block_ended", reason="reset")
            self.work_block_id = uuid.uuid4().hex
            self.engine.start_work(
                10,
                self.engine.effort,
                planned_break_minutes=self.engine.planned_break_minutes,
                rhythm="custom",
            )
            self._record_event("work_block_started", reason="ten_minute_reset", initial_work_seconds=0)
            self._save_session()
            self._render()

        self._primary_button(frame, self.t("rest_two"), lambda: rest(2)).pack(fill="x")
        ttk.Button(frame, text=self.t("rest_ten"), command=lambda: rest(10)).pack(fill="x", pady=(7, 0))
        ttk.Button(frame, text=self.t("short_block"), command=short_block).pack(fill="x", pady=(7, 0))
        ttk.Button(frame, text=self.t("cancel"), style="Secondary.TButton", command=popup.destroy).pack(pady=(9, 0))
        self._apply_directionality(frame)

    def _choose_activity(self, force_regular: bool = False) -> tuple[str, str, str]:
        self.activity_humor_context = None
        today = date.today().isoformat()
        if self._lunch_is_due() and not force_regular:
            self.settings_data["last_lunch_day"] = today
            self.settings_store.save()
            return self.t("lunch_title"), self.t("lunch_body"), ""

        mode = self.settings_data.get("personal_mode", "first_break")
        personal_due = bool(self.settings_data.get("personal_enabled")) and (
            mode == "every_break" or (mode == "first_break" and self.settings_data.get("last_personal_day") != today)
        )
        if personal_due and not force_regular:
            self.settings_data["last_personal_day"] = today
            self.settings_store.save()
            title = self.t("personal_reminder")
            body = self.settings_data.get("personal_text", "").strip() or self.t("default_personal")
            note = self.settings_data.get("personal_details", "").strip()
            return title, body, note

        drink_choice = self.settings_data.get("drink_choice", "off")
        if self._drink_is_due() and not force_regular:
            self.settings_data["last_drink_day"] = today
            self.settings_store.save()
            body_key = {
                "coffee": "coffee_body",
                "tea": "tea_body",
                "either": "coffee_or_tea_body",
            }.get(drink_choice, "coffee_or_tea_body")
            return self.t("drink_title"), self.t(body_key), ""

        if self._snack_is_due() and not force_regular:
            self.settings_data["last_snack_day"] = today
            self.settings_store.save()
            return self.t("snack_title"), self.t("snack_body"), ""

        if self.settings_data.get("water_reminders") and self._water_is_due() and not force_regular:
            self.settings_data["last_water_prompt"] = datetime.now().isoformat(timespec="minutes")
            self.settings_store.save()
            self.activity_humor_context = "water"
            return self.t("water_title"), self.t("water_body"), ""

        custom_break_activity = self._custom_message_text("break_activity")
        if custom_break_activity:
            return self.t("custom_break_activity_title"), custom_break_activity, ""

        keys = [
            ("activity_distance", "activity_distance_body"),
            ("activity_hands", "activity_hands_body"),
            ("activity_walk", "activity_walk_body"),
            ("activity_chest", "activity_chest_body"),
            ("activity_twist", "activity_twist_body"),
            ("activity_neck", "activity_neck_body"),
            ("activity_ankle", "activity_ankle_body"),
            ("activity_quiet", "activity_quiet_body"),
        ]
        if self.engine.block_seconds <= 5 * 60:
            keys = keys[:4] + [keys[-1]]
        key_title, key_body = keys[self.activity_index % len(keys)]
        self.activity_index += 1
        notes: list[str] = []
        if key_title in {"activity_chest", "activity_twist", "activity_neck", "activity_ankle"}:
            notes.append(self.t("movement_note"))
        return self.t(key_title), self.t(key_body), " ".join(notes)

    def _water_is_due(self) -> bool:
        raw = self.settings_data.get("last_water_prompt", "")
        if not raw:
            return True
        try:
            return datetime.now() - datetime.fromisoformat(raw) >= timedelta(minutes=90)
        except ValueError:
            return True

    def _drink_is_due(self) -> bool:
        choice = self.settings_data.get("drink_choice", "off")
        if choice not in {"coffee", "tea", "either"}:
            return False
        if self.settings_data.get("last_drink_day") == date.today().isoformat():
            return False
        cutoff = self.settings_data.get("caffeine_cutoff", "12:00")
        return valid_clock_time(cutoff) and datetime.now().strftime("%H:%M") < cutoff

    def _snack_is_due(self) -> bool:
        if not self.settings_data.get("snack_reminders"):
            return False
        if self.settings_data.get("last_snack_day") == date.today().isoformat():
            return False
        return float(self.history.day().get("work_seconds", 0.0)) >= 3 * 60 * 60

    def _lunch_is_due(self) -> bool:
        if not self.settings_data.get("lunch_enabled"):
            return False
        if self.settings_data.get("last_lunch_day") == date.today().isoformat():
            return False
        lunch_time = self.settings_data.get("lunch_time", "12:30")
        return valid_clock_time(lunch_time) and datetime.now().strftime("%H:%M") >= lunch_time

    def _next_break_text(self) -> str:
        target = datetime.now() + timedelta(seconds=max(0.0, self.engine.remaining_seconds))
        return self.t("next_break", time=target.strftime("%H:%M"))

    def _tick(self) -> None:
        if self.exiting:
            return
        self._drain_tray_actions()
        if self.exiting:
            return
        current_day = date.today().isoformat()
        if self.settings_data.get("work_counter_day") != current_day:
            self.engine.work_since_long_break = 0.0
            self.settings_data["work_counter_day"] = current_day
            self.settings_data["work_since_long_break"] = 0.0
        now = time.monotonic()
        wall_now = time.time()
        elapsed = max(0.0, now - self.last_tick)
        wall_elapsed = max(0.0, wall_now - self.last_wall_tick)
        self.last_tick = now
        self.last_wall_tick = wall_now
        if self.dialog_open:
            self.root.after(250, self._tick)
            return
        # On most Windows systems the monotonic clock advances across suspend,
        # but the wall-clock cross-check also catches platforms where it does not.
        # A large manual wall-clock jump is handled conservatively as a gap too.
        wall_only_gap = max(0.0, wall_elapsed - elapsed)
        detected_gap = max(elapsed, wall_elapsed)
        if self.engine.counting and (elapsed > SLEEP_GAP_SECONDS or wall_only_gap > SLEEP_GAP_SECONDS):
            self._forget_time_correction()
            self.engine.pause()
            self.pause_started_at = datetime.now().astimezone() - timedelta(seconds=detected_gap)
            self._record_event(
                "timer_paused_after_gap",
                gap_seconds=round(detected_gap, 3),
                monotonic_gap_seconds=round(elapsed, 3),
                wall_gap_seconds=round(wall_elapsed, 3),
            )
            self._save_all()
            self.humor_hint = "after_sleep_gap"
            self._render()
            self._notify(self._t_plain("wake_title"), self._t_plain("wake_body"))
        else:
            result = self.engine.tick(elapsed, int(self.settings_data["long_break_minutes"]) * 60)
            self.history.add_seconds("work", result.work_seconds)
            self.history.add_seconds("break", result.break_seconds)
            if result.event:
                self._forget_time_correction()
                self.humor_hint = None
                self._record_event(
                    result.event,
                    work_elapsed_seconds=round(self.engine.work_block_elapsed, 3),
                    break_elapsed_seconds=round(self.engine.break_elapsed, 3),
                )
                self.current_activity = None if result.event == "work_due" else self.current_activity
                self._save_all()
                self._render()
                if result.event == "work_due":
                    self._notify(
                        self._t_plain("break_due"),
                        self._t_plain(
                            "work_complete_notification",
                            work=self.engine.planned_work_minutes,
                            rest=self._suggested_break_minutes(),
                        ),
                    )
                else:
                    self._notify(self._t_plain("rest_complete"), self._t_plain("break_complete_notification"))
            else:
                self._update_dynamic()

        self._check_timed_personal_reminder()
        self._sync_tray_state()
        self._sync_mini_timer()
        if (
            not self.exiting
            and self._palette_for_state().get("name") != self.colors.get("name")
            and not self._other_popups_open()
        ):
            self._render()
        if self.engine.counting and now - self.last_save >= SAVE_INTERVAL_SECONDS:
            self._save_runtime()
            self.last_save = now
        if not self.exiting:
            self.root.after(250, self._tick)

    def _update_dynamic(self) -> None:
        if not self.timer_canvas:
            return
        self._update_timer_ring()
        if self.engine.state == TimerState.WORK_DUE and self.dynamic_break_button:
            try:
                text = self.t("start_break", minutes=self._suggested_break_minutes())
                if str(self.dynamic_break_button.cget("text")) != text:
                    self.dynamic_break_button.configure(text=text)
            except tk.TclError:
                pass

    def _check_timed_personal_reminder(self) -> None:
        if not self.settings_data.get("personal_enabled") or self.settings_data.get("personal_mode") != "daily_time":
            return
        if not self.engine.active or self.personal_popup_open:
            return
        now = datetime.now()
        if self.personal_snooze_until and now < self.personal_snooze_until:
            return
        if self.settings_data.get("last_personal_day") == now.date().isoformat():
            return
        target = self.settings_data.get("personal_time", "10:00")
        if valid_clock_time(target) and now.strftime("%H:%M") >= target:
            self._open_personal_popup()

    def _open_personal_popup(self) -> None:
        self.personal_popup_open = True
        popup = self._popup(self.t("personal_reminder"), 430, 275)
        frame = ttk.Frame(popup, padding=22)
        frame.pack(fill="both", expand=True)
        text = self.settings_data.get("personal_text", "").strip() or self.t("default_personal")
        details = self.settings_data.get("personal_details", "").strip()
        self._label(frame, text=self.t("personal_reminder"), style="Section.TLabel").pack(anchor="w")
        self._label(frame, text=text, wraplength=370).pack(anchor="w", pady=(9, 0))
        if details:
            self._label(frame, text=details, style="Muted.TLabel", wraplength=370).pack(anchor="w", pady=(6, 0))

        def complete() -> None:
            self.settings_data["last_personal_day"] = date.today().isoformat()
            self.settings_store.save()
            self.personal_popup_open = False
            popup.destroy()

        def later() -> None:
            self.personal_snooze_until = datetime.now() + timedelta(minutes=10)
            self.personal_popup_open = False
            popup.destroy()

        def closed() -> None:
            self.personal_snooze_until = datetime.now() + timedelta(minutes=10)
            self.personal_popup_open = False
            popup.destroy()

        popup.protocol("WM_DELETE_WINDOW", closed)
        self._primary_button(frame, self.t("done"), complete).pack(fill="x", pady=(18, 0))
        ttk.Button(frame, text=self.t("remind_later"), command=later).pack(fill="x", pady=(7, 0))
        ttk.Button(frame, text=self.t("skip"), style="Secondary.TButton", command=complete).pack(pady=(7, 0))
        self._play_sound()

    # ------------------------------------------------------------------ mini timer

    def _x11(self) -> Any | None:
        if platform.system() != "Linux":
            return None
        helper = getattr(self, "_x11_helper", None)
        if helper is None and not getattr(self, "_x11_failed", False):
            try:
                helper = X11Helper()
                self._x11_helper = helper
            except Exception:
                LOGGER.info("X11 helper unavailable; using Tk window state only", exc_info=True)
                self._x11_failed = True
                helper = None
        return helper

    def _main_window_minimized(self) -> bool:
        try:
            state = self.root.state()
            if state in {"iconic", "withdrawn"} or not self.root.winfo_viewable():
                return True
        except tk.TclError:
            return False
        helper = self._x11()
        if helper is not None:
            try:
                return bool(helper.is_minimized(int(self.root.winfo_id())))
            except Exception:
                LOGGER.debug("X11 minimized check failed", exc_info=True)
        return False

    def _mini_timer_wanted(self) -> bool:
        if self.exiting or not self.settings_data.get("mini_timer") or not self.engine.active:
            return False
        minimized = self._main_window_minimized()
        if minimized != getattr(self, "_last_minimized_logged", None):
            self._last_minimized_logged = minimized
            LOGGER.info("Main window minimized=%s (Tk state %s)", minimized, self.root.state())
        if not minimized:
            self.mini_dismissed = False
            return False
        return not self.mini_dismissed

    def _sync_mini_timer(self) -> None:
        if not self._mini_timer_wanted():
            self._close_mini_timer()
            return
        if self.mini_window is None:
            self._create_mini_timer()
        self._draw_mini_timer()

    def _close_mini_timer(self) -> None:
        window, self.mini_window, self.mini_canvas = self.mini_window, None, None
        if window is not None:
            try:
                window.destroy()
            except tk.TclError:
                pass

    def _mini_values(self) -> tuple[str, str, float, str]:
        """Time text, logical status text, remaining fraction and colour key."""
        engine = self.engine
        state = engine.state
        paused = state == TimerState.PAUSED
        base = engine.paused_from if paused and engine.paused_from else state
        overtime = base in {TimerState.WORK_DUE, TimerState.REST_COMPLETE}
        if overtime:
            time_text = "+" + format_duration(engine.overtime_seconds)
            fraction = 0.0
        else:
            time_text = format_duration(engine.remaining_seconds)
            fraction = engine.remaining_seconds / max(1.0, engine.block_seconds)
        status_key = {
            TimerState.WORKING: "focus_title",
            TimerState.WORK_DUE: "break_due",
            TimerState.RESTING: "break_title",
            TimerState.REST_COMPLETE: "rest_complete",
        }.get(base, "focus_title")
        if paused:
            return time_text, self._t_plain("mini_paused"), fraction, "muted"
        if overtime:
            return time_text, self._t_plain(status_key), fraction, "warm"
        colour = "timeline_break" if base == TimerState.RESTING else "accent"
        return time_text, self._t_plain(status_key), fraction, colour

    def _mini_pixel_size(self) -> int:
        return self._px(MINI_SIZES.get(str(self.settings_data.get("mini_size", "medium")), 140))

    def _mini_alpha(self, hover: bool = False) -> float:
        if hover and self.settings_data.get("mini_hover_solid", True):
            return 1.0
        return float(MINI_OPACITY.get(str(self.settings_data.get("mini_opacity", "light")), 0.85))

    def _set_mini_alpha(self, hover: bool) -> None:
        window = self.mini_window
        if window is None:
            return
        try:
            window.attributes("-alpha", self._mini_alpha(hover))
        except tk.TclError:
            pass

    def _create_mini_timer(self) -> None:
        size = self._mini_pixel_size()
        window = tk.Toplevel(self.root)
        window.withdraw()
        window.overrideredirect(True)
        windows = platform.system() == "Windows"
        key = "#010203"
        try:
            window.attributes("-topmost", True)
        except tk.TclError:
            pass
        matte = None
        if windows:
            try:
                window.attributes("-transparentcolor", key)
                matte = key
            except tk.TclError:
                matte = None
        self.mini_matte = matte
        canvas = tk.Canvas(
            window, width=size, height=size, background=matte or self.colors["face"],
            highlightthickness=0, borderwidth=0, cursor="hand2",
        )
        canvas.pack(fill="both", expand=True)
        self.mini_window = window
        self.mini_canvas = canvas
        self.mini_size_px = size
        self._mini_cache_key = None
        self.mini_items = (
            canvas.create_image(size / 2, size / 2),
            canvas.create_text(size / 2, size / 2 - size * 0.045, text="", fill=self.colors["text"]),
            canvas.create_text(size / 2, size / 2 + size * 0.15, text="", fill=self.colors["muted"]),
        )
        for sequence, handler in (
            ("<ButtonPress-1>", self._mini_press),
            ("<B1-Motion>", self._mini_motion),
            ("<ButtonRelease-1>", self._mini_release),
            ("<Button-3>", self._mini_menu),
            ("<Enter>", lambda _event: self._set_mini_alpha(True)),
            ("<Leave>", lambda _event: self._set_mini_alpha(False)),
        ):
            canvas.bind(sequence, handler)

        position = self._mini_position(size, size)
        LOGGER.info("Mini timer at %s (monitors %s)", position, self._mini_monitors())
        window.geometry(f"{size}x{size}{position}")
        window.deiconify()
        self._set_mini_alpha(False)
        try:
            window.update_idletasks()
            window.lift()
        except tk.TclError:
            pass
        helper = self._x11()
        if helper is not None:
            try:
                helper.shape_circle(int(window.wm_frame(), 16), size)
            except Exception:
                LOGGER.debug("Could not make the mini timer round", exc_info=True)

    def _mini_monitors(self) -> list[tuple[int, int, int, int]]:
        helper = self._x11()
        if helper is None:
            return []
        try:
            return helper.monitors()
        except Exception:
            LOGGER.info("Monitor list unavailable", exc_info=True)
            return []

    def _mini_position(self, width: int, height: int) -> str:
        """Saved place if it is on a visible monitor, else bottom right of the
        monitor that shows the main window.

        With several monitors the X11 "screen" is one large box that can
        include empty areas, so its bottom-right corner may not be visible.
        """
        saved = str(self.settings_data.get("mini_timer_position", ""))
        match = re.fullmatch(r"([+-]\d+)([+-]\d+)", saved)
        monitors = self._mini_monitors()
        try:
            main_x = self.root.winfo_rootx() + self.root.winfo_width() // 2
            main_y = self.root.winfo_rooty() + self.root.winfo_height() // 2
        except tk.TclError:
            main_x = main_y = 0

        def containing(px: int, py: int) -> tuple[int, int, int, int] | None:
            for box in monitors:
                bx, by, bw, bh = box
                if bx <= px < bx + bw and by <= py < by + bh:
                    return box
            return None

        if monitors:
            if match:
                x, y = int(match.group(1)), int(match.group(2))
                box = containing(x + width // 2, y + height // 2)
                if box is not None:
                    bx, by, bw, bh = box
                    x = max(bx, min(x, bx + bw - width))
                    y = max(by, min(y, by + bh - height))
                    return f"+{x}+{y}"
            bx, by, bw, bh = containing(main_x, main_y) or monitors[0]
            return f"+{bx + bw - width - self._px(32)}+{by + bh - height - self._px(96)}"

        if platform.system() == "Linux" and not match:
            # No monitor list: put it inside the area the main window used.
            try:
                x = self.root.winfo_rootx() + self.root.winfo_width() - width - self._px(16)
                y = self.root.winfo_rooty() + self.root.winfo_height() - height - self._px(16)
                return f"+{max(0, x)}+{max(0, y)}"
            except tk.TclError:
                pass
        screen_w = self.root.winfo_screenwidth()
        screen_h = self.root.winfo_screenheight()
        if match:
            x, y = int(match.group(1)), int(match.group(2))
        else:
            x = screen_w - width - self._px(32)
            y = screen_h - height - self._px(96)
        x = max(0, min(x, screen_w - width))
        y = max(0, min(y, screen_h - height))
        return f"+{x}+{y}"

    def _draw_mini_timer(self) -> None:
        canvas = self.mini_canvas
        if canvas is None:
            return
        try:
            time_text, status, fraction, colour_key = self._mini_values()
            c = self.colors
            size = int(getattr(self, "mini_size_px", self._mini_pixel_size()))
            ring = c.get(colour_key, c["accent"])
            overtime = colour_key == "warm"
            ring_alpha = 255
            if overtime and self.settings_data.get("mini_signal", True):
                # A slow, quiet pulse of the ring when the planned time is over.
                phase = (time.monotonic() % 3.0) / 3.0
                ring_alpha = int(110 + 145 * (0.5 + 0.5 * math.cos(2 * math.pi * phase)))
                ring_alpha = int(round(ring_alpha / 29.0) * 29)
            key = (round(fraction * 600), ring, ring_alpha, c.get("name"), size)
            image_item, time_item, status_item = self.mini_items
            if key != getattr(self, "_mini_cache_key", None):
                self._mini_cache_key = key
                data = dial_image_data(
                    size,
                    fraction=fraction,
                    ring=ring,
                    wedge=blend_colour(ring, c["face"], 0.2 if c.get("is_dark") else 0.14),
                    face=c["face"],
                    border=c["border"],
                    track=c["track"],
                    tick=c["tick"],
                    tick_major=blend_colour(c["muted"], c["face"], 0.7),
                    overtime=overtime,
                    ring_alpha=ring_alpha,
                    matte=getattr(self, "mini_matte", None),
                )
                if data is not None:
                    image = tk.PhotoImage(master=self.root, data=data)
                    canvas.itemconfigure(image_item, image=image)
                    canvas._mini_image = image
                elif not canvas.find_withtag("mini_plain"):
                    g = dial_geometry(size)
                    centre = size / 2.0
                    canvas.create_oval(
                        centre - g["face_r"], centre - g["face_r"], centre + g["face_r"], centre + g["face_r"],
                        fill=c["face"], outline=c["border"], tags=("mini_plain",),
                    )
                    canvas.tag_lower("mini_plain")
            canvas.itemconfigure(
                time_item, text=time_text, fill=c["warm"] if overtime else (c["muted"] if colour_key == "muted" else c["text"]),
                font=self._font("mono", max(9, self._dial_font_size(time_text, size)), bold=True),
            )
            canvas.itemconfigure(
                status_item, text=self._rtl_display(status), fill=c["muted"] if colour_key == "muted" else ring,
                font=self._font("ui", 7 if size < self._px(130) else 8),
            )
        except tk.TclError:
            self._close_mini_timer()

    def _mini_press(self, event: Any) -> None:
        window = self.mini_window
        if window is None:
            return
        self.mini_drag = {
            "x": event.x_root,
            "y": event.y_root,
            "left": window.winfo_x(),
            "top": window.winfo_y(),
            "moved": False,
        }

    def _mini_motion(self, event: Any) -> None:
        window = self.mini_window
        drag = self.mini_drag
        if window is None or not drag:
            return
        dx, dy = event.x_root - drag["x"], event.y_root - drag["y"]
        if not drag["moved"] and abs(dx) + abs(dy) < 4:
            return
        drag["moved"] = True
        try:
            window.geometry(f"+{drag['left'] + dx}+{drag['top'] + dy}")
        except tk.TclError:
            pass

    def _mini_release(self, _event: Any) -> None:
        drag, self.mini_drag = self.mini_drag, {}
        window = self.mini_window
        if window is None or not drag:
            return
        if drag.get("moved"):
            try:
                self.settings_data["mini_timer_position"] = f"+{window.winfo_x()}+{window.winfo_y()}"
                self.settings_store.save()
            except (tk.TclError, OSError):
                LOGGER.debug("Could not save the mini timer position", exc_info=True)
            return
        self._close_mini_timer()
        self._show_main_window(int(getattr(_event, "time", 0) or 0))

    def _mini_menu(self, event: Any) -> None:
        if self.mini_window is None:
            return
        menu = tk.Menu(self.mini_window, tearoff=False)
        menu.add_command(label=self.t("mini_open"), command=lambda: (self._close_mini_timer(), self._show_main_window()))
        if self.engine.state == TimerState.PAUSED:
            menu.add_command(label=self.t("resume"), command=self._toggle_pause)
        elif self.engine.counting:
            menu.add_command(label=self.t("pause"), command=self._toggle_pause)
        menu.add_separator()
        menu.add_command(label=self.t("mini_hide"), command=self._dismiss_mini_timer)
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

    def _dismiss_mini_timer(self) -> None:
        self.mini_dismissed = True
        self._close_mini_timer()

    def _tray_status_text(self) -> str:
        # Native Windows menus understand logical RTL text themselves.  Do not
        # pass the visually reordered strings used by Tk into the tray menu.
        state = self.engine.state
        if state == TimerState.WORKING:
            return f"{self._t_plain('working')} · {format_duration(self.engine.remaining_seconds)}"
        if state == TimerState.WORK_DUE:
            return f"{self._t_plain('break_due')} · {format_duration(self.engine.overtime_seconds)}"
        if state == TimerState.RESTING:
            return f"{self._t_plain('break_title')} · {format_duration(self.engine.remaining_seconds)}"
        if state == TimerState.REST_COMPLETE:
            return f"{self._t_plain('rest_complete')} · {format_duration(self.engine.overtime_seconds)}"
        if state == TimerState.PAUSED:
            if self.engine.paused_from in {TimerState.WORK_DUE, TimerState.REST_COMPLETE}:
                value = self.engine.overtime_seconds
            else:
                value = self.engine.remaining_seconds
            return f"{self._t_plain('paused')} · {format_duration(value)}"
        return self._t_plain("tray_status_ready")

    def _sync_tray_state(self) -> None:
        if not self.tray.available:
            return
        self.tray.update(status=self._tray_status_text())

    def _show_main_window(self, timestamp: int = 0) -> None:
        if self.exiting:
            return
        try:
            self.root.deiconify()
            self.root.state("normal")
            self.root.lift()
            self.root.after(50, self.root.focus_force)
        except tk.TclError:
            pass
        helper = self._x11() if platform.system() == "Linux" else None
        if helper is None:
            return
        try:
            window_id = int(self.root.winfo_id())
            minimized = helper.is_minimized(window_id)
            viewable = helper.is_viewable(window_id)
            LOGGER.info(
                "Restore requested: minimized=%s viewable=%s tk_state=%s time=%s",
                minimized, viewable, self.root.state(), timestamp,
            )
            # Ask the window manager in the standard way (as a dock or app
            # switcher does), then check and fall back if it did not work.
            helper.activate(window_id, timestamp)
            self.root.after(300, self._ensure_main_window_shown)
        except Exception:
            LOGGER.info("Could not restore the main window through X11", exc_info=True)

    def _ensure_main_window_shown(self, attempt: int = 1) -> None:
        """If the window is still hidden, unmap and map it again.

        A freshly mapped window is shown by every window manager, even when
        it ignored the activation request.
        """
        helper = self._x11()
        if helper is None or self.exiting:
            return
        try:
            window_id = int(self.root.winfo_id())
            minimized = helper.is_minimized(window_id)
            viewable = helper.is_viewable(window_id)
            LOGGER.info("Restore check %s: minimized=%s viewable=%s", attempt, minimized, viewable)
            if not minimized and viewable is not False:
                return
            if attempt > 2:
                LOGGER.warning("Main window could not be restored automatically")
                return
            self.root.withdraw()

            def show_again() -> None:
                try:
                    self.root.deiconify()
                    self.root.lift()
                    self.root.focus_force()
                except tk.TclError:
                    return
                self.root.after(400, lambda: self._ensure_main_window_shown(attempt + 1))

            self.root.after(120, show_again)
        except Exception:
            LOGGER.info("Could not map the main window again", exc_info=True)

    def _drain_tray_actions(self) -> None:
        while True:
            try:
                action = self.tray_actions.get_nowait()
            except queue.Empty:
                return
            if action == "open":
                self._show_main_window()
            elif action == "pause":
                if self.engine.state in {
                    TimerState.WORKING,
                    TimerState.WORK_DUE,
                    TimerState.RESTING,
                    TimerState.PAUSED,
                }:
                    self._toggle_pause()
            elif action == "break":
                if self.engine.is_work_context:
                    self._take_break()
            elif action == "finish":
                if self.engine.active:
                    self._finish_session()
            elif action == "about":
                self._show_main_window()
                self.root.after(120, self._open_about)
            elif action == "quit":
                self._quit()
                return
            self._sync_tray_state()

    def _hide_to_tray(self, *, explain: bool = False) -> bool:
        """Hide an active session after the user presses the title-bar Close button."""
        if self.exiting or not self.tray.available:
            return False
        try:
            self._save_all()
            self.root.withdraw()
        except tk.TclError:
            return False

        LOGGER.info("Main window hidden to system tray")
        if explain and not bool(self.settings_data.get("tray_close_notice_shown_v015", False)):
            # A tray balloon is less disruptive than a modal dialog and also
            # points the user toward the notification-area icon. Use a new
            # friends-build flag so long-time testers see this explanation once
            # even if an older release already showed the legacy notice.
            if self.tray.notify(self.t("tray_notice_title"), self.t("tray_notice_body")):
                self.settings_data["tray_close_notice_shown_v015"] = True
                self.settings_store.save()
        return True

    def _notify(self, title: str | None = None, body: str | None = None) -> None:
        self._play_sound()
        if title and body and self.settings_data.get("notifications", True):
            if self.tray.available:
                self.tray.notify(title, body)
            elif platform.system() == "Linux":
                self._linux_notify(title, body)
        try:
            self._flash_window()
            if title:
                self.root.title(f"{title} | {self.t('app_title')}")
                self.root.after(4000, lambda: self.root.title(self.t("app_title")))
        except tk.TclError:
            pass

    def _linux_notify(self, title: str, body: str) -> bool:
        """Send a desktop notification through notify-send, off the Tk thread."""
        if shutil.which("notify-send") is None:
            return False
        command = ["notify-send", f"--app-name={APP_NAME}"]
        icon = ensure_png_icon(self.data_dir / "taktpause.png")
        if icon:
            command.append(f"--icon={icon}")
        command += [str(title)[:200], str(body)[:500]]
        run_in_background(command, timeout=10.0)
        return True

    def _play_sound(
        self,
        force: bool = False,
        style_name: str | None = None,
        custom_path: str | None = None,
        play_twice: bool | None = None,
    ) -> bool:
        """Play the configured reminder sound once or, when enabled, exactly twice.

        WAV repeats use synchronous playback in a daemon worker. That keeps Tk
        responsive and guarantees the second copy starts only after the first one
        finishes instead of overlapping it. Preview can override ``play_twice``
        before the Settings dialog has been saved.
        """
        if not force and not self.settings_data.get("sound"):
            return False
        style_name = style_name or str(self.settings_data.get("sound_style", "gentle"))
        custom_path = custom_path if custom_path is not None else str(self.settings_data.get("custom_sound_path", ""))
        repeat = bool(self.settings_data.get("sound_twice", False)) if play_twice is None else bool(play_twice)
        try:
            if platform.system() == "Windows":
                import winsound

                if style_name == "system":
                    if not repeat:
                        winsound.MessageBeep(winsound.MB_OK)
                        return True

                    def play_system_twice() -> None:
                        try:
                            winsound.MessageBeep(winsound.MB_OK)
                            # MessageBeep duration depends on the Windows sound theme.
                            # A short gap prevents two queued alerts from becoming one.
                            time.sleep(0.35)
                            winsound.MessageBeep(winsound.MB_OK)
                        except (OSError, RuntimeError):
                            LOGGER.exception("Could not repeat the Windows reminder sound")

                    threading.Thread(
                        target=play_system_twice,
                        name="TaktpauseSound",
                        daemon=True,
                    ).start()
                    return True

                if style_name == "custom":
                    sound_path = Path(custom_path).expanduser()
                    if not sound_path.is_file() or sound_path.suffix.lower() != ".wav":
                        return False
                else:
                    sound_path = self.data_dir / "sounds" / "gentle_chime.wav"
                    if not sound_path.is_file():
                        create_gentle_chime(sound_path)

                if not repeat:
                    winsound.PlaySound(
                        str(sound_path),
                        winsound.SND_FILENAME | winsound.SND_ASYNC | winsound.SND_NODEFAULT,
                    )
                    return True

                path_text = str(sound_path)

                def play_wav_twice() -> None:
                    try:
                        flags = winsound.SND_FILENAME | winsound.SND_NODEFAULT
                        winsound.PlaySound(path_text, flags)
                        time.sleep(0.12)
                        winsound.PlaySound(path_text, flags)
                    except (OSError, RuntimeError):
                        LOGGER.exception("Could not repeat reminder WAV")

                threading.Thread(
                    target=play_wav_twice,
                    name="TaktpauseSound",
                    daemon=True,
                ).start()
                return True

            if platform.system() == "Linux":
                sound_path: Path | None = None
                if style_name == "system":
                    sound_path = linux_system_sound_path()
                elif style_name == "custom":
                    candidate = Path(custom_path).expanduser()
                    if not candidate.is_file() or candidate.suffix.lower() != ".wav":
                        return False
                    sound_path = candidate
                if sound_path is None:
                    sound_path = self.data_dir / "sounds" / "gentle_chime.wav"
                    if not sound_path.is_file():
                        create_gentle_chime(sound_path)
                commands = linux_audio_commands(sound_path)
                if commands:
                    play_sound_in_background(commands, repeat=2 if repeat else 1)
                    return True
                LOGGER.warning("No sound player found (paplay, pw-play or aplay)")

            self.root.bell()
            if repeat:
                self.root.after(500, self.root.bell)
            return True
        except (ImportError, OSError, RuntimeError, tk.TclError, wave.Error):
            return False

    def _save_session(self) -> None:
        if not self.engine.active:
            self.session_store.data = {}
        else:
            self.session_store.data = {
                "saved_at": datetime.now().isoformat(timespec="seconds"),
                "task": self.task,
                "session_id": self.session_id,
                "work_block_id": self.work_block_id,
                "activity_index": self.activity_index,
                "engine": self.engine.snapshot(),
            }
        self.session_store.save()

    def _save_runtime(self) -> None:
        """Persist changing timer/history state without rewriting preferences."""
        self.history.save()
        self._save_session()

    def _save_all(self) -> None:
        self.history.save()
        self.settings_data["work_counter_day"] = date.today().isoformat()
        self.settings_data["work_since_long_break"] = self.engine.work_since_long_break
        try:
            if self.root.state() == "normal":
                self.settings_data["window_geometry"] = self.root.geometry()
        except tk.TclError:
            pass
        self.settings_store.save()
        self._save_session()

    def _load_pending_snapshot(self) -> dict[str, Any] | None:
        data = self.session_store.data
        if not data or not isinstance(data.get("engine"), dict):
            return None
        raw_saved = data.get("saved_at")
        if raw_saved:
            try:
                saved = datetime.fromisoformat(str(raw_saved))
                now = datetime.now(saved.tzinfo) if saved.tzinfo is not None else datetime.now()
                if now - saved > timedelta(days=2):
                    return None
            except (TypeError, ValueError):
                LOGGER.warning("Current session has an invalid saved_at value; offering recovery anyway")
        # A valid engine snapshot is more valuable than an optional timestamp.
        # Let the user choose Resume or Discard rather than silently deleting it.
        return data

    def _resume_snapshot(self) -> None:
        if not self.pending_snapshot:
            return
        try:
            saved_engine = self.pending_snapshot["engine"]
            self.engine.restore(saved_engine)
            if "planned_work_minutes" not in saved_engine:
                work, rest = resolve_timing("effort", self.engine.effort, self.settings_data)
                self.engine.planned_work_minutes = work
                self.engine.planned_break_minutes = rest
            if self.engine.state == TimerState.PAUSED:
                self.engine.resume()
            self.break_count = 1 if self.engine.state in {TimerState.RESTING, TimerState.REST_COMPLETE} else 0
            self.task = str(self.pending_snapshot.get("task", ""))
            self.task_var.set(self.task)
            self.effort_var.set(self.engine.effort)
            self.rhythm_key = normalize_rhythm(self.engine.rhythm, self.engine.effort)
            self.engine.rhythm = self.rhythm_key
            self.session_id = str(self.pending_snapshot.get("session_id", "")) or uuid.uuid4().hex
            self.work_block_id = str(self.pending_snapshot.get("work_block_id", "")) or uuid.uuid4().hex
            try:
                self.activity_index = max(0, int(self.pending_snapshot.get("activity_index", self.activity_index)))
            except (TypeError, ValueError):
                self.activity_index = 0
            self.pending_snapshot = None
            self._record_event("session_restored")
            self._save_session()
            self._render()
        except (KeyError, TypeError, ValueError):
            self._discard_snapshot()

    def _discard_snapshot(self) -> None:
        self.pending_snapshot = None
        self.session_store.data = {}
        self.session_store.save()
        self.events.append("saved_session_discarded", version=APP_VERSION)
        self._render()

    def _popup(self, title: str, width: int, height: int) -> Any:
        popup = tk.Toplevel(self.root)
        popup.title(title)
        popup.geometry(f"{self._px(width)}x{self._px(height)}")
        popup.resizable(False, False)
        popup.configure(background=self.colors["bg"])
        popup.transient(self.root)
        popup.after_idle(lambda: self._apply_windows_titlebar(popup))
        popup.after(50, lambda: self._apply_directionality(popup) if popup.winfo_exists() else None)
        return popup

    def _scrollable_tab(self, parent: Any) -> Any:
        container = ttk.Frame(parent)
        container.pack(fill="both", expand=True)
        canvas = tk.Canvas(
            container,
            background=self.colors["bg"],
            highlightthickness=0,
            borderwidth=0,
        )
        scrollbar = ttk.Scrollbar(container, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=scrollbar.set)
        scrollbar.pack(side="right", fill="y")
        canvas.pack(side="left", fill="both", expand=True)
        body = ttk.Frame(canvas, padding=(18, 18, 22, 18))
        window_id = canvas.create_window((0, 0), window=body, anchor="nw")
        body.bind(
            "<Configure>",
            lambda _event: canvas.configure(scrollregion=canvas.bbox("all")),
        )
        canvas.bind(
            "<Configure>",
            lambda event: canvas.itemconfigure(window_id, width=event.width),
        )

        def wheel(event: Any) -> None:
            # Tk 8.6 on Linux reports the wheel as buttons 4 and 5.
            number = getattr(event, "num", None)
            if number == 4:
                canvas.yview_scroll(-1, "units")
            elif number == 5:
                canvas.yview_scroll(1, "units")
            elif getattr(event, "delta", 0):
                canvas.yview_scroll(-1 if event.delta > 0 else 1, "units")

        wheel_events = ("<MouseWheel>", "<Button-4>", "<Button-5>")

        def bind_wheel(_event: Any = None) -> None:
            for sequence in wheel_events:
                self.root.bind_all(sequence, wheel)

        def unbind_wheel(_event: Any = None) -> None:
            for sequence in wheel_events:
                self.root.unbind_all(sequence)

        for sequence in wheel_events:
            canvas.bind(sequence, wheel)
            body.bind(sequence, wheel)
        container.bind("<Enter>", bind_wheel)
        container.bind("<Leave>", unbind_wheel)
        container.bind("<Destroy>", unbind_wheel)
        return body

    def _current_timeline_kind(self) -> str | None:
        if self.engine.state in {TimerState.WORKING, TimerState.WORK_DUE}:
            return "work"
        if self.engine.state == TimerState.RESTING:
            return "break"
        return None

    def _activity_intervals(self, day_key: str) -> list[ActivityInterval]:
        return reconstruct_activity_intervals(
            self.events.records(),
            day_key=day_key,
            live_session_id=self.session_id,
            live_kind=self._current_timeline_kind(),
            now=datetime.now().astimezone(),
        )

    def _raise_existing(self, kind: str) -> bool:
        """Bring an already open dialog to the front instead of opening a second one."""
        window = getattr(self, "_dialogs", {}).get(kind)
        try:
            if window is not None and window.winfo_exists():
                window.deiconify()
                window.lift()
                window.focus_force()
                return True
        except tk.TclError:
            pass
        return False

    def _remember_dialog(self, kind: str, window: Any) -> None:
        if not hasattr(self, "_dialogs"):
            self._dialogs = {}
        self._dialogs[kind] = window

    def _open_stats(self) -> None:
        if self._raise_existing("stats"):
            return
        popup = self._popup(self.t("stats_title"), 880, 840)
        self._remember_dialog("stats", popup)
        popup.attributes("-topmost", False)
        popup.resizable(True, True)
        popup.minsize(self._px(720), self._px(640))
        frame = self._scrollable_tab(popup)
        self._label(frame, text=self.t("stats_title"), style="Title.TLabel").pack(anchor="w")
        self._hairline(frame, pady=(14, 0))

        # Four numbers first, like a dashboard: the selected day, the week,
        # the daily average and the typical block.  No scores, no judgement.
        stats_canvas = tk.Canvas(
            frame, height=self._px(104), background=self.colors["bg"], highlightthickness=0, borderwidth=0,
        )
        stats_canvas.pack(fill="x", pady=(16, 18))
        stats_data: dict[str, Any] = {}

        today_value = date.today()
        current_week_start = today_value - timedelta(days=today_value.weekday())
        all_records_for_bounds = self.events.records()
        available_dates: list[date] = []
        for day_key in self.history.data.get("days", {}):
            try:
                available_dates.append(date.fromisoformat(str(day_key)))
            except ValueError:
                pass
        for record in all_records_for_bounds:
            parsed = parse_event_datetime(record.get("at"))
            if parsed is not None:
                available_dates.append(parsed.date())
        earliest_date = min(available_dates) if available_dates else today_value
        earliest_week_start = earliest_date - timedelta(days=earliest_date.weekday())
        selected_week_start = current_week_start
        week_days: list[str] = []
        selectable_days: list[str] = []
        week_intervals: dict[str, list[ActivityInterval]] = {}
        week_task_summaries: list[dict[str, Any]] = []
        selected_task_key: str | None = None
        task_label_to_key: dict[str, str | None] = {self.t("all_tasks"): None}
        task_key_to_label: dict[str, str] = {}

        weekday_keys = (
            "week_mon", "week_tue", "week_wed", "week_thu",
            "week_fri", "week_sat", "week_sun",
        )
        activity_day_var = tk.StringVar(value=today_value.isoformat())
        week_range_var = tk.StringVar(value="")
        task_filter_var = tk.StringVar(value=self.t("all_tasks"))

        self._label(frame, text=self.t("week_overview"), style="Section.TLabel").pack(anchor="w")
        self._label(
            frame,
            text=self.t("week_overview_note"),
            style="Muted.TLabel",
            wraplength=740,
        ).pack(anchor="w", pady=(4, 8))

        week_nav = ttk.Frame(frame)
        week_nav.pack(fill="x", pady=(0, 8))
        previous_week_button = ttk.Button(
            week_nav,
            text=self.t("week_previous"),
            style="Secondary.TButton",
        )
        previous_week_button.pack(side="left")
        self._label(
            week_nav,
            textvariable=week_range_var,
            style="Mono.TLabel",
        ).pack(side="left", padx=10)
        next_week_button = ttk.Button(
            week_nav,
            text=self.t("week_next"),
            style="Secondary.TButton",
        )
        next_week_button.pack(side="left")

        filter_row = ttk.Frame(frame)
        filter_row.pack(fill="x", pady=(0, 8))
        self._label(filter_row, text=self.t("task_filter"), style="Muted.TLabel").pack(side="left")
