        def save_settings() -> None:
            numeric_keys = [
                "custom_work_minutes", "custom_break_minutes",
                "long_break_after", "long_break_minutes",
                "lunch_minutes",
            ]
            try:
                numeric_values = {key: int(variables[key].get()) for key in numeric_keys}
                if any(value < 1 or value > 180 for value in numeric_values.values()):
                    raise ValueError
            except ValueError:
                self._run_dialog(
                    messagebox.showerror,
                    self.t("settings_title"),
                    self.t("invalid_number"),
                    parent=popup,
                )
                return
            clock_value = variables["personal_time"].get().strip()
            caffeine_cutoff = variables["caffeine_cutoff"].get().strip()
            lunch_time = variables["lunch_time"].get().strip()
            if not all(valid_clock_time(value) for value in (clock_value, caffeine_cutoff, lunch_time)):
                self._run_dialog(
                    messagebox.showerror,
                    self.t("settings_title"),
                    self.t("invalid_time"),
                    parent=popup,
                )
                return
            selected_sound = reverse_sounds[variables["sound_style_label"].get()]
            selected_sound_path = Path(variables["custom_sound_path"].get().strip()).expanduser()
            if selected_sound == "custom" and (
                not selected_sound_path.is_file() or selected_sound_path.suffix.lower() != ".wav"
            ):
                self._run_dialog(
                    messagebox.showerror,
                    self.t("sound_style"),
                    self.t("sound_file_missing"),
                    parent=popup,
                )
                return
            self.settings_data.update(numeric_values)
            for key in ("sound", "sound_twice", "notifications", "humor", "water_reminders", "personal_enabled", "snack_reminders", "lunch_enabled"):
                self.settings_data[key] = bool(variables[key].get())
            self.settings_data["personal_text"] = variables["personal_text"].get().strip()
            self.settings_data["personal_details"] = variables["personal_details"].get().strip()
            self.settings_data["personal_mode"] = reverse_modes[variables["personal_mode_label"].get()]
            self.settings_data["personal_time"] = clock_value
            self.settings_data["sound_style"] = selected_sound
            self.settings_data["custom_sound_path"] = variables["custom_sound_path"].get().strip()
            self.settings_data["drink_choice"] = reverse_drinks[variables["drink_label"].get()]
            self.settings_data["caffeine_cutoff"] = caffeine_cutoff
            self.settings_data["lunch_time"] = lunch_time
            self.settings_data["language"] = reverse_languages[variables["language_label"].get()]
            self.settings_data["theme"] = reverse_themes[variables["theme_label"].get()]
            self.settings_data["mini_timer"] = bool(variables["mini_timer"].get())
            self.settings_data["mini_size"] = reverse_sizes.get(variables["mini_size_label"].get(), "medium")
            self.settings_data["mini_opacity"] = reverse_opacity.get(variables["mini_opacity_label"].get(), "light")
            for key in ("mini_hover_solid", "mini_signal", "state_colours"):
                self.settings_data[key] = bool(variables[key].get())
            self.settings_data["adaptive_timing"] = bool(variables["adaptive_timing"].get())
            self.adaptive_var.set(self.settings_data["adaptive_timing"])
            self._close_mini_timer()
            persist_message_editor()
            self.custom_messages.replace_data(message_working)
            self.settings_store.save()
            self.custom_messages.save()
            self.recent_custom_messages.clear()
            popup.destroy()
            self.lang = self._resolved_language()
            self.tray.set_menu_labels(self._tray_menu_labels())
            self._apply_style()
            self._set_window_icon()
            self.root.title(self.t("app_title"))
            self.current_activity = None
            self._build_shell()
            self._render()
            self._sync_tray_state()

