        # 0.16.3 regression: correcting a late Break and then a late Resume in
        # the same cycle must keep history exact. The first correction can be
        # longer than the planned break; its whole confirmed duration is counted
        # as break, while only time after that correction becomes untracked
        # overtime.
        correction_app.engine = TimerEngine()
        correction_app.history.data = {"days": {}}
        correction_app.last_time_correction = None
        correction_app.work_block_id = "double-correction-work"
        correction_app.engine.start_work(35, "moderate", planned_break_minutes=5, rhythm="balanced")
        correction_app.engine.tick(2400, 900)  # 40 min of work counted
        correction_app.history.add_seconds("work", 2400)
        assert correction_app._apply_time_correction("break", 10) is None
        correction_days = correction_app.history.data["days"]
        assert len(correction_days) == 1
        correction_day = next(iter(correction_days.values()))
        assert abs(float(correction_day["work_seconds"]) - 1800.0) < 1e-6
        assert abs(float(correction_day["break_seconds"]) - 600.0) < 1e-6
        assert correction_app.engine.state == TimerState.REST_COMPLETE
        assert abs(correction_app.engine.break_elapsed - 600.0) < 1e-6
        assert abs(correction_app.engine.overtime_seconds) < 1e-6
        correction_app.last_time_correction = None
        correction_app.engine.tick(240, 900)  # four later minutes are untracked overtime
        assert correction_app._apply_time_correction("work", 6) is None
        correction_days = correction_app.history.data["days"]
        assert len(correction_days) == 1
        correction_day = next(iter(correction_days.values()))
        assert abs(float(correction_day["work_seconds"]) - 2160.0) < 1e-6
        assert abs(float(correction_day["break_seconds"]) - 480.0) < 1e-6

        # Returning to work early preserves the pre-break work counter for an
        # ordinary break, but a sufficiently long preceding break resets it.
        correction_app.engine.start_break(20)
        correction_app.engine.work_counter_at_break_start = 720.0
        correction_app.engine.work_since_long_break = 720.0
        correction_app.engine.tick(600, 900)
        correction_app.history.add_seconds("break", 600)
        assert correction_app._apply_time_correction("work", 2) is None
        assert correction_app.engine.work_counter_at_break_start == 720.0
        correction_app.last_time_correction = None

        correction_app.engine.work_since_long_break = 720.0
        correction_app.engine.start_break(30)
        correction_app.engine.work_counter_at_break_start = 720.0
        correction_app.engine.tick(1000, 900)
        correction_app.history.add_seconds("break", 1000)
        assert correction_app._apply_time_correction("work", 1) is None
        assert abs(correction_app.engine.work_since_long_break - 60.0) < 1e-6

