def acquire_linux_instance_lock(data_dir: Path) -> tuple[Any | None, bool]:
    """Hold an advisory lock in the data folder for as long as the app runs."""
    try:
        import fcntl
    except ImportError:
        return None, True
    try:
        data_dir.mkdir(parents=True, exist_ok=True)
        handle = open(data_dir / "taktpause.lock", "a+", encoding="utf-8")
    except OSError:
        return None, True
    try:
        fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        handle.close()
        return None, False
    except OSError:
        handle.close()
        return None, True
    return handle, True


def acquire_single_instance() -> tuple[Any | None, bool]:
    """Prevent two copies from writing the same local files."""
    if platform.system() == "Linux":
        return acquire_linux_instance_lock(application_data_dir())
    if platform.system() != "Windows":
        return None, True
    try:
        import ctypes

        kernel32 = ctypes.windll.kernel32
        kernel32.CreateMutexW.argtypes = [ctypes.c_void_p, ctypes.c_bool, ctypes.c_wchar_p]
        kernel32.CreateMutexW.restype = ctypes.c_void_p
        kernel32.CloseHandle.argtypes = [ctypes.c_void_p]
        kernel32.CloseHandle.restype = ctypes.c_bool
        handle = kernel32.CreateMutexW(None, False, "Local\\Taktpause-4A37C865")
        if not handle:
            return None, True
        if kernel32.GetLastError() == 183:
            kernel32.CloseHandle(handle)
            return None, False
        return handle, True
    except (AttributeError, OSError):
        return None, True


def release_single_instance(handle: Any | None) -> None:
    if handle is not None and platform.system() == "Linux":
        try:
            handle.close()
        except OSError:
            pass
        return
    if handle and platform.system() == "Windows":
        try:
            import ctypes

            ctypes.windll.kernel32.CloseHandle.argtypes = [ctypes.c_void_p]
            ctypes.windll.kernel32.CloseHandle.restype = ctypes.c_bool
            ctypes.windll.kernel32.CloseHandle(handle)
        except (AttributeError, OSError):
            pass


def show_already_running_message() -> None:
    language = system_language()
    message = TEXT.get(language, TEXT.get("en", {})).get(
        "already_running", "Taktpause is already running."
    )
    if platform.system() == "Windows":
        try:
            import ctypes

            ctypes.windll.user32.MessageBoxW(None, message, APP_NAME, 0x00000040)
            return
        except (AttributeError, OSError):
            pass
    if platform.system() == "Linux" and tk is not None and messagebox is not None:
        try:
            shown = message
            if language == "fa" and arabic_reshaper is not None and bidi_get_display is not None:
                shown = bidi_get_display(arabic_reshaper.reshape(message), base_dir="R")
            root = tk.Tk(className=APP_NAME)
            root.withdraw()
            linux_startup_complete()
            messagebox.showinfo(APP_NAME, shown, parent=root)
            root.destroy()
            return
        except tk.TclError:
            pass
    print(message, file=sys.stderr)


def main() -> int:
    if "--self-test" in sys.argv:
        run_self_test()
        return 0
    if tk is None:
        print(
            "This Python installation does not include Tkinter. On Windows, "
            "install Python from python.org and keep the optional Tcl/Tk component enabled. "
            "On Ubuntu or Debian: sudo apt install python3-tk",
            file=sys.stderr,
        )
        if TK_IMPORT_ERROR:
            print(f"Details: {TK_IMPORT_ERROR} (Python {sys.executable})", file=sys.stderr)
        return 1
    instance_handle, first_instance = acquire_single_instance()
    if not first_instance:
        show_already_running_message()
        return 0
    try:
        TaktpauseApp().run()
    except tk.TclError as exc:
        print(f"Could not open the graphical interface: {exc}", file=sys.stderr)
        return 1
    finally:
        release_single_instance(instance_handle)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())


